	[11006] = {
		id = 11006,
		fmt = '7. If the leader does not log in for 5 consecutive days, leadership transfers to the most active and highest-contributing player in this order: vice-leader ] member.  ',
		fmt_ma = '7. Jika ketua tidak log masuk selama 5 hari berturut-turut, jawatan ketua akan dipindahkan kepada pemain yang layak dari segi log masuk dan sumbangan tertinggi mengikut keutamaan: timbalan ketua ] ahli, dan bertukar tempat dengan mereka.  ',
		fmt_en = '7. If the leader does not log in for 5 consecutive days, leadership transfers to the most active and highest-contributing player in this order: vice-leader ] member.  ',
		fmt_in = '7. Jika pemimpin guild tidak login selama 5 hari berturut-turut, posisi pemimpin guild akan dialihkan ke pemain yang memenuhi syarat login dan memiliki kontribusi tertinggi sesuai prioritas: wakil pemimpin ] anggota, dan akan bertukar posisi dengan mereka.',
		fmt_th = '7. หากหัวหน้าไม่ล็อกอินติดต่อกัน 5 วัน ตำแหน่งจะโอนไปให้ผู้เล่นที่มีคุณสมบัติเข้าเกณฑ์และมีคะแนนกิลด์สูงสุด โดยเรียงลำดับ: รองหัวหน้า ] สมาชิก',
		fmt_ph = '7. Kapag hindi naka-log in ang Guild Leader sa loob ng 5 magkakasunod na araw, ang posisyon ay ililipat sa miyembrong may pinaka-mataas na kontribusyon ayon sa priority: Vice Leader ] Miyembro  ',
		fmt_vn = '7. Nếu hội trưởng không đăng nhập trong 5 ngày liên tiếp, vị trí hội trưởng sẽ được chuyển giao cho người chơi đáp ứng điều kiện đăng nhập và có cống hiến cao nhất theo thứ tự ưu tiên: phó hội trưởng ] thành viên, và đổi vị trí với họ.'
	},
	[11007] = {
