	[13001] = {
		id = 13001,
		fmt = '1. Players can complete the open activity list within 8 days from event start, with tasks open for 5 days. After 8 days, the event ends.  ',
		fmt_ma = '1. Pemain boleh selesaikan senarai aktiviti yang dibuka dalam 5 hari pertama dalam tempoh 8 hari sejak acara bermula, selepas 8 hari acara akan ditutup secara automatik.  ',
		fmt_en = '1. Players can complete the open activity list within 8 days from event start, with tasks open for 5 days. After 8 days, the event ends.  ',
		fmt_in = '1. Pemain dapat menyelesaikan daftar kegiatan yang dibuka dalam 5 hari pertama dalam waktu 8 hari sejak acara dimulai, setelah 8 hari, acara akan ditutup secara otomatis.',
		fmt_th = '1. ผู้เล่นสามารถทำกิจกรรมใน 5 วันแรก ภายใน 8 วันนับจากเริ่มกิจกรรม หลังครบ 8 วัน กิจกรรมจะปิด',
		fmt_ph = '1. Maaaring kumpletuhin ng manlalaro ang activity list na bukas sa loob ng unang 5 araw sa loob ng 8 araw mula simula ng event, pagkatapos ng 8 araw ay awtomatikong magsasara ang event  ',
		fmt_vn = '1. Người chơi có thể hoàn thành danh sách hoạt động mở trong 5 ngày đầu tiên trong vòng 8 ngày kể từ khi sự kiện bắt đầu, sau 8 ngày sự kiện sẽ tự động đóng lại.'
	},
	[13002] = {
		id = 13002,
		fmt = '2. Completing all objectives grants full rewards, or on day 8, you can claim rewards based on current progress.  ',
