	},
	[14001] = {
		id = 14001,
		fmt = 'An angelic pet with six pairs of glowing wings, clad in pure white holy attire. It represents perfect goodness and is known as the pet of happiness. To evil, it is merciless, attacking relentlessly until the enemy is destroyed.  ',
		fmt_ma = 'Seekor haiwan peliharaan malaikat dengan enam pasang sayap yang bersinar terang, tubuh diliputi oleh pakaian putih suci. Ini adalah lambang kebaikan sempurna, dikenali sebagai haiwan peliharaan pembawa kebahagiaan. Terhadap kejahatan, ia sangat dingin dan akan terus menyerang sehingga musuh dimusnahkan sepenuhnya.  ',
		fmt_en = 'An angelic pet with six pairs of glowing wings, clad in pure white holy attire. It represents perfect goodness and is known as the pet of happiness. To evil, it is merciless, attacking relentlessly until the enemy is destroyed.  ',
		fmt_in = 'Seekor hewan peliharaan malaikat dengan enam pasang sayap yang bersinar terang, tubuhnya tertutup pakaian putih suci yang murni. Ini adalah perwujudan dari kebaikan sempurna, yang dikenal sebagai hewan peliharaan pembawa kebahagiaan. Untuk kejahatan, ia sangat dingin, tidak akan berhenti menyerang hingga musuh dihancurkan sepenuhnya.',
		fmt_th = 'สัตว์เลี้ยงเทวทูตมี 6 คู่ปีกสว่างไสว ร่างกายคลุมด้วยชุดขาวบริสุทธิ์ เป็นตัวแทนแห่งความดี เรียกว่าสัตว์เลี้ยงนำโชค ต่อต้านความชั่วร้ายอย่างเย็นชา จะโจมตีจนศัตรูถูกทำลายสิ้น',
		fmt_ph = 'Isang pet na anghel na may anim na pares ng makinang na pakpak, buong katawan ay nakasuot ng dalisay na puting kasuotan. Ito ang sagisag ng perpektong kabutihan, kilala bilang pet na nagdadala ng kaligayahan. Para sa kasamaan, ito’y sobrang malamig at walang tigil na aatake hanggang sa ganap na mapuksa ang kaaway  ',
		fmt_vn = 'Một thú cưng thiên sứ với sáu đôi cánh tỏa sáng rực rỡ, cơ thể được bao phủ bởi trang phục thuần trắng thánh khiết. Đây là hiện thân của sự thiện hoàn hảo, được gọi là thú cưng mang lại hạnh phúc. Đối với cái ác, nó vô cùng lạnh lùng, sẽ không ngừng tấn công cho đến khi hoàn toàn tiêu diệt kẻ địch.'
	},
	[14002] = {
		id = 14002,
		fmt = 'Heaven\'s Fist: Uses a giant golden fist to deal heavy damage to all enemies, with a 30% chance to reduce 300 rage from each target and 15% chance to control them.  ',
		fmt_ma = 'Tumbukan Syurga: Menggunakan tumbukan gergasi berwarna emas yang bercahaya untuk memberi kerosakan besar kepada semua musuh, dengan 30% peluang mengurangkan 300 kemarahan setiap sasaran dan 15% peluang mengawal musuh.  ',
		fmt_en = 'Heaven\'s Fist: Uses a giant golden fist to deal heavy damage to all enemies, with a 30% chance to reduce 300 rage from each target and 15% chance to control them.  ',
		fmt_in = 'Kekuatan Surga: Menggunakan tinju raksasa yang bersinar emas untuk memberikan kerusakan besar kepada semua musuh, dengan 30% kemungkinan mengurangi 300 energi amarah setiap target, dan 15% kemungkinan mengontrol target.',
		fmt_th = 'สิทธิ์แห่งสวรรค์: ใช้หมัดทองคำขนาดใหญ่โจมตีศัตรูทั้งหมด มีโอกาส 30% ลดเกจโกรธเป้าหมาย 300 และ 15% โอกาสควบคุมเป้าหมาย',
		fmt_ph = 'Langit na Kamao: Gumagamit ng higanteng ginintuang kamao upang magdulot ng malaking pinsala sa lahat ng kaaway, may 30% na tsansa na bawasan ng 300 fury ng bawat target, at 15% na tsansa na ma-stun ang target  ',
		fmt_vn = 'Quyền Thiên Đường: Sử dụng nắm đấm khổng lồ phát sáng vàng kim gây sát thương lớn lên toàn bộ kẻ địch, có 30% xác suất giảm 300 nộ khí của mỗi mục tiêu, và 15% xác suất khống chế mục tiêu.'
	},
	[14003] = {
		id = 14003,
		fmt = 'Holy Staff: Uses the angelic pet’s staff to deal heavy damage to a single enemy, with a 20% chance to seal them, dealing an extra 60% damage to defense-type enemies.  ',
