	[19001] = {
		id = 19001,
		fmt = '#C0xFFF5D6#1. Players can send and receive red packets in the guild red packet. Limited quantity, hurry!  ',
		fmt_ma = '#C0xFFF5D6#1. Pemain boleh menghantar dan menerima angpau dalam sistem angpau persatuan. Jumlah angpau terhad, cepat-cepatlah ya.  ',
		fmt_en = '#C0xFFF5D6#1. Players can send and receive red packets in the guild red packet. Limited quantity, hurry!  ',
