		fmt_th = '#C0xFFF5D6#1. ผู้เล่นสามารถแจกและรับอั่งเปาในกิลด์ จำนวนมีจำกัด รีบกันหน่อยนะ',
		fmt_ph = '#C0xFFF5D6#1. Maaaring magpadala at tumanggap ng red packet sa guild red packet. Limitado ang bilang ng red packet, bilisan mo!  ',
		fmt_vn = '#C0xFFF5D6#1. Người chơi có thể phát và nhận lì xì trong lì xì của bang hội. Số lượng lì xì có hạn, hãy nhanh tay nhé.'
	},
	[19002] = {
		id = 19002,
		fmt = '#C0xFFF5D6#2. Guild red packets auto-refresh daily at 19:00.',
		fmt_ma = '#C0xFFF5D6#2. Angpau persatuan akan diperbaharui secara automatik setiap hari pada pukul 19:00',
		fmt_en = '#C0xFFF5D6#2. Guild red packets auto-refresh daily at 19:00.',
		fmt_in = '#C0xFFF5D6#2. Guild red envelopes will automatically refresh every day at 19:00.',
		fmt_th = '#C0xFFF5D6#2. อั่งเปากิลด์จะรีเฟรชอัตโนมัติทุกวันเวลา 19:00',
		fmt_ph = '#C0xFFF5D6#2. Ang guild red packet ay awtomatikong nire-reset tuwing 19:00 araw-araw',
		fmt_vn = '#C0xFFF5D6#2. Hồng bao bang hội tự động làm mới mỗi ngày lúc 19:00'
	},
	[19003] = {
		id = 19003,
		fmt = '#C0xFFF5D6#3. Upgrading Red Packet Tech in the Research Institute increases quantity and value of guild red packets.',
		fmt_ma = '#C0xFFF5D6#3. Meningkatkan tahap teknologi Angpau di Institut Penyelidikan akan meningkatkan bilangan dan nilai Angpau Persatuan.',
		fmt_en = '#C0xFFF5D6#3. Upgrading Red Packet Tech in the Research Institute increases quantity and value of guild red packets.',
		fmt_in = '#C0xFFF5D6#3. Upgrading the Red Envelope Technology in the Research Institute can increase the quantity and value of Guild Red Envelopes.',
		fmt_th = '#C0xFFF5D6#3. อัปเกรดเทคโนโลยีอั่งเปาที่ศูนย์วิจัย จะเพิ่มจำนวนและมูลค่าอั่งเปา',
		fmt_ph = '#C0xFFF5D6#3. Ang pag-upgrade ng technology level ng Red Packet sa Research Institute ay maaaring magpataas ng dami at halaga ng guild red packet',
		fmt_vn = '#C0xFFF5D6#3. Nâng cấp cấp độ công nghệ Hồng Bao của Viện Nghiên cứu có thể tăng số lượng và giá trị của Hồng Bao Bang Hội.'
	},
	[19004] = {
		id = 19004,
		fmt = '#C0xFFF5D6#4. Sending and receiving red packets is voluntary.',
		fmt_ma = '#C0xFFF5D6#4. Pemain bebas memilih untuk menghantar dan menerima angpau.',
		fmt_en = '#C0xFFF5D6#4. Sending and receiving red packets is voluntary.',
		fmt_in = '#C0xFFF5D6#4. Distributing and receiving red envelopes is done at the discretion of the player.',
		fmt_th = '#C0xFFF5D6#4. แจกและรับอั่งเปาเป็นการกระทำโดยผู้เล่นเอง',
		fmt_ph = '#C0xFFF5D6#4. Ang pagpapadala at pagtanggap ng red packet ay kusang-loob ng mga manlalaro',
		fmt_vn = '#C0xFFF5D6#4. Phát và nhận lì xì do người chơi tự chọn thực hiện.'
	},
	[19005] = {
		id = 19005,
		fmt = '#C0xFFF5D6#5. Players can receive their own red packets.',
		fmt_ma = '#C0xFFF5D6#5. Pemain yang menghantar angpau juga boleh menerima angpau mereka sendiri.',
		fmt_en = '#C0xFFF5D6#5. Players can receive their own red packets.',
		fmt_in = '#C0xFFF5D6#5. Players who distribute red envelopes can receive red envelopes from themselves.',
		fmt_th = '#C0xFFF5D6#5. ผู้เล่นที่แจกอั่งเปาสามารถรับของตัวเองได้',
		fmt_ph = '#C0xFFF5D6#5. Ang manlalarong nagpapadala ng red packet ay maaari ring tumanggap ng sarili nilang red packet',
