	},
	[19006] = {
		id = 19006,
		fmt = '#C0xFFF5D6#6. Red packet amounts are random, help out passersby!  ',
		fmt_ma = '#C0xFFF5D6#6. Nilai dalam angpau akan diagihkan secara rawak, tolong bantu orang tua melintas jalan ya.  ',
		fmt_en = '#C0xFFF5D6#6. Red packet amounts are random, help out passersby!  ',
		fmt_in = '#C0xFFF5D6#6. The value in the red envelopes will be received randomly, so be sure to help others more often!  ',
		fmt_th = '#C0xFFF5D6#6. มูลค่าในอั่งเปาจะสุ่มได้รับ ช่วยผู้สูงวัยด้วยนะ',
		fmt_ph = '#C0xFFF5D6#6. Ang halaga sa red packet ay random, sana ay mas maraming matulungan na matanda sa daan  ',
		fmt_vn = '#C0xFFF5D6#6. Giá trị trong lì xì sẽ được nhận ngẫu nhiên, hãy giúp đỡ người già qua đường nhiều hơn nhé.'
	},
	[19007] = {
		id = 19007,
		fmt = '#C0xFFF5D6#7. Increasing VIP level increases send/receive attempts.',
		fmt_ma = '#C0xFFF5D6#7. Meningkatkan tahap VIP akan meningkatkan bilangan kali menghantar dan menerima angpau.',
		fmt_en = '#C0xFFF5D6#7. Increasing VIP level increases send/receive attempts.',
