	[19008] = {
		id = 19008,
		fmt = '#C0xFFF5D6#8. Red packets remain for 24 hours; after that, unclaimed funds disappear with no refund.  ',
		fmt_ma = '#C0xFFF5D6#8. Angpau yang dihantar oleh pemain akan disimpan selama 24 jam, selepas itu ia akan hilang secara automatik dan baki tidak akan dipulangkan.  ',
		fmt_en = '#C0xFFF5D6#8. Red packets remain for 24 hours; after that, unclaimed funds disappear with no refund.  ',
		fmt_in = '#C0xFFF5D6#8. Red envelopes that players distribute will be held for 24 hours; after this time, they will disappear, and the remaining amount will not be refunded.',
		fmt_th = '#C0xFFF5D6#8. อั่งเปาที่แจกจะคงอยู่ 24 ชม. หลังจากนั้นจะหายไป และเงินคงเหลือจะไม่คืน',
		fmt_ph = '#C0xFFF5D6#8. Ang red packet na ipinadala ng manlalaro ay mananatili sa loob ng 24 na oras, pagkatapos nito ay awtomatikong mawawala at ang natitirang halaga ay hindi maibabalik  ',
		fmt_vn = '#C0xFFF5D6#8. Lì xì mà người chơi phát ra sẽ được giữ trong 24 giờ, sau thời gian này sẽ tự động biến mất và số tiền còn lại sẽ không được hoàn trả.'
	},
	[20001] = {
		id = 20001,
		fmt = 'Welcome to Guild War! Each season lasts one week with generous rewards. Call your allies and fight together!',
		fmt_ma = 'Selamat datang ke Perang Persatuan, Perang ini berlangsung satu minggu setiap musim, setiap musim akan ada ganjaran lumayan. Cepat panggil rakan seperjuangan anda dan berjuang bersama!  ',
		fmt_en = 'Welcome to Guild War! Each season lasts one week with generous rewards. Call your allies and fight together!',
		fmt_in = 'Welcome to the Guild Battle! Guild Battles last for one week per season, and there are generous rewards each season. Call your allies and fight together!',
		fmt_th = 'ยินดีต้อนรับสู่ศึกกิลด์ ศึกกิลด์ใช้เวลา 1 สัปดาห์ต่อซีซั่น มีรางวัลมากมาย ชวนเพื่อนมาสู้ไปด้วยกัน!',
		fmt_ph = 'Maligayang pagdating sa Guild War, ang Guild War ay tumatagal ng isang linggo bawat season, bawat season ay may magagandang gantimpala. Tara, tawagin mo na ang mga ka-guild mo, sabay tayong lumaban!  ',
		fmt_vn = 'Chào mừng đến với Công Hội Chiến, Công Hội Chiến kéo dài một tuần một mùa, mỗi mùa đều có phần thưởng hậu hĩnh đó nha. Mau gọi chiến hữu của bạn, cùng nhau chiến đấu nào!'
	},
	[20002] = {
		id = 20002,
		fmt = '1. Guild War is divided into two stages: qualifiers and finals. Qualifiers last 4 days (Tuesday to Friday), finals last 1 day (Saturday).  ',
		fmt_ma = '1. Perang Persatuan dibahagikan kepada dua peringkat: pusingan kelayakan dan pusingan akhir. Pusingan kelayakan berlangsung selama 4 hari (Selasa hingga Jumaat), pusingan akhir berlangsung selama 1 hari (Sabtu).  ',
		fmt_en = '1. Guild War is divided into two stages: qualifiers and finals. Qualifiers last 4 days (Tuesday to Friday), finals last 1 day (Saturday).  ',
		fmt_in = '1. Guild Wars are divided into two phases: the qualifiers and the finals. The qualifiers last for 4 days (from Tuesday to Friday), and the finals last for 1 day (Saturday).  ',
		fmt_th = '1. แบ่งเป็น 2 ช่วง: รอบคัดเลือก และรอบชิง รอบคัดเลือก 4 วัน (อังคาร-ศุกร์) รอบชิง 1 วัน (เสาร์)',
		fmt_ph = '1. Ang Guild War ay hinati sa dalawang yugto: preliminaries at finals. Ang preliminaries ay tumatagal ng 4 na araw (Martes hanggang Biyernes), ang finals ay isang araw (Sabado).  ',
		fmt_vn = '1. Hội chiến bang hội được chia thành hai giai đoạn: vòng loại và vòng chung kết. Vòng loại kéo dài 4 ngày (từ thứ Ba đến thứ Sáu), vòng chung kết kéo dài 1 ngày (thứ Bảy).'
	},
