	[20005] = {
		id = 20005,
		fmt = '4. Registration requirement: players with Commander level 40+ and Guild level 4+ can register. Only registered players can participate that day.',
		fmt_ma = '4. Syarat pendaftaran: Hanya pemain dengan tahap komander 40 ke atas dan tahap persatuan 4 ke atas boleh mendaftar. Hanya selepas mendaftar barulah boleh menyertai perlawanan hari itu.',
		fmt_en = '4. Registration requirement: players with Commander level 40+ and Guild level 4+ can register. Only registered players can participate that day.',
		fmt_in = '4. Registration conditions: Only players whose command level is 40 or higher and guild level is 4 or higher can register. You can only participate in the battle of the day if you have registered.',
		fmt_th = '4. เงื่อนไข: ผู้เล่นมีเลเวลผู้บัญชาการ ≥40 และเลเวลากิลด์ ≥4 เท่านั้นถึงสมัครได้ ต้องสมัครถึงจะร่วมแข่งได้',
		fmt_ph = '4. Kondisyon sa pagpaparehistro: Tanging mga manlalaro na may commander level na 40 pataas at guild level na 4 pataas ang maaaring magparehistro. Kailangang magparehistro upang makasali sa laban ng araw.',
		fmt_vn = '4. Điều kiện đăng ký: Chỉ những người chơi có cấp chỉ huy đạt từ 40 trở lên và cấp công hội đạt từ 4 trở lên mới có thể đăng ký. Chỉ khi đăng ký, bạn mới có thể tham gia trận đấu trong ngày.'
	},
	[20006] = {
		id = 20006,
		fmt = '5. VIP 3+ players will be auto-registered by the system 30 mins before battle start.',
		fmt_ma = '5. Pemain dengan tahap VIP 3 ke atas akan didaftarkan secara automatik oleh sistem 30 minit sebelum perlawanan bermula.',
		fmt_en = '5. VIP 3+ players will be auto-registered by the system 30 mins before battle start.',
		fmt_in = '5. Players with VIP level 3 or higher will be automatically registered by the system 30 minutes before the battle begins.',
		fmt_th = '5. ผู้เล่น VIP 3 ขึ้นไป ระบบจะสมัครอัตโนมัติล่วงหน้า 30 นาที',
		fmt_ph = '5. Ang mga manlalaro na may VIP level 3 pataas ay awtomatikong ire-register ng system 30 minuto bago magsimula ang laban.',
		fmt_vn = '5. Người chơi có VIP cấp 3 trở lên sẽ được hệ thống tự động đăng ký trước khi trận đấu bắt đầu nửa giờ.'
	},
	[21001] = {
		id = 21001,
		fmt = '1. During qualifiers, from Tue to Thu, hero attributes are restricted. Check restrictions on registration or formation screen. No restriction on Friday.  ',
		fmt_ma = '1. Dalam pusingan kelayakan, dari Selasa hingga Khamis akan ada had atribut wira yang boleh bertanding. Pemain boleh semak had ini di antara muka pendaftaran atau susun atur formasi hari itu. Pada hari Jumaat tiada had atribut.  ',
		fmt_en = '1. During qualifiers, from Tue to Thu, hero attributes are restricted. Check restrictions on registration or formation screen. No restriction on Friday.  ',
		fmt_in = '1. In the qualifiers, from Tuesday to Thursday, there will be attribute limits on the heroes deployed. Players can check these limits in the registration interface or formation interface for the day. On Friday, there will be no attribute limits for heroes.  ',
		fmt_th = '1. รอบคัดเลือก (อังคาร-พฤหัส) จะจำกัดคุณสมบัติตัวละคร ตรวจสอบได้ในหน้าสมัครหรือจัดทีม วันศุกร์ไม่จำกัด',
		fmt_ph = '1. Sa preliminaries, mula Martes hanggang Huwebes ay may limitasyon sa attributes ng mga hero na maaaring lumaban. Maaaring tingnan ang limitasyon sa registration interface o battle setup interface. Sa Biyernes, walang limitasyon sa attributes ng hero.  ',
		fmt_vn = '1. Trong vòng loại, từ thứ ba đến thứ năm sẽ giới hạn thuộc tính của các anh hùng ra trận. Cụ thể, người chơi có thể kiểm tra giới hạn này tại giao diện đăng ký hoặc giao diện bố trận trong ngày. Riêng thứ sáu sẽ không giới hạn thuộc tính của anh hùng;'
	},
	[21002] = {
		id = 21002,
		fmt = '2. On restricted days, heroes with matching attribute can join. Heroes of same evolution line can only be used once per day.  ',
		fmt_ma = '2. Dalam pusingan beratribut terhad, hanya perlu satu atribut sesuai sahaja untuk layak bertanding. Wira dalam satu garis evolusi hanya boleh digunakan sekali sehari.  ',
		fmt_en = '2. On restricted days, heroes with matching attribute can join. Heroes of same evolution line can only be used once per day.  ',
		fmt_in = '2. In rounds with attribute limits, as long as a hero has one suitable attribute, they can participate in the battle of the day. Heroes from the same evolution line can only be used once per day.  ',
