	[21004] = {
		id = 21004,
		fmt = '4. If first team is defeated, second team continues the battle.  ',
		fmt_ma = '4. Bila pasukan pertama kalah, pasukan kedua boleh terus bertarung dalam pusingan seterusnya.  ',
