	[21005] = {
		id = 21005,
		fmt = '5. Free-for-all mode: you’ll face players from other guilds (if too few left, you may fight your own guild to determine ranking).  ',
		fmt_ma = '5. Mod perlawanan adalah pertempuran bebas, anda akan melawan pemain dari persatuan lain (bila pemain tinggal terlalu sedikit, anda mungkin bertarung dengan ahli persatuan sendiri untuk tentukan ranking individu).  ',
		fmt_en = '5. Free-for-all mode: you’ll face players from other guilds (if too few left, you may fight your own guild to determine ranking).  ',
		fmt_in = '5. The battle mode is a free-for-all, and you will encounter players from other guilds (if there are too few players left, you may have to battle your own guild members to determine individual rankings).  ',
		fmt_th = '5. โหมดต่อสู้แบบผสม เจอผู้เล่นจากกิลด์อื่น (ถ้าเหลือน้อย อาจเจอเพื่อนกิลด์ตัวเองเพื่อจัดอันดับ)',
		fmt_ph = '5. Ang laban ay free-for-all, maaari kang makalaban ng mga manlalaro mula sa ibang guild (kung kaunti na lang ang natitirang players, maaari kang makalaban ng sarili mong guildmates para sa personal ranking).  ',
		fmt_vn = '5. Hình thức thi đấu là chế độ hỗn chiến, bạn sẽ gặp người chơi từ các bang hội khác (khi số lượng người chơi còn lại quá ít, bạn có thể phải giao chiến với thành viên trong bang hội của mình để xác định thứ hạng cá nhân);'
	},
	[21006] = {
		id = 21006,
