	},
	[21009] = {
		id = 21009,
		fmt = '9. Final winner increases guild points and battle stars; stars control attribute bonuses in finals.',
		fmt_ma = '9. Pemain menang akhir akan tambah mata persatuan dan Bintang Pertempuran, Bintang Pertempuran boleh digunakan untuk kawal atribut tambahan dalam perlawanan akhir.  ',
		fmt_en = '9. Final winner increases guild points and battle stars; stars control attribute bonuses in finals.',
