	},
	[22001] = {
		id = 22001,
		fmt = '1. Top 8 guilds with highest cumulative points after 4 days enter finals. Qualified players auto-registered.',
		fmt_ma = '1. Dalam 4 hari pertama perlawanan, 8 persatuan dengan markah terkumpul tertinggi akan layak ke pusingan akhir, semua pemain yang layak akan didaftarkan automatik semasa persiapan akhir.  ',
		fmt_en = '1. Top 8 guilds with highest cumulative points after 4 days enter finals. Qualified players auto-registered.',
		fmt_in = '1. In the first 4 days of fighting, the top 8 guilds with the highest accumulated points will enter the finals. All eligible players will automatically register during the preparation period for the finals.  ',
		fmt_th = '1. ใน 4 วันแรกของการแข่งขัน 8 กิลด์ที่มีแต้มสะสมสูงสุดจะเข้าสู่รอบชิง ผู้เล่นที่มีคุณสมบัติตรงตามเงื่อนไขจะลงทะเบียนอัตโนมัติในช่วงเตรียมรอบชิง',
		fmt_ph = '1. Sa unang 4 na araw ng preliminaries, ang top 8 guilds na may pinakamataas na points ay papasok sa finals. Ang lahat ng qualified players ay auto-register sa finals.  ',
		fmt_vn = '1.Trong 4 ngày giao tranh đầu tiên, 8 bang hội có điểm tích lũy cao nhất sẽ được vào vòng chung kết, tất cả người chơi đáp ứng đủ điều kiện tham gia sẽ tự động đăng ký trong thời gian chuẩn bị cho vòng chung kết;'
	},
	[22002] = {
