	[22004] = {
		id = 22004,
		fmt = '4. Finals mode: each guild can deploy 3 teams, each team up to 4 heroes.  ',
		fmt_ma = '4. Mod perlawanan akhir adalah giliran bertempur antara guild, pemain boleh guna 3 formasi wira, setiap formasi boleh ada maksimum 4 wira.  ',
