		fmt_vn = '4. Chế độ chiến đấu trong trận chung kết là đánh luân phiên giữa các bang hội, người chơi có thể sử dụng 3 đội hình anh hùng để thi đấu, mỗi đội hình tối đa có 4 anh hùng ra trận;'
	},
	[22005] = {
		id = 22005,
		fmt = '5. Battles between guilds: winning team continues, losing team eliminated until one guild remains.  ',
		fmt_ma = '5. Dalam pertarungan antara dua guild, pasukan lawan bertempur ikut turutan. Pasukan menang terus bertarung, pasukan kalah tersingkir hingga semua pasukan dari satu guild dikalahkan dan guild satu lagi menang.  ',
		fmt_en = '5. Battles between guilds: winning team continues, losing team eliminated until one guild remains.  ',
		fmt_in = '5. In the battle between two guilds, the teams will fight in order. The winning team will continue to the next match, and the losing team will be eliminated until all teams from one guild are completely defeated, and the other guild wins.  ',
		fmt_th = '5. การสู้แต่ละกิลด์ ทีมจะสู้ตามลำดับ ทีมชนะสู้ต่อ ทีมแพ้ถูกคัดออกจนกว่าทุกทีมกิลด์ใดกิลด์หนึ่งแพ้หมด',
		fmt_ph = '5. Sa laban ng dalawang guilds, ang mga teams ay lalabanan ayon sa order. Ang nanalong team ay magpapatuloy, ang talo ay eliminated hanggang maubos ang teams ng isang guild at ang guild na natira ang mananalo.  ',
		fmt_vn = '5. Trong trận chiến giữa hai bang hội, các đội sẽ thi đấu theo thứ tự đối đầu. Đội chiến thắng sẽ tiếp tục tham gia trận đấu tiếp theo, đội thua sẽ bị loại khỏi danh sách đối đầu cho đến khi tất cả các đội của một bang hội bị tiêu diệt hoàn toàn và bang hội còn lại chiến thắng;'
	},
	[22006] = {
		id = 22006,
		fmt = '6. Winning guild progresses to next match against other winners, until champion is determined.  ',
		fmt_ma = '6. Guild yang menang boleh terus bertarung dengan guild pemenang lain, hingga juara ditemui.  ',
		fmt_en = '6. Winning guild progresses to next match against other winners, until champion is determined.  ',
		fmt_in = '6. Winning guilds can continue to participate in matches with other victorious guilds until the champion is determined.',
		fmt_th = '6. กิลด์ชนะจะเจอกิลด์ชนะอื่นต่อไปจนหาผู้ชนะสุดท้าย',
		fmt_ph = '6. Ang winning guilds ay magpapatuloy sa susunod na laban hanggang matukoy ang champion.',
		fmt_vn = '6. Các hội quán chiến thắng có thể tiếp tục tham gia các trận đấu sau đó với các hội quán chiến thắng khác, cho đến khi tìm ra nhà vô địch;'
	},
	[22007] = {
		id = 22007,
		fmt = '7. Pet states persist throughout finals; HP not restored, dead heroes stay dead.  ',
		fmt_ma = '7. Status haiwan peliharaan dikekalkan sepanjang pusingan akhir, walaupun menang, darah dan wira mati tidak akan dipulihkan untuk perlawanan seterusnya.  ',
		fmt_en = '7. Pet states persist throughout finals; HP not restored, dead heroes stay dead.  ',
		fmt_in = '7. Pet statuses will remain the same throughout the finals. Even if a team wins, when facing the next victorious guild, the hero’s health will not recover, and dead heroes will not revive.  ',
		fmt_th = '7. สถานะสัตว์เลี้ยงคงเดิมตลอดรอบชิง เลือดไม่ฟื้น ตัวตายไม่คืนชีพ',
		fmt_ph = '7. Ang pet status ay mananatili sa finals, kahit manalo ka, ang HP ng heroes ay hindi magre-recover at ang patay na hero ay hindi mabubuhay.  ',
		fmt_vn = '7. Trạng thái thú cưng sẽ được giữ nguyên trong toàn bộ vòng chung kết, ngay cả khi chiến thắng, khi đối đầu với công hội chiến thắng tiếp theo, máu của tướng sẽ không hồi phục và tướng đã chết cũng sẽ không sống lại.'
	},
	[22008] = {
		id = 22008,
		fmt = '8. After final match, guilds receive large reward points based on rank.  ',
		fmt_ma = '8. Selepas perlawanan akhir selesai, guild akan menerima sejumlah besar markah ganjaran berdasarkan ranking.  ',
