		fmt_vn = '1. Trong thời gian vòng loại, mỗi ngày công hội giành chiến thắng cuối cùng sẽ nhận được một ngôi sao chiến đấu;'
	},
	[22102] = {
		id = 22102,
		fmt = '2. Before finals start, Guild Master/Vice can use battle stars to set attribute and stat bonuses for finals.  ',
		fmt_ma = '2. Sebelum pusingan akhir bermula, pemimpin guild (Ketua/Timbalan Ketua) boleh gunakan Bintang Pertempuran untuk tetapkan atribut dan nilai kekuatan tambahan untuk perlawanan akhir.  ',
		fmt_en = '2. Before finals start, Guild Master/Vice can use battle stars to set attribute and stat bonuses for finals.  ',
