	[22201] = {
		id = 22201,
		fmt = '1. Throughout Guild War, all first-time deployed heroes in each round gain buffs to attack, defense, speed, etc.  ',
		fmt_ma = '1. Sepanjang Perang Persatuan, setiap giliran pertempuran, semua wira yang pertama kali masuk formasi akan dapat buff atribut seperti serangan, pertahanan, kelajuan, dan lain-lain.  ',
		fmt_en = '1. Throughout Guild War, all first-time deployed heroes in each round gain buffs to attack, defense, speed, etc.  ',
		fmt_in = '1. During the Guild War, every hero participating in the battle for the first time will receive a certain amount of buffs in attributes like attack, defense, speed, etc.  ',
		fmt_th = '1. ระหว่างศึกกิลด์ ทุกตัวที่เข้าร่วมทีมครั้งแรกจะได้บัฟเพิ่มโจมตี ป้องกัน ความเร็ว ฯลฯ',
		fmt_ph = '1. Sa buong Guild War, sa bawat laban, lahat ng hero na unang beses sumali sa team ay makakatanggap ng buff sa attack, defense, speed, atbp.  ',
		fmt_vn = '1.Trong suốt thời gian diễn ra Công Hội Chiến, mỗi lượt giao tranh, tất cả các anh hùng lần đầu tiên tham gia vào đội hình chiến đấu sẽ nhận được một lượng buff nhất định về thuộc tính tấn công, phòng thủ, tốc độ, v.v.'
	},
	[22202] = {
		id = 22202,
		fmt = '2. Over time, buffs decay, heroes get fatigued, combat power decreases.  ',
		fmt_ma = '2. Bila perlawanan berlanjutan, nilai peningkatan ini akan berkurang, wira akan penat dan prestasi menurun.  ',
		fmt_en = '2. Over time, buffs decay, heroes get fatigued, combat power decreases.  ',
		fmt_in = '2. As the battle progresses, these buffs will gradually decrease, and heroes will become fatigued, reducing their combat effectiveness.  ',
		fmt_th = '2. เมื่อนานไป ค่าบัฟจะลดลง ตัวละครจะล้า ความสามารถลดลง',
		fmt_ph = '2. Habang tumatagal ang laban, unti-unting mababawasan ang buffs at mapapagod ang hero, bababa ang combat effectiveness.  ',
		fmt_vn = '2. Khi trận chiến kéo dài, các chỉ số tăng cường này sẽ giảm dần, và anh hùng sẽ trở nên mệt mỏi, làm giảm khả năng chiến đấu;'
	},
	[22203] = {
		id = 22203,
		fmt = '3. After each battle, hero stats (attack, defense, speed, healing) will further decline.  ',
		fmt_ma = '3. Selepas setiap perlawanan, atribut seperti serangan, pertahanan, kelajuan dan pemulihan pasukan akan terus menurun.  ',
		fmt_en = '3. After each battle, hero stats (attack, defense, speed, healing) will further decline.  ',
		fmt_in = '3. After each battle, the hero\'s attributes such as attack, defense, speed, and healing will continue to decrease.  ',
		fmt_th = '3. ทุกครั้งที่ลงสนาม สถานะต่างๆ จะลดลงต่อเนื่อง',
		fmt_ph = '3. Pagkatapos ng bawat laban, patuloy na bababa ang attack, defense, speed at healing attributes ng mga hero sa team.  ',
		fmt_vn = '3. Sau mỗi lần tham gia chiến đấu, các thuộc tính như tấn công, phòng thủ, tốc độ và lượng hồi máu của anh hùng trong đội sẽ tiếp tục giảm.'
	},
	[22301] = {
		id = 22301,
		fmt = '1. During finals registration (Saturday 9:30-20:50), players can bet on finals result.  ',
