	[22302] = {
		id = 22302,
		fmt = '2. Bet on champion, higher odds yield higher rewards, max 1,000,000 gold.  ',
		fmt_ma = '2. Pertaruhan juara, semakin tinggi kadar taruhan, semakin besar ganjaran, maksimum hingga 1,000,000 emas.  ',
		fmt_en = '2. Bet on champion, higher odds yield higher rewards, max 1,000,000 gold.  ',
		fmt_in = '2. Bet on the champion, the higher the odds, the bigger the reward, with a maximum of 1,000,000 gold.  ',
		fmt_th = '2. เดิมพันทีมชนะ อัตราจ่ายสูง รางวัลมากสุด 1,000,000 โกลด์  ',
		fmt_ph = '2. Maglagay ng taya para sa kampeon, mas mataas ang odds, mas malaki ang premyo, ngunit hindi hihigit sa 1,000,000 ginto;',
