	},
	[22303] = {
		id = 22303,
		fmt = '3. Rewards mailed after finals. Correct bet on champion wins reward based on odds, betting on runner-up refunds half the wager.  ',
		fmt_ma = '3. Selepas perlawanan selesai, ganjaran akan dihantar melalui surat. Taruhan juara yang tepat akan dapat bayaran penuh ikut kadar, taruhan tempat kedua akan dikembalikan separuh.  ',
		fmt_en = '3. Rewards mailed after finals. Correct bet on champion wins reward based on odds, betting on runner-up refunds half the wager.  ',
		fmt_in = '3. After the match ends, rewards will be sent via mail. Betting on the correct champion will reward you with the payout according to the odds, and betting on the runner-up will refund half of the bet amount.  ',
		fmt_th = '3. หลังแข่งเสร็จ รางวัลจะส่งทางจดหมาย ทายถูกได้ตามอัตราจ่าย ทายทีมรองได้คืนครึ่งหนึ่ง',
		fmt_ph = '3. Pagkatapos ng laban, ang mga premyo ay ipapadala sa pamamagitan ng liham. Ang pagtaya sa tamang kampeon ay makakatanggap ng pera ayon sa odds, at ang pagtaya sa pangalawang puwesto ay makakatanggap ng kalahating halaga ng taya.',
		fmt_vn = '3. Sau khi trận đấu kết thúc, phần thưởng sẽ được gửi qua thư. Đặt cược đúng nhà vô địch sẽ nhận được số tiền theo tỷ lệ cược, đặt cược vào đội á quân sẽ được hoàn lại một nửa số tiền cược.'
	},
