	[36001] = {
		id = 36001,
		fmt = '#C0x08ED1F#Evil beasts are plotting to destroy and reshape the pet world, spreading dark gears to control many pets. Every day, they release some pets to cause chaos. To save the pet world, unite and purify the pets controlled by dark gears!',
		fmt_ma = '#C0x08ED1F#Ang masasamang halimaw ay nagbabalak sirain at kontrolin ang mundo ng pet sa pamamagitan ng madidilim na gear. Araw-araw sila\'y nagpapakawala ng pet na nalason ng gear. Sama-sama tayong linisin ang mga ito upang mailigtas ang mundo!',
		fmt_en = '#C0x08ED1F#Evil beasts are plotting to destroy and reshape the pet world, spreading dark gears to control many pets. Every day, they release some pets to cause chaos. To save the pet world, unite and purify the pets controlled by dark gears!',
		fmt_in = '#C0x08ED1F#Binatang buas jahat berusaha menghancurkan dan menguasai dunia hewan peliharaan, menyebarkan roda hitam untuk mengendalikan hewan. Setiap hari mereka akan melepaskan hewan bermasalah, mari bersama melawan mereka!',
		fmt_th = '#C0x08ED1F#สัตว์ประหลาดปีศาจกำลังวางแผนทำลายและสร้างโลกสัตว์เลี้ยงขึ้นใหม่ พวกมันปล่อยเฟืองมืดออกมาควบคุมสัตว์เลี้ยงจำนวนมาก ทุกวันจะมีสัตว์เลี้ยงป่วนถูกปล่อยออกมา เพื่อกอบกู้โลกสัตว์เลี้ยง มาร่วมมือกันกำจัดสัตว์เลี้ยงที่ถูกควบคุมด้วยเฟืองมืดกันเถอะ!',
		fmt_ph = '#C0x08ED1F#Ang mga mabagsik na halimaw ay nagbabalak na sirain at muling likhain ang mundo ng mga alaga, nagkalat sila ng mga itim na gear upang kontrolin ang maraming alaga. Bawat araw, magpapalabas sila ng ilang alaga na nagdudulot ng kaguluhan. Upang mailigtas ang mundo ng mga alaga, magkaisa tayo at linisin ang mga alaga na pinapalakad ng mga itim na gear!',
		fmt_vn = '#C0x08ED1F#Quái thú ác ma đang âm mưu phá hoại và tái tạo thế giới thú cưng, chúng phát tán nhiều bánh răng đen tối để điều khiển hàng loạt thú cưng. Mỗi ngày, chúng sẽ thả ra một số thú cưng gây rối. Để cứu thế giới thú cưng, hãy cùng nhau đoàn kết và thanh tẩy những thú cưng bị bánh răng đen tối điều khiển!'
	},
