	[39006] = {
		id = 39006,
		fmt = '6. VIP3 and above players will be automatically registered 50 minutes before the registration period ends each day.',
		fmt_ma = '6. VIP3 ke atas akan didaftarkan secara automatik 50 minit sebelum tamat masa pendaftaran',
