	[39007] = {
		id = 39007,
		fmt = '7. During battle, each side can fight up to 10 rounds. If no winner is determined at the end of the rounds and both sides have more than 90% HP, the side dealing more damage wins; if either side has less than 90% HP, the side with the higher remaining HP percentage wins.',
		fmt_ma = '7. Dalam pertarungan, maksimum 10 pusingan. Jika tiada pemenang, jika kedua-duanya lebih 90% HP, pihak dengan kerosakan tertinggi menang; jika hanya satu di bawah 90%, pihak dengan HP lebih tinggi menang  ',
		fmt_en = '7. During battle, each side can fight up to 10 rounds. If no winner is determined at the end of the rounds and both sides have more than 90% HP, the side dealing more damage wins; if either side has less than 90% HP, the side with the higher remaining HP percentage wins.',
		fmt_in = '7. Pada fase pertarungan, maksimal 10 ronde. Jika setelah ronde selesai belum ada pemenang, jika HP kedua belah pihak di atas 90%, pihak yang memberikan damage lebih tinggi akan menang; jika ada satu pihak HP di bawah 90%, pihak dengan persentase HP tersisa lebih tinggi akan menang',
		fmt_th = '7. ในช่วงการต่อสู้ ทั้งสองฝ่ายจะต่อสู้สูงสุด 10 รอบ หากครบแล้วยังไม่ชี้ขาด หาก HP ทั้งสองฝ่ายเกิน 90% ฝ่ายที่ทำดาเมจสูงกว่าจะชนะ หากฝ่ายใด HP ต่ำกว่า 90% จะตัดสินจากเปอร์เซ็นต์ HP ที่เหลือ',
		fmt_ph = '7. Sa panahon ng laban, ang dalawang koponan ay maaaring lumaban ng maximum na 10 rounds. Kung walang nanalo sa pagtatapos ng rounds at parehong may buhay ang bawat panig na higit sa 90%, ang koponan na may mas mataas na damage ay mananalo; kung may isa lamang na may buhay na mas mababa sa 90%, ang koponan na may mas mataas na porsyento ng buhay ay mananalo.',
		fmt_vn = '7. Trong giai đoạn chiến đấu, hai bên tối đa chiến đấu 10 hiệp. Nếu kết thúc hiệp đấu mà cả hai bên chưa phân thắng bại, nếu máu của cả hai bên đều trên 90%, thì bên gây sát thương cao hơn sẽ thắng; nếu chỉ cần một bên có máu dưới 90%, thì bên có tỷ lệ máu còn lại cao hơn sẽ thắng.'
	},
	[39008] = {
		id = 39008,
		fmt = '8. There is a points ranking during the match; points are determined by the damage dealt by heroes — the higher the damage, the higher the points.',
		fmt_ma = '8. Terdapat papan pendahulu berdasarkan kerosakan, lebih tinggi kerosakan = lebih tinggi mata  ',
		fmt_en = '8. There is a points ranking during the match; points are determined by the damage dealt by heroes — the higher the damage, the higher the points.',
		fmt_in = '8. Ada papan peringkat skor, skor ditentukan oleh damage yang diberikan pahlawan, semakin besar damage, semakin tinggi skor',
		fmt_th = '8. มีตารางคะแนนในแมตช์ คะแนนจะขึ้นอยู่กับดาเมจที่ฮีโร่ทำได้ ยิ่งสูงคะแนนยิ่งมาก',
		fmt_ph = '8. Mayroong ranking system sa laban, ang puntos ay ibinibigay base sa damage na naibigay ng bawat bayani. Mas mataas na damage, mas mataas ang puntos.',
		fmt_vn = '8. Có bảng xếp hạng điểm trong trận đấu, điểm được quyết định bởi sát thương mà anh hùng gây ra, sát thương càng cao, điểm càng cao.'
	},
	[39009] = {
		id = 39009,
		fmt = '9. Betting opens each day at 10:00. The higher the odds, the greater the potential profit. Players can earn up to 1 million gold coins daily.',
		fmt_ma = '9. Waktu bertaruh bermula 10:00 setiap hari. Lebih tinggi peluang, lebih besar ganjaran. Maksimum 1,000,000 syiling setiap hari  ',
		fmt_en = '9. Betting opens each day at 10:00. The higher the odds, the greater the potential profit. Players can earn up to 1 million gold coins daily.',
		fmt_in = '9. Taruhan dimulai setiap hari pukul 10:00, semakin tinggi odds, semakin besar keuntungan, tiap hari bisa mendapatkan maksimal 1 juta koin emas',
		fmt_th = '9. เริ่มเดิมพันทุกวันเวลา 10:00 ยิ่งอัตราต่อรองสูง ผลตอบแทนยิ่งมาก จำกัดสูงสุดวันละ 1 ล้านเหรียญ',
		fmt_ph = '9. Ang pagtaya ay magsisimula araw-araw nang 10:00, mas mataas ang odds, mas malaki ang kita. Ang maximum na taya bawat araw ay 1,000,000 coins.',
		fmt_vn = '9. Bắt đầu đặt cược mỗi ngày lúc 10 giờ, tỷ lệ cược càng cao, lợi nhuận càng lớn, mỗi ngày có thể nhận tối đa 100 vạn xu.'
	},
	[39010] = {
		id = 39010,
		fmt = '10. If the selected bet reaches the quarterfinals but does not win the championship, part of the bet will be refunded; if the bet fails to reach the quarterfinals, no refund will be given.',
		fmt_ma = '10. Jika pertaruhan berjaya ke suku akhir tetapi kalah, akan mendapat bayaran balik sebahagian. Jika gagal ke suku akhir, tiada bayaran balik  ',
		fmt_en = '10. If the selected bet reaches the quarterfinals but does not win the championship, part of the bet will be refunded; if the bet fails to reach the quarterfinals, no refund will be given.',
		fmt_in = '10. Jika pilihan taruhan masuk perempat final tapi tidak juara, sebagian taruhan akan dikembalikan; jika tidak masuk perempat final, taruhan tidak dikembalikan',
		fmt_th = '10. หากผู้เดิมพันเข้ารอบก่อนรองแต่ไม่ได้แชมป์ จะคืนเงินเดิมพันบางส่วน หากไม่เข้ารอบก่อนรองจะไม่คืน',
		fmt_ph = '10. Kung ang taya ay nakapasok sa quarter finals ngunit hindi nanalo ng championship, ibabalik ang bahagi ng taya; kung hindi nakapasok sa quarter finals, walang ibabalik na taya.',
