	[45003] = {
		id = 45003,
		fmt = '3. For heroes of different qualities, the maximum number of shards you can receive per wish varies. Higher quality heroes yield fewer shards.',
		fmt_ma = '3. Bilangan maksimum cebisan wira yang boleh diperoleh bergantung kepada kualiti wira — semakin tinggi kualiti, semakin sedikit jumlah cebisan diterima.  ',
