	[48003] = {
		id = 48003,
		fmt = 'Certain missions like total online time, stamina consumption, etc., can be completed in stages, with activity points awarded at each stage.',
		fmt_ma = 'Ang ilang mga activity quest tulad ng oras ng pag-online, pagkonsumo ng stamina, atbp. ay maaaring kumpletuhin sa mga yugto, bawat yugto ay nagbibigay ng katumbas na activity points.',
		fmt_en = 'Certain missions like total online time, stamina consumption, etc., can be completed in stages, with activity points awarded at each stage.',
		fmt_in = 'Beberapa misi aktivitas seperti akumulasi waktu online, konsumsi stamina, dll. dapat diselesaikan per tahap, setiap tahap memberikan poin aktivitas yang sesuai  ',
		fmt_th = 'ภารกิจบางอย่างเช่นสะสมเวลาออนไลน์ ใช้พลังงาน ฯลฯ จะมีหลายช่วง แต่ละช่วงรับแต้มกิจกรรมตามลำดับ',
		fmt_ph = 'Ang ilang activity quest tulad ng cumulative online time, stamina consumption, atbp. ay maaaring kumpletuhin sa mga yugto, bawat yugto ay may katumbas na activity points.',
		fmt_vn = 'Một số nhiệm vụ hoạt động như tích lũy thời gian online, tiêu hao thể lực,... có thể hoàn thành theo từng giai đoạn, mỗi giai đoạn đều nhận được điểm hoạt động tương ứng.'
	},
	[49001] = {
		id = 49001,
		fmt = '1. In the limited-time chest event, each chest draw grants 10 points, which determines leaderboard ranking. For ties, the earlier achiever ranks higher.',
		fmt_ma = '1. Sa kahon na may limitadong oras, bawat pagbubukas ay nagbibigay ng 10 puntos, at ang puntos na ito ang magtatakda ng ranggo sa leaderboard. Kung pantay ang puntos, ang nauna makakuha ng puntos ang mauuna sa ranggo.',
		fmt_en = '1. In the limited-time chest event, each chest draw grants 10 points, which determines leaderboard ranking. For ties, the earlier achiever ranks higher.',
		fmt_in = '1. Dalam peti terbatas waktu, setiap kali undian akan mendapatkan 10 poin, poin menentukan peringkat di papan peringkat. Jika poin sama, pemain yang mencapai poin lebih dulu akan mendapat peringkat lebih tinggi  ',
		fmt_th = '1. ในกล่องจำกัดเวลา ทุกครั้งที่สุ่มกล่องจะได้รับ 10 คะแนน คะแนนจะกำหนดอันดับในกระดานอันดับ หากคะแนนเท่ากัน ผู้ที่ได้คะแนนก่อนจะอยู่อันดับสูงกว่า',
		fmt_ph = '1. Sa limited-time chest, bawat draw ay magbibigay ng 10 points, ang points ang magtatakda ng ranking sa leaderboard. Kapag pantay ang points, ang naunang nakaabot ay mauuna sa ranking.',
		fmt_vn = '1. Trong rương giới hạn thời gian, mỗi lần rút rương sẽ nhận được 10 điểm, điểm số sẽ quyết định thứ hạng trên bảng xếp hạng. Nếu điểm số bằng nhau, người đạt điểm trước sẽ xếp hạng cao hơn.'
	},
	[49002] = {
		id = 49002,
		fmt = '2. In this event, every 10 equipment chest draws grants awakening alloy and universal shard chest (no awakening shards are produced).',
		fmt_ma = '2. Sa event na ito, bawat 10 beses ng pagbubukas ng kahon ng kagamitan ay makakakuha ng Awakening Alloy at Universal Shard Chest (hindi nagbibigay ng Awakening Shard).',
		fmt_en = '2. In this event, every 10 equipment chest draws grants awakening alloy and universal shard chest (no awakening shards are produced).',
		fmt_in = '2. Dalam event ini, setiap 10 kali undian peti peralatan akan mendapatkan paduan logam awakening dan peti fragment universal (tidak menghasilkan fragment awakening)  ',
		fmt_th = '2. ในกิจกรรมนี้ ทุกการสุ่มกล่องอุปกรณ์ครบ 10 ครั้ง จะได้รับโลหะผสมปลุกพลังและกล่องเศษอเนกประสงค์ (จะไม่ได้รับเศษปลุกพลัง)',
		fmt_ph = '2. Sa event na ito, bawat 10 draws ng equipment chest ay makakatanggap ng awakening alloy at universal fragment chest (hindi naglalaman ng awakening fragments).',
		fmt_vn = '2. Trong sự kiện này, mỗi 10 lần rút rương trang bị sẽ nhận được hợp kim thức tỉnh và rương mảnh vạn năng (không sản sinh mảnh thức tỉnh).'
	},
