	[50003] = {
		id = 50003,
		fmt = '3. Each hammer use consumes 1 hammer and XXXXX currency (amount and type depend on configuration). Each attempt may yield 3x, 6x, or 10x rewards.',
		fmt_ma = '3. Bawat pagbasag ng itlog ay gagamit ng 1 martilyo at XXXXX currency (halaga at uri ay batay sa setting). Bawat basag ay may tsansang makakuha ng 3x, 6x, o 10x na gantimpala.',
		fmt_en = '3. Each hammer use consumes 1 hammer and XXXXX currency (amount and type depend on configuration). Each attempt may yield 3x, 6x, or 10x rewards.',
		fmt_in = '3. Setiap kali memecahkan telur menghabiskan 1 palu dan XXXXX koin (jumlah dan jenis koin sesuai pengaturan). Setiap pemecahan memiliki peluang mendapatkan hadiah 3x, 6x, 10x  ',
		fmt_th = '3. ทุกครั้งที่ตีไข่จะใช้ค้อน 1 อัน และใช้สกุลเงิน XXXXX (ปริมาณและประเภทตามที่กำหนด) แต่ละครั้งมีโอกาสได้รับรางวัลคูณ 3 เท่า, 6 เท่า, 10 เท่า  ',
		fmt_ph = '3. Bawat basag ng itlog ay gagamit ng 1 hammer at XXXXX currency (halaga at uri ay ayon sa configuration). May chance na makatanggap ng 3x, 6x, 10x na rewards bawat basag.',
		fmt_vn = '3. Mỗi lần đập trứng sẽ tiêu hao 1 búa và XXXXX tiền tệ (số lượng và loại tiền tệ theo cấu hình). Mỗi lần đập trứng có cơ hội nhận thưởng gấp 3 lần, 6 lần, 10 lần.'
	},
	[50004] = {
		id = 50004,
		fmt = '4. When hitting a 10x prize, the system will immediately reset the 3 golden eggs. If not yet hit, players can keep hitting the remaining eggs until they do.',
		fmt_ma = '4. Kapag nakuha ang 10x na gantimpala, awtomatikong ire-reset ng sistema ang 3 itlog. Kung hindi pa nakuha, maaaring ipagpatuloy ang pagbasag ng natitirang itlog hanggang sa makuha ito.',
		fmt_en = '4. When hitting a 10x prize, the system will immediately reset the 3 golden eggs. If not yet hit, players can keep hitting the remaining eggs until they do.',
		fmt_in = '4. Jika mendapatkan hadiah 10x, sistem akan langsung mereset 3 telur emas. Jika belum dapat, pemain bisa melanjutkan memecahkan telur hingga mendapatkannya  ',
		fmt_th = '4. เมื่อได้รางวัลคูณ 10 เท่า ระบบจะรีเซ็ตไข่ทองใหม่ทันที 3 ฟอง หากยังไม่ได้รางวัล ผู้เล่นสามารถตีไข่ที่เหลือต่อไปจนกว่าจะได้รางวัล',
		fmt_ph = '4. Kapag nakakuha ng 10x reward, awtomatikong mare-reset ang 3 golden eggs. Kapag hindi pa nakakuha ng 10x reward, maaaring ipagpatuloy ang pagbasag sa natitirang eggs.',
		fmt_vn = '4. Khi đập trúng giải thưởng gấp 10 lần, hệ thống sẽ ngay lập tức đặt lại 3 quả trứng vàng. Nếu chưa đập trúng, người chơi có thể tiếp tục đập các quả trứng còn lại cho đến khi trúng.'
	},
	[50005] = {
		id = 50005,
		fmt = '5. Lucky players may hit a 10x prize on the first try; if not, after 3 attempts a 10x prize is guaranteed.',
		fmt_ma = '5. Kung masuwerte, maaaring makuha ang 10x na gantimpala sa unang basag; kung hindi, sigurado na itong makukuha pagkatapos ng 3 basag.',
		fmt_en = '5. Lucky players may hit a 10x prize on the first try; if not, after 3 attempts a 10x prize is guaranteed.',
		fmt_in = '5. Jika beruntung, pemain bisa langsung dapat hadiah 10x di percobaan pertama; jika kurang beruntung, setelah 3 kali percobaan pasti mendapatkan hadiah 10x  ',
		fmt_th = '5. หากโชคดี ผู้เล่นอาจได้รางวัลคูณ 10 เท่าตั้งแต่ครั้งแรก หากโชคร้าย หลังจากตีครบ 3 ครั้งก็จะได้รับรางวัลคูณ 10 เท่าแน่นอน',
		fmt_ph = '5. Kung masuwerte, maaaring makuha ang 10x reward sa unang subok; kung hindi, sigurado makukuha ito sa ikatlong subok.',
		fmt_vn = '5. Nếu may mắn, người chơi có thể đập trúng giải thưởng gấp 10 lần ngay lần đầu tiên; nếu không may, sau 3 lần đập cũng chắc chắn nhận được giải thưởng gấp 10 lần.'
	},
	[51001] = {
		id = 51001,
