		fmt_vn = '5. Chiến văn sau khi phân giải có thể nhận được nguyên liệu cường hóa chiến văn, dùng để cường hóa các chiến văn khác.'
	},
	[85001] = {
		id = 85001,
		fmt = '1. During the event, players can lead heroes to challenge the World Boss',
		fmt_ma = '1. Semasa acara berlangsung, pemain boleh membawa hero untuk mencabar Boss Dunia.',
		fmt_en = '1. During the event, players can lead heroes to challenge the World Boss',
		fmt_in = '1. Selama event berlangsung, pemain dapat memimpin pahlawan untuk menantang Boss Dunia.  ',
		fmt_th = '1. ในช่วงกิจกรรม ผู้เล่นสามารถนำฮีโร่เข้าร่วมท้าทายบอสโลก',
		fmt_ph = '1. Sa panahon ng event, puwedeng isama ang hero para sa World Boss challenge',
		fmt_vn = '1. Trong thời gian sự kiện, người chơi có thể dẫn dắt anh hùng tham gia thử thách Boss thế giới.'
	},
	[85002] = {
		id = 85002,
		fmt = '2. Each World Boss fight records the damage dealt. When reaching certain damage thresholds, players will receive corresponding chest rewards immediately after the fight',
		fmt_ma = '2. Setiap pertempuran akan merekodkan jumlah kerosakan. Bila mencapai sasaran tertentu, pemain akan mendapat peti ganjaran sejurus selepas cabaran.',
		fmt_en = '2. Each World Boss fight records the damage dealt. When reaching certain damage thresholds, players will receive corresponding chest rewards immediately after the fight',
		fmt_in = '2. Setiap pertarungan melawan Boss Dunia akan mencatat jumlah damage yang dihasilkan. Setelah mencapai target damage tertentu, hadiah sesuai akan langsung diperoleh setelah selesai tantangan.  ',
		fmt_th = '2. แต่ละรอบที่ต่อสู้กับบอสโลก จะบันทึกปริมาณความเสียหายที่ผู้เล่นสร้าง เมื่อถึงเป้าหมายความเสียหายที่กำหนด ผู้เล่นจะได้รับรางวัลในกล่องหลังจบท้าทายทันที',
		fmt_ph = '2. Bawat laban sa World Boss magre-record ng damage, kapag umabot ng target, may reward agad',
		fmt_vn = '2. Mỗi trận đấu với Boss thế giới sẽ ghi nhận lượng sát thương người chơi gây ra. Khi đạt mục tiêu sát thương nhất định, người chơi sẽ nhận được phần thưởng trong rương tương ứng ngay sau khi kết thúc thử thách.'
	},
	[85003] = {
		id = 85003,
		fmt = '3. The World Boss records the highest total server-wide damage. Upon reaching the goal, all players participating that day will receive chest rewards via mail at 5:00 AM the next day, and cumulative damage will reset',
		fmt_ma = '3. Kerosakan tertinggi seluruh server akan direkod. Jika tercapai, semua pemain yang sertai akan terima peti ganjaran melalui surat pada jam 5 pagi keesokan hari, dan data akan diset semula.',
		fmt_en = '3. The World Boss records the highest total server-wide damage. Upon reaching the goal, all players participating that day will receive chest rewards via mail at 5:00 AM the next day, and cumulative damage will reset',
		fmt_in = '3. Boss Dunia mencatat total damage tertinggi seluruh server. Jika target tercapai, semua pemain yang berpartisipasi hari itu akan menerima hadiah. Hadiah akan dikirim melalui surat pada pukul 5 pagi keesokan harinya, dan data damage akan direset.  ',
		fmt_th = '3. บอสโลกจะบันทึกความเสียหายรวมสูงสุดของทั้งเซิร์ฟเวอร์ เมื่อถึงเป้าหมาย ผู้เล่นทุกคนที่เข้าร่วมกิจกรรมในวันนั้นจะได้รับรางวัลกล่อง รางวัลจะส่งผ่านจดหมายตอนตี 5 ของวันถัดไป และข้อมูลความเสียหายสะสมจะถูกรีเซ็ต',
		fmt_ph = '3. World Boss magre-record ng highest total server damage, pag umabot target, lahat participant may reward sa mail 5AM next day, data reset',
		fmt_vn = '3. Boss thế giới ghi nhận tổng sát thương cao nhất của toàn máy chủ. Khi đạt mục tiêu, tất cả người chơi tham gia sự kiện trong ngày sẽ nhận được phần thưởng rương. Phần thưởng sẽ được gửi qua thư vào 5 giờ sáng ngày hôm sau, đồng thời dữ liệu sát thương tích lũy sẽ được đặt lại.'
	},
	[85004] = {
		id = 85004,
		fmt = '4. World Boss has free challenge attempts; players can purchase more. When attempt limit is reached, players cannot continue fighting that day. Attempts reset at 5:00 AM the next day',
		fmt_ma = '4. Terdapat bilangan percubaan percuma, dan pemain boleh beli lebih. Bila had dicapai, pemain tidak boleh mencabar lagi pada hari tersebut. Percubaan akan ditetapkan semula jam 5 pagi.',
		fmt_en = '4. World Boss has free challenge attempts; players can purchase more. When attempt limit is reached, players cannot continue fighting that day. Attempts reset at 5:00 AM the next day',
		fmt_in = '4. Ada jumlah tantangan gratis untuk Boss Dunia, pemain juga dapat membeli tambahan. Setelah mencapai batas, pemain tidak dapat lagi bertarung hari itu. Kesempatan akan direset pukul 5 pagi.  ',
		fmt_th = '4. บอสโลกมีจำนวนครั้งท้าทายฟรี ผู้เล่นสามารถซื้อรอบเพิ่มได้ เมื่อถึงขีดจำกัดการท้าทาย ผู้เล่นจะไม่สามารถต่อสู้ในวันนั้นได้ รอบท้าทายจะรีเซ็ตตอนตี 5 ของวันถัดไป',
		fmt_ph = '4. May free tries sa World Boss, puwedeng bumili extra tries, may limit per day, refresh 5AM next day',
		fmt_vn = '4. Boss thế giới có số lần thử thách miễn phí, người chơi cũng có thể mua thêm lượt. Khi đạt giới hạn lượt, người chơi không thể tiếp tục chiến đấu trong ngày đó. Lượt thử thách sẽ được làm mới vào 5 giờ sáng ngày hôm sau.'
	},
	[85005] = {
		id = 85005,
		fmt = '5. The highest individual single-hit damage in a World Boss fight will be recorded on the individual and guild leaderboards. Rankings and damage logs reset at 5:00 AM the next day',
		fmt_ma = '5. Kerosakan tertinggi individu untuk satu percubaan akan disenaraikan dalam papan ranking individu dan guild. Data akan diset semula setiap jam 5 pagi.',
		fmt_en = '5. The highest individual single-hit damage in a World Boss fight will be recorded on the individual and guild leaderboards. Rankings and damage logs reset at 5:00 AM the next day',
		fmt_in = '5. Damage tertinggi pribadi dalam satu serangan Boss Dunia hari itu akan dicatat dalam peringkat individu dan guild. Peringkat akan direset pukul 5 pagi keesokan harinya.',
		fmt_th = '5. ความเสียหายสูงสุดส่วนตัวที่สร้างได้ในครั้งเดียวต่อบอสโลกในวันนั้น จะถูกบันทึกในตารางอันดับผู้เล่นและอันดับกิลด์ ตารางอันดับและบันทึกความเสียหายจะรีเซ็ตตอนตี 5 ของวันถัดไป',
		fmt_ph = '5. Highest individual damage per day recorded sa solo at guild rank, refresh 5AM next day',
		fmt_vn = '5. Sát thương cao nhất cá nhân gây ra trong một lần duy nhất vào Boss Thế Giới trong ngày sẽ được ghi vào bảng xếp hạng cá nhân và bảng xếp hạng công hội. Bảng xếp hạng và ghi chép sát thương sẽ được làm mới vào 5 giờ sáng ngày hôm sau.'
	},
	[85006] = {
		id = 85006,
		fmt = '6. Players and guilds ranked will receive ranking rewards. Click "Ranking Rewards" to preview rewards. Rewards are sent via mail at 5:00 AM the next day',
		fmt_ma = '6. Pemain dan guild dalam papan ranking akan menerima ganjaran ranking. Klik butang "Ganjaran Ranking" untuk lihat butiran. Ganjaran dihantar melalui surat jam 5 pagi.',
		fmt_en = '6. Players and guilds ranked will receive ranking rewards. Click "Ranking Rewards" to preview rewards. Rewards are sent via mail at 5:00 AM the next day',
		fmt_in = '6. Pemain dan guild yang masuk peringkat akan mendapatkan hadiah, silakan klik "Hadiah Peringkat" untuk melihat detail. Hadiah dikirim melalui surat pada pukul 5 pagi.  ',
		fmt_th = '6. ผู้เล่นและกิลด์ที่ติดอันดับจะได้รับรางวัลอันดับ กรุณาคลิกปุ่ม "รางวัลอันดับ" เพื่อดูรางวัลล่วงหน้า รางวัลจะส่งผ่านจดหมายตอนตี 5 ของวันถัดไป  ',
		fmt_ph = '6. Players at guilds sa rank board makakatanggap ng rank reward via mail 5AM next day',
		fmt_vn = '6. Người chơi và bang hội lọt vào bảng xếp hạng sẽ nhận được phần thưởng xếp hạng. Vui lòng nhấp vào nút "Phần thưởng xếp hạng" để xem trước phần thưởng. Phần thưởng sẽ được gửi qua thư vào lúc 5 giờ sáng ngày hôm sau.'
	},
	[85007] = {
		id = 85007,
		fmt = '7. Players not in a guild will not appear on the guild leaderboard. If a player joins a guild before data reset, only damage after joining will count',
		fmt_ma = '7. Pemain tanpa guild tidak akan dikira dalam ranking guild. Hanya data selepas menyertai guild akan direkod.',
		fmt_en = '7. Players not in a guild will not appear on the guild leaderboard. If a player joins a guild before data reset, only damage after joining will count',
		fmt_in = '7. Pemain tanpa guild tidak akan masuk ke peringkat guild. Jika bergabung dengan guild sebelum data direset, hanya data setelah bergabung yang akan dihitung.  ',
		fmt_th = '7. ผู้เล่นที่ไม่ได้เข้าร่วมกิลด์จะไม่ได้รับการนับในอันดับกิลด์ หากผู้เล่นเข้ากิลด์ก่อนข้อมูลรีเซ็ต จะบันทึกข้อมูลท้าทายบอสโลกเฉพาะหลังจากเข้ากิลด์เท่านั้น',
		fmt_ph = '7. Players na walang guild hindi kasama sa guild rank; kung sumali bago reset, counted lang bagong challenge data',
		fmt_vn = '7. Người chơi không gia nhập công hội sẽ không được tính vào bảng xếp hạng công hội. Nếu người chơi gia nhập công hội trước khi dữ liệu được thiết lập lại, thì chỉ thông tin về thử thách Boss Thế Giới sau khi gia nhập công hội mới sẽ được ghi lại.'
	},
	[85008] = {
		id = 85008,
		fmt = '8. If a player fights World Boss while in a guild, then leaves and joins another guild before data reset, their damage will not count for the new guild\'s ranking',
		fmt_ma = '8. Pemain yang sertai Boss Dunia dalam satu guild, keluar dan masuk guild lain sebelum data diset semula, tidak akan menjana data untuk guild baru.',
		fmt_en = '8. If a player fights World Boss while in a guild, then leaves and joins another guild before data reset, their damage will not count for the new guild\'s ranking',
		fmt_in = '8. Jika pemain menyerang Boss Dunia saat di guild, lalu keluar dan bergabung guild lain sebelum reset, data damage tidak akan dihitung untuk guild baru.  ',
		fmt_th = '8. ผู้เล่นที่อยู่ในการต่อสู้บอสโลกขณะอยู่ในกิลด์ จากนั้นออกจากกิลด์และเข้ากิลด์ใหม่ก่อนข้อมูลรีเซ็ต จะไม่สร้างข้อมูลความเสียหายส่วนตัวในกิลด์ใหม่',
		fmt_ph = '8. Kung player nag-Boss challenge habang nasa guild, tapos lumabas at pumasok sa ibang guild bago reset, di counted damage sa bagong guild',
		fmt_vn = '8. Người chơi đã vào trận đấu BOSS Thế Giới khi đang ở trong một bang hội, sau đó rời bang hội, và gia nhập lại một bang hội khác trước khi dữ liệu được làm mới, sẽ không tạo ra dữ liệu sát thương của riêng mình trong bang hội mới.'
	},
	[86001] = {
