	[86006] = {
		id = 86006,
		fmt = '6. Season ranks are divided into major and minor tiers. Major tiers in ascending order are Bronze-Silver-Gold-Platinum-Diamond-Master-Warlord; minor tiers are ranked by number, the lower the number the higher the rank. Master and Warlord have no minor tiers',
		fmt_ma = '6. Peringkat dibahagi kepada peringkat besar dan kecil. Besar: Gangsa-Perak-Emas-Platinum-Berlian-Elit-Dewa. Kecil: nombor (semakin kecil, semakin tinggi). Elit dan Dewa tiada peringkat kecil.',
		fmt_en = '6. Season ranks are divided into major and minor tiers. Major tiers in ascending order are Bronze-Silver-Gold-Platinum-Diamond-Master-Warlord; minor tiers are ranked by number, the lower the number the higher the rank. Master and Warlord have no minor tiers',
