		fmt_th = '5. ขนมบั๊งเชิงที่ทำเสร็จแล้วสามารถใช้ได้ทั้งในหน้ากิจกรรมและจากกระเป๋าของผู้เล่น วัตถุดิบและขนมบั๊งเชิงมีอายุใช้งาน "#C0xF76B45#กรุณาใช้ก่อนหมดอายุ มิฉะนั้นไอเท็มจะถูกลบออก#C0xFFFFFF#"',
		fmt_ph = '5. Ginawang Banh Chung puwedeng gamitin sa event UI o bag. Ingredients at Banh Chung may expiry. "#C0xF76B45#Gamitin bago mag-expire o mawawala ang item.#C0xFFFFFF#"',
		fmt_vn = '5. Bánh chưng sau khi làm xong có thể sử dụng trong giao diện sự kiện hoặc từ túi đồ. Nguyên liệu và bánh chưng đều có thời hạn sử dụng. "#C0xF76B45#Vui lòng sử dụng trước khi hết hạn, nếu không vật phẩm sẽ bị xóa.#C0xFFFFFF#".'
	},
	[93001] = {
		id = 93001,
		fmt = '1. The fishing feature has a daily limit on the number of attempts. This limit will be reset at 5 AM daily. Once the attempts are used up, players cannot fish further that day.',
		fmt_ma = '1. Fungsi memancing mempunyai had bilangan setiap hari. Bilangan ini akan disegarkan semula pada jam 5 pagi setiap hari. Setelah habis, pemain tidak boleh terus memancing hari itu.',
		fmt_en = '1. The fishing feature has a daily limit on the number of attempts. This limit will be reset at 5 AM daily. Once the attempts are used up, players cannot fish further that day.',
		fmt_in = '1. Fitur memancing memiliki batas jumlah percobaan per hari. Jumlah ini akan direset setiap pukul 5 pagi. Jika habis, pemain tidak bisa memancing lagi hari itu.  ',
		fmt_th = '1. ฟีเจอร์ตกปลาจะจำกัดจำนวนครั้งต่อวัน จำนวนครั้งนี้จะรีเซ็ตตอนตี 5 ของทุกวัน เมื่อหมดจำนวนครั้ง ผู้เล่นจะไม่สามารถตกปลาได้ในวันนั้น',
		fmt_ph = '1. Fishing feature may daily limit, refresh 5AM daily. Pag naubos, di na puwedeng mangisda',
		fmt_vn = '1. Tính năng câu cá có giới hạn số lần mỗi ngày. Số lần này sẽ được làm mới vào 5 giờ sáng hàng ngày. Khi hết lượt, người chơi không thể tiếp tục câu cá trong ngày.'
	},
	[93002] = {
		id = 93002,
		fmt = '2. Each fishing attempt requires one bait.',
		fmt_ma = '2. Setiap kali memancing memerlukan satu umpan.',
		fmt_en = '2. Each fishing attempt requires one bait.',
		fmt_in = '2. Setiap kali memancing memerlukan satu umpan.',
		fmt_th = '2. แต่ละครั้งในการตกปลาจะต้องใช้เหยื่อ 1 ชิ้น',
		fmt_ph = '2. Bawat fishing try gagamit ng bait',
