	},
	[93008] = {
		id = 93008,
		fmt = '8. To level up fishing, players need to catch the required number of fish for each level. Once the required amount is reached, the level will automatically increase, and the number required for the next level will be recalculated.',
		fmt_ma = '8. Untuk meningkatkan tahap memancing, pemain perlu menangkap jumlah ikan yang diperlukan untuk setiap tahap. Setelah mencukupi, tahap akan naik secara automatik dan bilangan yang diperlukan untuk tahap baru akan dikira semula dari awal.',
		fmt_en = '8. To level up fishing, players need to catch the required number of fish for each level. Once the required amount is reached, the level will automatically increase, and the number required for the next level will be recalculated.',
		fmt_in = '8. Untuk meningkatkan level memancing, pemain harus menangkap jumlah ikan tertentu. Setelah cukup, level akan naik otomatis dan jumlah untuk level berikutnya dihitung ulang.  ',
		fmt_th = '8. เพื่อเพิ่มเลเวลตกปลา ผู้เล่นต้องจับปลาตามจำนวนที่กำหนดสำหรับแต่ละเลเวล เมื่อครบจำนวน เลเวลจะเพิ่มขึ้นอัตโนมัติและจำนวนที่ต้องจับสำหรับเลเวลถัดไปจะเริ่มนับใหม่',
		fmt_ph = '8. Para tumaas fishing level, kailangan hulihin required na bilang ng isda per level. Pag naabot, level up auto at reset counter',
		fmt_vn = '8. Để tăng cấp độ câu cá, người chơi cần đạt đủ số lượng cá yêu cầu cho mỗi cấp. Khi đếm đủ số lượng, cấp độ sẽ tự động tăng và số lượng yêu cầu cho cấp mới sẽ được tính lại từ đầu.'
	},
	[93009] = {
