		fmt_ph = 'Kapag Commander Level Lv.68, puwedeng gamitin auto fishing. Click companion hero sa UI para mag-auto fish, auto fishing pwedeng mag-fail',
		fmt_vn = 'Khi cấp độ chỉ huy đạt Lv.68, bạn có thể sử dụng chức năng tự động câu cá. Nhấn vào anh hùng đồng hành trên giao diện để vào tự động câu cá, tự động câu cá có thể thất bại.'
	},
