		fmt = '1. Specific heroes in the Manual can be awakened in the Soul Awakening House.',
		fmt_ma = '1. Hero tertentu dalam Buku Panduan boleh dibangkitkan semangatnya di Rumah Kebangkitan Semangat.',
		fmt_en = '1. Specific heroes in the Manual can be awakened in the Soul Awakening House.',
