	[95002] = {
		id = 95002,
		fmt = '2. After awakening the soul, the hero\'s basic attributes will be increased, and all the attributes already cultivated will be completely inherited; attribute system and rarity #C0xF76B45##L10# can also change #C0xFFFFFF#.',
		fmt_ma = '2. Selepas kebangkitan semangat, atribut asas hero akan meningkat, semua atribut yang telah dibangunkan akan diwarisi sepenuhnya; sistem atribut dan kelangkaan #C0xF76B45##L10# juga boleh berubah #C0xFFFFFF#.',
		fmt_en = '2. After awakening the soul, the hero\'s basic attributes will be increased, and all the attributes already cultivated will be completely inherited; attribute system and rarity #C0xF76B45##L10# can also change #C0xFFFFFF#.',
		fmt_in = '2. Setelah kebangkitan jiwa, atribut dasar hero akan meningkat, semua atribut yang sudah ditingkatkan akan diwariskan sepenuhnya; elemen atribut dan tingkat kelangkaan #C0xF76B45##L10# juga bisa berubah #C0xFFFFFF#.  ',
		fmt_th = '2. หลังจากปลุกจิตวิญญาณแล้ว ค่าสถานะพื้นฐานของฮีโร่จะเพิ่มขึ้น ค่าสถานะที่บำรุงจะได้รับการถ่ายทอดอย่างสมบูรณ์ และธาตุ/ความหายาก #C0xF76B45##L10# ก็อาจเปลี่ยนแปลงได้ #C0xFFFFFF#',
		fmt_ph = '2. Pagkatapos ng Soul Awakening, tataas ang base stats ng hero, lahat ng trained stats maiiwan; ang element at rarity #C0xF76B45##L10# puwede ring magbago #C0xFFFFFF#',
		fmt_vn = '2. Sau khi thức tỉnh linh hồn, thuộc tính cơ bản của anh hùng sẽ được tăng lên, tất cả thuộc tính đã bồi dưỡng sẽ được kế thừa hoàn toàn; hệ thuộc tính và độ hiếm #C0xF76B45##L10# cũng có thể thay đổi #C0xFFFFFF#.'
	},
	[95003] = {
		id = 95003,
		fmt = '3. Heroes need to be cultivated to a certain stage before they can undergo soul awakening; and it primarily consumes two types of special items: Soul Awakening Stones and Exclusive Awakening Stones.',
		fmt_ma = '3. Hero perlu dibangunkan sehingga tahap tertentu sebelum boleh melakukan kebangkitan semangat; dan terutamanya memerlukan dua jenis bahan khas: Batu Kebangkitan Semangat dan Batu Kebangkitan Eksklusif.',
		fmt_en = '3. Heroes need to be cultivated to a certain stage before they can undergo soul awakening; and it primarily consumes two types of special items: Soul Awakening Stones and Exclusive Awakening Stones.',
		fmt_in = '3. Hero harus ditingkatkan sampai tahap tertentu sebelum bisa melakukan kebangkitan jiwa; proses ini terutama memerlukan dua jenis item khusus: Batu Kebangkitan Jiwa dan Batu Kebangkitan Khusus.',
		fmt_th = '3. ฮีโร่จะต้องบำรุงจนถึงขั้นตอนหนึ่งก่อนจึงจะสามารถปลุกจิตวิญญาณได้ และต้องใช้วัตถุดิบพิเศษ 2 ชนิด คือ หินปลุกจิตวิญญาณ และหินปลุกจิตวิญญาณเฉพาะทาง',
		fmt_ph = '3. Kailangan i-train muna ang hero hanggang required phase bago puwedeng i-Awaken; kailangan ng dalawang special item: Soul Awakening Stone at Special Awakening Stone',
		fmt_vn = '3. Anh hùng cần được bồi dưỡng đến một giai đoạn nhất định mới có thể tiến hành thức tỉnh linh hồn; và chủ yếu tiêu hao hai loại đạo cụ đặc biệt: Đá thức tỉnh linh hồn và Đá thức tỉnh chuyên dụng.'
	},
	[95004] = {
		id = 95004,
		fmt = '4. Soul Awakening Stones and Exclusive Awakening Stones can be obtained daily through exchanges in the Soul Awakening House.',
		fmt_ma = '4. Batu Kebangkitan Semangat dan Batu Kebangkitan Eksklusif boleh diperoleh setiap hari melalui penukaran di Rumah Kebangkitan Semangat.',
