	[96001] = {
		id = 96001,
		fmt = '1. Soul Awakening Stones can be obtained by exchanging #C0xF76B45##L10# heroes of the same rarity #C0xFFFFFF# or hero shards #C0xF76B45##L10# of the same rarity #C0xFFFFFF#, with a daily exchange limit.',
		fmt_ma = '1. Batu Kebangkitan Semangat boleh diperoleh dengan menukar #C0xF76B45##L10# hero dengan kelangkaan yang sama #C0xFFFFFF# atau kepingan hero #C0xF76B45##L10# dengan kelangkaan yang sama #C0xFFFFFF#, dengan had penukaran harian.',
		fmt_en = '1. Soul Awakening Stones can be obtained by exchanging #C0xF76B45##L10# heroes of the same rarity #C0xFFFFFF# or hero shards #C0xF76B45##L10# of the same rarity #C0xFFFFFF#, with a daily exchange limit.',
		fmt_in = '1. Batu Kebangkitan Jiwa bisa diperoleh dengan mengonversi #C0xF76B45##L10# hero dengan tingkat kelangkaan yang sama #C0xFFFFFF# atau fragmen hero #C0xF76B45##L10# dengan tingkat kelangkaan yang sama #C0xFFFFFF#, dan ada batas jumlah konversi harian.  ',
		fmt_th = '1. หินปลุกจิตวิญญาณสามารถรับได้โดยการแลกเปลี่ยน #C0xF76B45##L10# ฮีโร่ที่มีความหายากเท่ากัน #C0xFFFFFF# หรือเศษชิ้นส่วนฮีโร่ #C0xF76B45##L10# ที่มีความหายากเท่ากัน #C0xFFFFFF# โดยมีจำนวนจำกัดในการแลกเปลี่ยนต่อวัน',
		fmt_ph = '1. Soul Awakening Stone puwedeng makuha sa pag-convert ng #C0xF76B45##L10# parehong rarity na hero #C0xFFFFFF# o hero fragments #C0xF76B45##L10# parehong rarity #C0xFFFFFF#, may daily conversion limit',
		fmt_vn = '1. Đá Thức Tỉnh Linh Hồn có thể nhận được bằng cách chuyển đổi #C0xF76B45##L10# tướng cùng độ hiếm #C0xFFFFFF# hoặc mảnh tướng #C0xF76B45##L10# cùng độ hiếm #C0xFFFFFF#, và có giới hạn số lượng chuyển đổi mỗi ngày.'
	},
	[96004] = {
		id = 96004,
		fmt = '③ Each SS hero or red shadow clone can be exchanged for 10 Red Soul Awakening Stones. Every 8 SS shards can be exchanged for 1 Red Soul Awakening Stone.',
		fmt_ma = '③ Setiap hero SS atau bayangan gelap merah boleh ditukar menjadi 10 Batu Kebangkitan Semangat Merah, setiap 8 kepingan SS boleh ditukar menjadi 1 Batu Kebangkitan Semangat Merah.',
		fmt_en = '③ Each SS hero or red shadow clone can be exchanged for 10 Red Soul Awakening Stones. Every 8 SS shards can be exchanged for 1 Red Soul Awakening Stone.',
		fmt_in = '③ Setiap hero SS atau klon bayangan merah dapat dikonversi menjadi 10 Batu Kebangkitan Jiwa Merah, setiap 8 fragmen SS dapat dikonversi menjadi 1 Batu Kebangkitan Jiwa Merah.  ',
		fmt_th = '③ ฮีโร่ระดับ SS หรือเงาแดงสามารถแลกเป็นหินปลุกจิตวิญญาณสีแดงได้ 10 ชิ้น ส่วน 8 เศษชิ้นส่วน SS สามารถแลกเป็นหินปลุกจิตวิญญาณสีแดงได้ 1 ชิ้น',
		fmt_ph = '③ Bawat SS hero o red shadow clone puwedeng i-convert sa 10 Red Soul Awakening Stone, bawat 8 SS fragments puwedeng i-convert sa 1 Red Soul Awakening Stone',
		fmt_vn = '③ Mỗi tướng SS hoặc phân thân bóng tối đỏ có thể chuyển đổi thành 10 Đá Thức Tỉnh Hồn Đỏ, mỗi 8 mảnh SS có thể chuyển đổi thành 1 Đá Thức Tỉnh Hồn Đỏ.'
	},
	[96005] = {
		id = 96005,
		fmt = '2. The number of Soul Awakening Stones that can be exchanged through the system\'s daily auto-addition at 5:00 AM and purchased with Diamonds will increase. These can be accumulated permanently but cannot exceed the maximum limit.',
		fmt_ma = '2. Jumlah Batu Kebangkitan Semangat yang boleh ditukar melalui sistem secara automatik setiap hari pada pukul 05:00 dan dibeli dengan Berlian akan meningkat, boleh dikumpul secara kekal tetapi tidak melebihi had maksimum.  ',
		fmt_en = '2. The number of Soul Awakening Stones that can be exchanged through the system\'s daily auto-addition at 5:00 AM and purchased with Diamonds will increase. These can be accumulated permanently but cannot exceed the maximum limit.',
		fmt_in = '2. Jumlah Batu Kebangkitan Jiwa yang dapat dikonversi dari sistem penambahan otomatis setiap hari pukul 05:00 dan pembelian dengan Berlian akan ditingkatkan, dapat diakumulasi secara permanen namun tidak boleh melebihi batas maksimum.  ',
		fmt_th = '2. จำนวนหินปลุกจิตวิญญาณที่สามารถแลกเปลี่ยนได้จากการที่ระบบเพิ่มให้อัตโนมัติทุกวันเวลา 05:00 และจากการซื้อด้วยเพชรจะถูกเพิ่มขึ้น สามารถสะสมได้ตลอดแต่ไม่เกินขีดจำกัดสูงสุด',
		fmt_ph = '2. Ang bilang ng Soul Awakening Stones na puwedeng i-convert mula sa daily auto-refresh ng system tuwing 05:00 at mula sa pagbili gamit ang Diamonds ay madaragdagan, puwedeng maipon ng permanente pero hindi lalampas sa max limit',
		fmt_vn = '2. Số lượng Đá Thức Tỉnh Hồn có thể chuyển đổi từ việc hệ thống tự động thêm vào mỗi ngày lúc 05:00 và mua bằng Kim Cương sẽ được tăng lên, có thể tích lũy vĩnh viễn nhưng không được vượt quá giới hạn tối đa.'
	},
	[97001] = {
