	[99004] = {
		id = 99004,
		fmt = '4. In Fair Mode, the match is divided into #C0xF76B45#position selection system#C0xFFFFFF# and #C0xF76B45#BAN selection system#C0xFFFFFF#, based on the pre-match hero selection process. Once a certain score is reached, the system will automatically switch to the BAN selection system (the theme will remain unchanged). The specific points can be found in the Fair Mode, click "i" below the switch button to view.',
		fmt_ma = '4. Pertarungan Adil menggunakan sistem pemilihan posisi #C0xF76B45#dan sistem BAN berdasarkan proses pemilihan hero sebelum pertarungan rasmi. Apabila mencapai mata tertentu, akan bertukar automatik ke sistem BAN (tema tidak berubah). Maklumat mata boleh didapati dalam mod Adil, klik i di bawah butang tukar mod.  ',
		fmt_en = '4. In Fair Mode, the match is divided into #C0xF76B45#position selection system#C0xFFFFFF# and #C0xF76B45#BAN selection system#C0xFFFFFF#, based on the pre-match hero selection process. Once a certain score is reached, the system will automatically switch to the BAN selection system (the theme will remain unchanged). The specific points can be found in the Fair Mode, click "i" below the switch button to view.',
		fmt_in = '4. Mode Adil dibagi menjadi sistem pemilihan posisi #C0xF76B45# dan sistem BAN berdasarkan proses pemilihan hero sebelum pertandingan resmi. Setelah mencapai poin tertentu, akan otomatis masuk ke sistem pemilihan BAN (tema tidak berubah). Detail poin bisa dilihat di mode Adil, klik "i" di bawah tombol untuk melihat.  ',
		fmt_th = '4. การแข่งขันโหมดยุติธรรมใช้ระบบเลือกตำแหน่ง #C0xF76B45#และระบบเลือก BAN#C0xFFFFFF# ตามขั้นตอนการเลือกฮีโร่ก่อนต่อสู้ เมื่อถึงคะแนนที่กำหนดจะเปลี่ยนเป็นระบบเลือก BAN อัตโนมัติ (ธีมไม่เปลี่ยน) คะแนนเฉพาะสามารถดูได้ในโหมดนี้ โดยคลิก i ใต้ปุ่มสลับโหมด',
		fmt_ph = '4. Sa Fair Mode, may position pick system at BAN pick system. Kapag naabot ang certain points, lilipat sa BAN pick. Specific points ay makikita sa Fair Mode info (click i button sa ilalim ng toggle button)',
		fmt_vn = '4. Trận đấu công bằng được chia thành hệ thống chọn vị trí #C0xF76B45# và hệ thống chọn BAN dựa trên quy trình chọn tướng trước trận chiến chính thức. Sau khi đạt số điểm nhất định sẽ tự động chuyển sang hệ thống chọn BAN (chủ đề sẽ). không thay đổi). Điểm cụ thể có thể được tìm thấy trong chế độ trận đấu công bằng, nhấp vào i bên dưới nút chuyển đổi để xem.'
	},
	[99005] = {
		id = 99005,
		fmt = '5. In a Fair Match, the substitute lineup must be set up in advance. If the number of heroes #C0xF76B45# is less than the minimum combination limit, the combination cannot be determined for the BAN selection stage.',
		fmt_ma = '5. Dalam pertarungan Adil, formasi gantian perlu disediakan terlebih dahulu. Jika jumlah hero #C0xF76B45#kurang daripada had minimum kombinasi, maka kombinasi tidak dapat kenal pasti hero yang boleh digunakan dalam fasa BAN.  ',
