	[99006] = {
		id = 99006,
		fmt = '6. Both Unlimited Mode and Fair Mode use the #C0xF76B45#6V6#C0xFFFFFF# mode, where the attributes #C0xF76B45# of heroes #C0xFFFFFF# will be significantly adjusted. Rare attributes will be included, and they will also be adjusted accordingly. The hero’s speed attribute will determine the battle order.',
		fmt_ma = '6. Kedua-dua mod Tanpa Had dan Adil menggunakan mod permainan #C0xF76B45#6V6#C0xFFFFFF#, atribut #C0xF76B45#hero#C0xFFFFFF# akan disesuaikan dengan baik. Atribut kelangkaan berbeza akan dimasukkan dan disesuaikan secara berasingan. Atribut kelajuan hero menentukan susunan pertempuran.  ',
		fmt_en = '6. Both Unlimited Mode and Fair Mode use the #C0xF76B45#6V6#C0xFFFFFF# mode, where the attributes #C0xF76B45# of heroes #C0xFFFFFF# will be significantly adjusted. Rare attributes will be included, and they will also be adjusted accordingly. The hero’s speed attribute will determine the battle order.',
		fmt_in = '6. Baik mode Tidak Terbatas maupun Adil menggunakan format pertempuran #C0xF76B45#6V6#C0xFFFFFF#, atribut #C0xF76B45# hero #C0xFFFFFF# akan disesuaikan secara optimal, atribut kelangkaan yang berbeda akan disesuaikan sesuai proporsi. Kecepatan hero akan menentukan urutan giliran.  ',
		fmt_th = '6. ทั้งโหมดไม่จำกัดและโหมดยุติธรรมใช้ระบบ #C0xF76B45#6V6#C0xFFFFFF# แก้ไขค่าสถานะฮีโร่ให้เหมาะสม ระดับความหายากและค่าสถานะต่าง ๆ ถูกปรับให้เหมาะสม ความเร็วฮีโร่กำหนดลำดับการต่อสู้',
		fmt_ph = '6. Parehong Unlimited at Fair Mode ay 6v6 format. Hero stats ay fixed, at rare stats ay adjusted. Speed stat magdidikta ng battle turn order',
		fmt_vn = '6. Cả chế độ đấu không giới hạn và chế độ đấu công bằng đều áp dụng chế độ 1 trò chơi #C0xF76B45#6V6#C0xFFFFFF#, thuộc tính #C0xF76B45# của anh hùng #C0xFFFFFF# sẽ được sửa khá tốt. thuộc tính hiếm khác nhau sẽ được đưa vào. Nó cũng sẽ được sửa đổi theo một chiều tương ứng. Thuộc tính tốc độ của anh hùng sẽ xác định thứ tự trận chiến.'
