	[99009] = {
		id = 99009,
		fmt = '9. Battles in both Unlimited Mode and Fair Mode last up to 20 rounds. In a battle, a side’s heroes will be considered defeated if all heroes are knocked out. If there is no winner by the end of the round, the side with more HP will be declared the winner.',
		fmt_ma = '9. Pertarungan dalam mod Tanpa Had dan Adil berlangsung sehingga 20 pusingan. Dalam pertarungan, hero satu pihak dianggap kalah jika semua hero kalah. Jika tiada pemenang selepas pusingan tamat, pihak dengan darah lebih banyak dianggap menang.',
		fmt_en = '9. Battles in both Unlimited Mode and Fair Mode last up to 20 rounds. In a battle, a side’s heroes will be considered defeated if all heroes are knocked out. If there is no winner by the end of the round, the side with more HP will be declared the winner.',
		fmt_in = '9. Pertarungan dalam mode Tidak Terbatas dan mode Adil berlangsung hingga 20 ronde. Dalam pertempuran, jika semua hero dari satu sisi dikalahkan, dianggap kalah. Jika tidak ada pemenang di akhir ronde, pihak dengan sisa HP terbanyak akan menang.  ',
		fmt_th = '9. การต่อสู้ในทั้งสองโหมดมี 20 รอบ หากฮีโร่ฝ่ายใดฝ่ายหนึ่งตายหมดจะถือว่าแพ้ หากจบรอบแล้วไม่มีผู้ชนะ ฝ่ายที่มีพลังชีวิตมากกว่าจะเป็นฝ่ายชนะ',
		fmt_ph = '9. Ang match ay hanggang 20 rounds. Kung lahat ng heroes ng isang side natalo, talo na. Kung walang winner after 20 rounds, panalo ang side na may mas mataas na HP',
		fmt_vn = '9. Trận chiến ở Chế độ Trận đấu Không giới hạn và Chế độ Trận đấu Công bằng kéo dài tới 20 hiệp. Trong trận chiến, anh hùng của một bên sẽ bị coi là thất bại nếu tất cả các anh hùng đều bị đánh bại. Nếu không có người chiến thắng ở cuối vòng đấu. Bên có nhiều máu hơn sẽ được coi là bên chiến thắng.'
	},
