	[100003] = {
		id = 100003,
		fmt = '3. During the season, #C0xF76B45#rewards will be issued every week 30 minutes after the end of the match on Sunday, #C0xFFFFFF#, with rewards based on the corresponding points in both modes #C0xF76B45#Note: At least every week, only players who participate in 3 matches (regardless of mode) can receive settlement rewards.',
		fmt_ma = '3. Dalam musim pertandingan, ganjaran penyelesaian akan dikeluarkan setiap minggu, 30 minit selepas perlawanan berakhir pada hari Ahad. Ganjaran berdasarkan mata tertinggi dalam dua mod. Nota: Sekurang-kurangnya setiap minggu, hanya pemain yang menyertai sekurang-kurangnya 3 perlawanan (tidak kira mod) layak menerima ganjaran penyelesaian.  ',
		fmt_en = '3. During the season, #C0xF76B45#rewards will be issued every week 30 minutes after the end of the match on Sunday, #C0xFFFFFF#, with rewards based on the corresponding points in both modes #C0xF76B45#Note: At least every week, only players who participate in 3 matches (regardless of mode) can receive settlement rewards.',
		fmt_in = '3. Dalam musim, #C0xF76B45# hadiah mingguan akan diberikan 30 menit setelah pertandingan terakhir hari Minggu #C0xFFFFFF#, hadiah didasarkan pada poin tertinggi dari dua mode #C0xF76B45# Catatan: Setiap minggu, hanya pemain yang berpartisipasi minimal 3 pertandingan (mode apapun) yang bisa menerima hadiah mingguan.  ',
		fmt_th = '3. ในฤดูกาล #C0xF76B45#จะมีการมอบรางวัลรายสัปดาห์ 30 นาทีหลังจบการต่อสู้ในวันอาทิตย์ #C0xFFFFFF# รางวัลจะขึ้นอยู่กับคะแนนสูงสุดในสองโหมด #C0xF76B45# หมายเหตุ: ต้องเล่นอย่างน้อย 3 แมตช์ต่อสัปดาห์ (โหมดใดก็ได้) ถึงจะได้รับรางวัล',
		fmt_ph = '3. Weekly rewards ng season ilalabas 30 mins after last match every Sunday, kailangan maglaro ng at least 3 matches per week para maka-claim',
		fmt_vn = '3. Trong mùa giải, #C0xF76B45# sẽ phát hành phần thưởng giải quyết mỗi tuần 30 phút sau khi kết thúc trận đấu vào Chủ nhật, #C0xFFFFFF#, phần thưởng theo khoảng thời gian tương ứng với số điểm cao hơn ở hai chế độ #C0xF76B45# Lưu ý. : Ít nhất mỗi tuần Chỉ những người chơi tham gia 3 trận đấu (bất kể chế độ) mới có thể nhận được phần thưởng quyết toán'
	},
	[100004] = {
		id = 100004,
		fmt = '4. At the end of the season, #C0xF76B45#settlement rewards will be issued 30 minutes after the match ends on the last day. Ranking rewards will be based on the highest current ranking in both modes. #C0xF76B45#Note: In the season, only players who have participated in at least 1 match (regardless of mode) can receive settlement rewards.',
