	[101003] = {
		id = 101003,
		fmt = '3. After linking the two commanders, the linked mission content will be opened, and the tasks will be divided into coordinated and solo tasks. #C0xF76B45#All tasks are open for returning commanders, but only some coordinated tasks require the participation of veteran commanders, so the veteran commander’s operation interface will only display coordinated task content.',
		fmt_ma = '3. Selepas dua komander berhubung, tugasan pautan dibuka, dibahagikan kepada tugasan kerjasama dan tugasan individu. Semua tugasan terbuka untuk komander kembali, hanya beberapa tugasan kerjasama memerlukan penyertaan komander veteran, jadi antara muka hanya menunjukkan tugasan kerjasama untuk komander veteran.  ',
		fmt_en = '3. After linking the two commanders, the linked mission content will be opened, and the tasks will be divided into coordinated and solo tasks. #C0xF76B45#All tasks are open for returning commanders, but only some coordinated tasks require the participation of veteran commanders, so the veteran commander’s operation interface will only display coordinated task content.',
		fmt_in = '3. Setelah kedua Komandan terhubung, misi koneksi akan terbuka, terdiri dari misi kerja sama dan misi individu. #C0xF76B45#Semua misi terbuka untuk Komandan yang kembali, hanya beberapa misi kerja sama yang memerlukan partisipasi Komandan veteran, maka antarmuka veteran hanya menampilkan misi kerja sama.  ',
		fmt_th = '3. หลังจากเชื่อมโยงทั้งสอง ฝ่ายจะได้รับภารกิจเชื่อมโยง แบ่งเป็นภารกิจร่วมมือและภารกิจเดี่ยว #C0xF76B45#ภารกิจทั้งหมดเปิดให้ผู้บัญชาการที่กลับมาเล่นใหม่ มีเพียงภารกิจร่วมมือบางส่วนที่ต้องการผู้บัญชาการเก่าเข้าร่วม หน้ากิจกรรมผู้บัญชาการเก่าจะแสดงเฉพาะภารกิจร่วมมือ',
		fmt_ph = '3. Kapag linked na, mission content unlocked—may coop missions at solo missions. #C0xF76B45#Lahat ng missions open sa returning commander, may ilang coop missions na kelangan ng veteran commander participation#C0xFFFFFF#',
		fmt_vn = '3. Sau khi hai chỉ huy liên kết, nội dung nhiệm vụ liên kết sẽ được mở, nhiệm vụ được chia thành nhiệm vụ phối hợp và nhiệm vụ đơn lẻ. #C0xF76B45#Tất cả nhiệm vụ đều được mở cho chỉ huy hồi quy, chỉ một số nhiệm vụ phối hợp cần sự tham gia của chỉ huy kỳ cựu, do đó giao diện hoạt động của chỉ huy kỳ cựu chỉ hiển thị nội dung nhiệm vụ phối hợp.'
	},
	[101004] = {
		id = 101004,
		fmt = '4. After completing each task, #C0xF76B45#both commanders will receive mission reward points#C0xFFFFFF#, and when the points reach a certain value, the Reunion Chest can be opened. #C0xF76B45#This means that both sides\' chest progress is synchronized, and they need to work together to open it!',
		fmt_ma = '4. Selepas melengkapkan setiap tugasan, kedua-dua komander menerima mata ganjaran tugasan. Apabila mata mencapai nilai tertentu, Peti Penyatuan boleh dibuka, kemajuan peti kedua-dua pihak adalah sama, perlu bekerjasama untuk membukanya.  ',
		fmt_en = '4. After completing each task, #C0xF76B45#both commanders will receive mission reward points#C0xFFFFFF#, and when the points reach a certain value, the Reunion Chest can be opened. #C0xF76B45#This means that both sides\' chest progress is synchronized, and they need to work together to open it!',
		fmt_in = '4. Setelah menyelesaikan tiap misi, #C0xF76B45#kedua Komandan akan mendapatkan poin hadiah misi#C0xFFFFFF#, bila poin mencapai nilai tertentu, akan membuka Peti Reuni, #C0xF76B45#progress peti disinkronkan di kedua sisi, butuh kerja sama untuk membukanya!  ',
		fmt_th = '4. เมื่อทำภารกิจสำเร็จ #C0xF76B45#ทั้งสองฝ่ายจะได้รับคะแนนภารกิจ#C0xFFFFFF# เมื่อคะแนนถึงค่าที่กำหนด จะปลดล็อกหีบสมานฉันท์ #C0xF76B45#หมายถึงความก้าวหน้าหีบของทั้งสองฝ่ายเท่ากัน ต้องร่วมมือกันเพื่อเปิด',
		fmt_ph = '4. After each mission, #C0xF76B45#parehong commanders makakatanggap ng mission points#C0xFFFFFF#. When points reach a threshold, Reunion Chest puwedeng buksan—#C0xF76B45#progress ng chest pareho para sa dalawang players#C0xFFFFFF#',
		fmt_vn = '4. Sau khi hoàn thành mỗi nhiệm vụ, #C0xF76B45#cả hai chỉ huy sẽ nhận được điểm thưởng nhiệm vụ#C0xFFFFFF#, khi điểm đạt đến một giá trị nhất định, có thể mở Rương Tái Hợp, #C0xF76B45#tức là tiến trình rương của cả hai bên là đồng nhất, cần cùng nhau nỗ lực để mở nhé!'
	},
