	[102002] = {
		id = 102002,
		fmt = '1. Faction opening time: #C0xF76B45#Monday 10:00#C0xFFFFFF# to #C0xF76B45#Sunday 21:45#C0xFFFFFF#; the remaining time is faction closing time, during which faction dungeon challenges and competing for National Honor King cannot be done. All factions will reset on Monday 05:00 weekly.',
		fmt_ma = '1. Masa pembukaan faksi: #C0xF76B45#Isnin 10:00#C0xFFFFFF# hingga #C0xF76B45#Ahad 21:45#C0xFFFFFF#; masa selebihnya adalah masa faksi ditutup, dalam masa ini tidak boleh mencabar dungeon faksi dan merebut Kebesaran Raja Negara. Pada Isnin 05:00 setiap minggu, semua faksi akan diset semula.  ',
		fmt_en = '1. Faction opening time: #C0xF76B45#Monday 10:00#C0xFFFFFF# to #C0xF76B45#Sunday 21:45#C0xFFFFFF#; the remaining time is faction closing time, during which faction dungeon challenges and competing for National Honor King cannot be done. All factions will reset on Monday 05:00 weekly.',
		fmt_in = '1. Waktu pembukaan faksi: #C0xF76B45#Senin 10:00#C0xFFFFFF# hingga #C0xF76B45#Minggu 21:45#C0xFFFFFF#; waktu selebihnya adalah waktu tutup faksi, selama periode ini tidak dapat menantang dungeon faksi dan memperebutkan Gelar Kehormatan Raja Negara. Semua faksi akan direset setiap Senin pukul 05:00.',
		fmt_th = '1. เวลาเปิดฝ่าย: #C0xF76B45#วันจันทร์ 10:00#C0xFFFFFF# ถึง #C0xF76B45#วันอาทิตย์ 21:45#C0xFFFFFF#; เวลาที่เหลือคือเวลาปิดฝ่าย ในช่วงเวลานี้ไม่สามารถท้าดันเจี้ยนฝ่ายและชิงแชมป์เกียรติยศชาติได้ วันจันทร์ 05:00 ของทุกสัปดาห์จะรีเซ็ตฝ่ายทั้งหมด',
		fmt_ph = '1. Oras ng pagbubukas ng Faction: #C0xF76B45#Lunes 10:00#C0xFFFFFF# hanggang #C0xF76B45#Linggo 21:45#C0xFFFFFF#; ang natitirang oras ay panahon ng pagsasara ng Faction, sa panahong ito hindi maaaring hamunin ang dungeon ng Faction at agawin ang Pambansang Dangal na Pinuno. Tuwing Lunes 05:00 ng umaga, ire-reset ang lahat ng Faction.',
		fmt_vn = '1. Thời gian mở phe: #C0xF76B45#Thứ Hai 10:00#C0xFFFFFF# đến #C0xF76B45#Chủ Nhật 21:45#C0xFFFFFF#; thời gian còn lại là thời gian đóng phe, trong thời gian này không thể khiêu chiến phó bản phe và tranh đoạt Quốc Chủ Vinh Dự. Thứ Hai 05:00 hàng tuần sẽ thiết lập lại tất cả các phe.'
	},
	[102003] = {
		id = 102003,
		fmt = '2. The strength dungeon has a certain number of successful challenges each day. This number will be reduced after successful challenges but will not be reduced if you fail. It will reset at 05:00 daily.',
		fmt_ma = '2. Penjara kuasa mempunyai jumlah cabaran berjaya tertentu setiap hari. Jumlah ini akan dikurangkan selepas cabaran berjaya, tidak dikurangkan jika gagal. Jumlah cabaran akan diset semula pada 05:00 setiap hari.  ',
		fmt_en = '2. The strength dungeon has a certain number of successful challenges each day. This number will be reduced after successful challenges but will not be reduced if you fail. It will reset at 05:00 daily.',
		fmt_in = '2. Dungeon kekuatan memiliki jumlah tantangan sukses tertentu setiap hari. Jumlah ini akan berkurang setelah tantangan berhasil, tetapi tidak akan berkurang jika gagal. Akan direset setiap hari pukul 05:00.',
		fmt_th = '2. ดันเจี้ยนกองกำลังมีจำนวนครั้งที่ท้าทายสำเร็จในแต่ละวัน ตัวเลขนี้จะถูกหักหลังจากท้าทายสำเร็จ แต่จะไม่ถูกหักถ้าล้มเหลว จะรีเซ็ตเวลา 05:00 ทุกวัน',
		fmt_ph = '2. Ang Dungeon ng Lakas ay may limitadong bilang ng matagumpay na hamon bawat araw. Mababawasan ang bilang na ito kapag matagumpay na hamunin, ngunit hindi mababawasan kung mabigo. Ire-reset ito araw-araw tuwing 05:00.',
		fmt_vn = '2. Hầm ngục lực lượng có một số thử thách thành công nhất định mỗi ngày. Con số này sẽ bị trừ sau khi thử thách thành công, nhưng sẽ không bị trừ nếu thất bại. Nó sẽ được đặt lại vào lúc 05:00 hàng ngày.'
	},
	[102004] = {
		id = 102004,
		fmt = '3. Each cycle is fixed at 8 different strengths, and each strength corresponds to 5 copies of the force.',
		fmt_ma = '3. Setiap kitaran terdiri daripada 8 kuasa berbeza, setiap kuasa mempunyai 5 salinan.  ',
		fmt_en = '3. Each cycle is fixed at 8 different strengths, and each strength corresponds to 5 copies of the force.',
		fmt_in = '3. Setiap siklus tetap memiliki 8 faksi berbeda dan setiap faksi memiliki 5 salinan dungeon.',
		fmt_th = '3. แต่ละรอบจะถูกกำหนดไว้ที่ 8 กองกำลังต่างกัน และแต่ละกองกำลังจะมีดันเจี้ยน 5 แห่งที่เกี่ยวข้อง',
		fmt_ph = '3. Bawat cycle ay may nakapirming 8 iba\'t ibang lakas at bawat lakas ay may katumbas na 5 dungeon.',
		fmt_vn = '3. Mỗi chu kỳ được cố định ở 8 lực khác nhau và mỗi lực tương ứng với 5 bản sao của lực.'
	},
	[102005] = {
		id = 102005,
		fmt = '4. Strength copies are one-time copies and cannot be challenged repeatedly;',
		fmt_ma = '4. Salinan kuasa adalah salinan sekali sahaja, tidak boleh dicabar berulang kali.  ',
