	[102006] = {
		id = 102006,
		fmt = '5. After completing all difficulties with each force, you can challenge to become the National Honor King of the corresponding force.',
		fmt_ma = '5. Selepas menyelesaikan semua tahap kesukaran untuk setiap kuasa, anda boleh mencabar menjadi Raja Kebesaran kuasa tersebut.  ',
		fmt_en = '5. After completing all difficulties with each force, you can challenge to become the National Honor King of the corresponding force.',
		fmt_in = '5. Setelah menyelesaikan semua tingkat kesulitan dari setiap faksi, Anda dapat menantang untuk menjadi Raja Kehormatan dari faksi tersebut.',
		fmt_th = '5. หลังจากผ่านความยากทั้งหมดของแต่ละกองกำลังแล้ว คุณสามารถท้าทายเพื่อเป็นแชมป์เกียรติยศของกองกำลังนั้นได้',
		fmt_ph = '5. Pagkatapos makumpleto ang lahat ng antas ng kahirapan ng bawat faction, maaari kang hamunin upang maging Pambansang Dangal na Pinuno ng nasabing faction.',
		fmt_vn = '5. Sau khi hoàn thành tất cả các độ khó với mỗi thế lực, bạn có thể thử thách để trở thành Quốc chủ danh dự của thế lực tương ứng.'
	},
	[102007] = {
		id = 102007,
		fmt = '6. Each force has only 1 National Honor King; and each player can only become the National Honor King of one force. After becoming the king of a new force, their qualification in other forces will automatically be removed from the lineup.',
		fmt_ma = '6. Setiap kuasa hanya mempunyai 1 Raja Kebesaran; setiap pemain hanya boleh menjadi Raja Kebesaran satu kuasa. Selepas menjadi Raja Kebesaran kuasa baru, kelayakan di kuasa lain akan dipadamkan secara automatik.  ',
		fmt_en = '6. Each force has only 1 National Honor King; and each player can only become the National Honor King of one force. After becoming the king of a new force, their qualification in other forces will automatically be removed from the lineup.',
		fmt_in = '6. Setiap faksi hanya memiliki 1 Raja Kehormatan; setiap pemain hanya dapat menjadi Raja Kehormatan dari satu faksi. Setelah menjadi Raja di faksi baru, keanggotaan di faksi lain akan dihapus secara otomatis.',
		fmt_th = '6. แต่ละกองกำลังมีแชมป์เกียรติยศเพียง 1 คน และผู้เล่นแต่ละคนสามารถเป็นแชมป์เกียรติยศได้เพียงหนึ่งกองกำลัง เมื่อกลายเป็นแชมป์ของกองกำลังใหม่ สิทธิ์ในทีมของกองกำลังอื่นจะถูกลบโดยอัตโนมัติ',
		fmt_ph = '6. Bawat faction ay may iisang Pambansang Dangal na Pinuno; at bawat manlalaro ay maaari lamang maging Pambansang Dangal na Pinuno ng isang faction. Kapag naging Pinuno ng bagong faction, awtomatikong mawawala ang karapatan sa iba pang faction.',
		fmt_vn = '6. Mỗi thế lực chỉ có 1 Quốc chủ Danh dự; và mỗi người chơi chỉ có thể trở thành Quốc chủ Danh dự của một thế lực. Sau khi trở thành quán chủ của thế lực mới, tự động xóa tư cách trong đội hình của các thế lực khác.'
	},
	[102008] = {
		id = 102008,
		fmt = '7. The National Honor King challenge has a certain waiting time, and after successfully completing the challenge, you need to rest for a period of time before challenging again; however, there is no limit on the number of challenges.',
		fmt_ma = '7. Cabaran Kebesaran Raja ada masa rehat tertentu; selepas berjaya, perlu berehat sebelum boleh cabar semula; tiada had bilangan cabaran.  ',
		fmt_en = '7. The National Honor King challenge has a certain waiting time, and after successfully completing the challenge, you need to rest for a period of time before challenging again; however, there is no limit on the number of challenges.',
		fmt_in = '7. Tantangan Raja Kehormatan memiliki waktu cooldown tertentu, setelah tantangan berhasil harus beristirahat sebelum dapat menantang lagi; tidak ada batasan jumlah tantangan.',
		fmt_th = '7. การท้าทายแชมป์เกียรติยศมีเวลารอจำกัด หลังจากท้าทายสำเร็จ ต้องพักสักระยะก่อนจะท้าทายใหม่ได้ แต่ไม่มีจำกัดจำนวนครั้งในการท้าทาย',
		fmt_ph = '7. Ang hamon para sa Pambansang Dangal na Pinuno ay may cooldown, pagkatapos ng matagumpay na hamon, kailangan munang magpahinga bago muling hamunin; walang limitasyon sa bilang ng hamon.',
		fmt_vn = '7. Thử thách Vinh Dự Quốc Chủ có giới hạn thời gian chờ nhất định, sau khi thử thách thành công cần nghỉ ngơi một thời gian mới có thể thử thách lại; nhưng không có giới hạn số lần thử thách.'
	},
	[102009] = {
		id = 102009,
		fmt = '8. The Honor King challenge requires heroes with designated attributes (only meeting one of the first or second attributes is sufficient). If no heroes with the corresponding attributes are available, you cannot participate in the challenge.',
		fmt_ma = '8. Cabaran Raja memerlukan mempunyai wira dengan atribut tertentu (cukup memenuhi salah satu daripada dua atribut). Jika tiada wira dengan atribut tersebut, anda tidak boleh sertai cabaran.  ',
		fmt_en = '8. The Honor King challenge requires heroes with designated attributes (only meeting one of the first or second attributes is sufficient). If no heroes with the corresponding attributes are available, you cannot participate in the challenge.',
		fmt_in = '8. Tantangan Raja memerlukan hero dengan atribut tertentu (cukup memenuhi salah satu dari dua atribut pertama atau kedua), jika tidak memiliki hero dengan atribut yang sesuai, tidak dapat mengikuti tantangan.',
		fmt_th = '8. การท้าทายแชมป์ต้องมีฮีโร่ที่มีคุณสมบัติตรงตามที่กำหนด (เพียงหนึ่งในสองคุณสมบัติแรก) หากไม่มีฮีโร่คุณสมบัตินั้นจะไม่สามารถเข้าร่วมท้าทายได้',
		fmt_ph = '8. Ang hamon para sa pagiging Pinuno ay nangangailangan ng bayani na may tinukoy na katangian (kailangan lamang matugunan ang isa sa dalawang pangunahing katangian), kung walang bayani na may kinakailangang katangian, hindi maaaring sumali sa hamon.',
		fmt_vn = '8. Thử thách Quán Chủ yêu cầu phải có anh hùng sở hữu thuộc tính chỉ định (chỉ cần đáp ứng một trong hai thuộc tính thứ nhất hoặc thứ hai), nếu không có anh hùng có thuộc tính giới hạn tương ứng, bạn sẽ không thể tham gia thử thách.'
	},
