	[102016] = {
		id = 102016,
		fmt = '3. The accumulated points will be automatically added by the system in small amounts every day at 05:00. You can also use diamonds to buy them, with a daily purchase limit. Points can also be earned by completing faction dungeons.',
		fmt_ma = '3. Mata terkumpul akan ditambah secara automatik oleh sistem dalam jumlah kecil setiap hari pada jam 05:00, anda juga boleh membeli dengan berlian, had pembelian harian terhad; menyelesaikan cabaran kuasa juga boleh mendapatkan mata terkumpul.  ',
		fmt_en = '3. The accumulated points will be automatically added by the system in small amounts every day at 05:00. You can also use diamonds to buy them, with a daily purchase limit. Points can also be earned by completing faction dungeons.',
		fmt_in = '3. Poin peningkatan akan ditambahkan otomatis oleh sistem setiap hari pukul 05:00, Anda juga dapat membelinya dengan berlian, jumlah pembelian harian terbatas; menyelesaikan dungeon faksi juga dapat memperoleh poin peningkatan.',
		fmt_th = '3. แต้มสะสมจะถูกเพิ่มโดยระบบอัตโนมัติทีละเล็กน้อยทุกวันเวลา 05:00 คุณสามารถใช้เพชรซื้อได้โดยมีจำนวนจำกัดต่อวัน และผ่านด่านกองกำลังก็จะได้รับแต้มสะสมด้วย',
		fmt_ph = '3. Ang mga puntos ng akumulasyon ay awtomatikong madaragdagan ng kaunti bawat araw tuwing 05:00, maaari ka ring bumili gamit ang mga diamante, may limitasyon sa bilang ng pagbili bawat araw; matagumpay na pag-clear ng dungeon ay maaari ring magbigay ng mga puntos ng akumulasyon.',
		fmt_vn = '3. Điểm cộng dồn sẽ được hệ thống tự động cộng một lượng nhỏ mỗi ngày vào lúc 05:00, bạn cũng có thể dùng kim cương để mua, số lần mua mỗi ngày có giới hạn; vượt ải các thế lực cũng có thể nhận được điểm cộng dồn.'
