	[103001] = {
		id = 103001,
		fmt = '1. The cross-server factions also have 8 different factions, and each cross-server faction can station 1 cross-server tavern owner and 7 cross-server citizens.',
		fmt_ma = '1. Kuasa lintas-server juga mempunyai 8 kuasa berbeza, dan setiap kuasa boleh menempatkan 1 tuan kedai lintas-server dan 7 penduduk lintas-server.  ',
		fmt_en = '1. The cross-server factions also have 8 different factions, and each cross-server faction can station 1 cross-server tavern owner and 7 cross-server citizens.',
		fmt_in = '1. Faksi lintas server juga memiliki 8 faksi berbeda, dan setiap faksi lintas server dapat ditempati oleh 1 Raja lintas server dan 7 warga lintas server.',
		fmt_th = '1. กองกำลังข้ามเซิร์ฟเวอร์ก็มี 8 กองกำลัง และแต่ละกองกำลังข้ามเซิร์ฟเวอร์จะมีแชมป์ข้ามเซิร์ฟเวอร์ 1 คนและชาวบ้านข้ามเซิร์ฟเวอร์ 7 คน',
		fmt_ph = '1. Sa Faction ng inter-server, mayroong 8 iba’t ibang faction din, at bawat faction ay maaaring magtalaga ng 1 inter-server leader at 7 inter-server citizens.',
		fmt_vn = '1. Các thế lực liên server cũng có 8 thế lực khác nhau, và mỗi thế lực liên server có thể đóng quân 1 quán chủ liên server và 7 kiều dân liên server.'
	},
	[103002] = {
		id = 103002,
		fmt = '2. After clearing all the difficulty levels of the local faction dungeon, you can challenge to become the Honorary King or Citizen of the cross-server faction.',
		fmt_ma = '2. Selepas melepasi semua tahap kesukaran dungeon kuasa tempatan, anda boleh mencabar untuk menjadi Raja atau Rakyat Hormat lintas-server.  ',
		fmt_en = '2. After clearing all the difficulty levels of the local faction dungeon, you can challenge to become the Honorary King or Citizen of the cross-server faction.',
		fmt_in = '2. Setelah menyelesaikan semua tingkat kesulitan dari dungeon faksi lokal, Anda dapat menantang untuk menjadi Raja Kehormatan atau Warga Kehormatan di lintas server.',
		fmt_th = '2. หลังผ่านความยากทั้งหมดของดันเจี้ยนกองกำลังท้องถิ่น คุณสามารถท้าทายเป็นแชมป์หรือชาวบ้านเกียรติยศข้ามเซิร์ฟเวอร์ได้',
		fmt_ph = '2. Pagkatapos makumpleto ang lahat ng antas ng kahirapan ng dungeon ng local Faction, maaari kang hamunin upang maging Honorary Leader o Citizen ng inter-server.',
		fmt_vn = '2. Sau khi vượt qua tất cả các độ khó của phó bản thế lực bản địa, bạn có thể thử thách để trở thành Quốc Chủ hoặc Quốc Dân vinh dự của liên server.'
	},
	[103003] = {
		id = 103003,
		fmt = '3. Each player can only be the honorary king or a common citizen of one cross-server faction. Once you become the tavern owner or a citizen of a new faction, the old team will be automatically deleted.',
		fmt_ma = '3. Setiap pemain hanya boleh menjadi Raja Hormat atau Rakyat satu kuasa lintas-server. Selepas menjadi tuan kedai atau rakyat kuasa baru, formasi lama akan dipadamkan secara automatik.  ',
		fmt_en = '3. Each player can only be the honorary king or a common citizen of one cross-server faction. Once you become the tavern owner or a citizen of a new faction, the old team will be automatically deleted.',
		fmt_in = '3. Setiap pemain hanya dapat menjadi Raja Kehormatan atau Warga dari satu faksi lintas server. Setelah menjadi Raja atau Warga di faksi baru, formasi lama akan dihapus secara otomatis.',
		fmt_th = '3. ผู้เล่นแต่ละคนสามารถเป็นแชมป์เกียรติยศหรือชาวบ้านของกองกำลังข้ามเซิร์ฟเวอร์ได้เพียงหนึ่งกองกำลัง เมื่อกลายเป็นแชมป์หรือชาวบ้านกองกำลังใหม่ ทีมเก่าจะถูกลบโดยอัตโนมัติ',
		fmt_ph = '3. Ang bawat manlalaro ay maaari lamang maging honorary leader o citizen ng isang inter-server faction. Kapag naging bagong leader o citizen, ang lumang lineup ay awtomatikong matatanggal.',
		fmt_vn = '3. Mỗi người chơi chỉ có thể là quốc chủ danh dự hoặc dân thường của một thế lực liên server. Sau khi trở thành quán chủ hoặc dân thường của thế lực mới, đội hình cũ sẽ tự động bị xóa.'
	},
	[103004] = {
		id = 103004,
		fmt = '4. The cross-server tavern owner challenge also has a cooldown time. After successfully completing the challenge, a rest period is required before trying again; however, there is no limit to the number of challenges.',
		fmt_ma = '4. Cabaran tuan kedai lintas-server juga mempunyai masa rehat tertentu; selepas cabaran berjaya, perlu berehat sebelum boleh cabar semula; tiada had bilangan cabaran.  ',
		fmt_en = '4. The cross-server tavern owner challenge also has a cooldown time. After successfully completing the challenge, a rest period is required before trying again; however, there is no limit to the number of challenges.',
		fmt_in = '4. Tantangan Raja lintas server juga memiliki waktu cooldown tertentu, setelah tantangan berhasil harus beristirahat sebelum dapat menantang lagi; tidak ada batasan jumlah tantangan.',
		fmt_th = '4. การท้าทายแชมป์ข้ามเซิร์ฟเวอร์มีเวลารอจำกัด หลังท้าทายสำเร็จ ต้องพักสักระยะก่อนจะท้าทายใหม่ได้ แต่ไม่จำกัดจำนวนครั้งในการท้าทาย',
		fmt_ph = '4. Ang hamon para sa inter-server leader ay may cooldown din, pagkatapos ng matagumpay na hamon kailangang magpahinga bago muling sumubok; walang limitasyon sa bilang ng hamon.',
		fmt_vn = '4. Thử thách quán chủ liên server cũng có thời gian hồi chiêu nhất định, sau khi thử thách thành công cần nghỉ ngơi một thời gian mới có thể thử thách lại; nhưng không giới hạn số lần thử thách.'
	},
	[103005] = {
		id = 103005,
		fmt = '5. Challenging a Cross-server Tavern Owner requires a hero with the designated attributes (only one of the first or second attributes needs to be met). If no hero with the corresponding restricted attribute is available, the challenge cannot be initiated.',
		fmt_ma = '5. Cabaran Tuan Kedai Lintas Server memerlukan wira yang mempunyai atribut tertentu (cukup memenuhi salah satu dari dua atribut); jika tiada wira dengan atribut tersebut, cabaran tidak boleh diteruskan.  ',
		fmt_en = '5. Challenging a Cross-server Tavern Owner requires a hero with the designated attributes (only one of the first or second attributes needs to be met). If no hero with the corresponding restricted attribute is available, the challenge cannot be initiated.',
		fmt_in = '5. Tantangan Raja lintas server memerlukan hero dengan atribut tertentu (cukup memenuhi salah satu dari dua atribut pertama atau kedua), jika tidak memiliki hero dengan atribut yang sesuai, tidak dapat mengikuti tantangan.',
		fmt_th = '5. การท้าทายแชมป์ข้ามเซิร์ฟเวอร์ต้องมีฮีโร่ที่มีคุณสมบัติตรงตามที่กำหนด (เพียงหนึ่งในสองคุณสมบัติแรก) หากไม่มีฮีโร่คุณสมบัตินั้นจะไม่สามารถท้าทายได้',
		fmt_ph = '5. Ang hamon para sa Inter-server Leader ay nangangailangan ng bayani na may itinakdang katangian (kailangan lamang matugunan ang isa sa dalawang pangunahing katangian), kung walang bayani na may kaukulang katangian, hindi makakalahok sa hamon.',
		fmt_vn = '5. Khiêu chiến Quán Chủ Liên Server yêu cầu phải có tướng sở hữu thuộc tính chỉ định (chỉ cần đáp ứng một trong hai thuộc tính thứ nhất hoặc thứ hai), nếu không có tướng thuộc tính giới hạn tương ứng thì không thể tiến hành khiêu chiến.'
	},
