	[105001] = {
		id = 105001,
		fmt = '1. When the conditions are met, the host can expel other players from the room, and other players can also vote to expel the host.',
		fmt_ma = '1. Apabila memenuhi syarat, tuan rumah boleh mengusir pemain lain dari bilik, dan pemain lain juga boleh mengundi untuk mengusir tuan rumah dari bilik.  ',
		fmt_en = '1. When the conditions are met, the host can expel other players from the room, and other players can also vote to expel the host.',
		fmt_in = '1. Jika memenuhi syarat, host dapat mengeluarkan pemain lain dari ruangan, dan pemain lain juga dapat melakukan voting untuk mengeluarkan host dari ruangan.',
		fmt_th = '1.เมื่อมีเงื่อนไขครบ เจ้าของห้องสามารถไล่ผู้เล่นอื่นออกจากห้องได้ และผู้เล่นคนอื่นสามารถลงคะแนนเพื่อไล่เจ้าของห้องออก',
		fmt_ph = '1. Kapag natugunan ang mga kinakailangan, maaaring palayasin ng host ang ibang manlalaro sa room, at maaaring bumoto ang ibang manlalaro para palayasin ang host.',
		fmt_vn = '1. Khi đáp ứng đủ điều kiện, chủ nhà có thể đuổi những người chơi khác ra khỏi phòng, và những người chơi khác cũng có thể bỏ phiếu để đuổi chủ nhà ra khỏi phòng.'
	},
	[105002] = {
		id = 105002,
		fmt = '2. The following 3 conditions must be met: First, at least 3 players in the room must have completed the challenge; Second, the player being invited to leave must have been in the room for at least 3 hours; Third, the number of successful challenges by the host is 0 or not attempted yet.',
		fmt_ma = '2. Tiga syarat perlu dipenuhi: Pertama, dalam bilik sekurang-kurangnya 3 pemain telah menyelesaikan cabaran; Kedua, pemain yang diundang keluar mesti berada dalam bilik sekurang-kurangnya 3 jam; Ketiga, bilangan kejayaan cabaran diri adalah 0 atau belum mencabar.  ',
		fmt_en = '2. The following 3 conditions must be met: First, at least 3 players in the room must have completed the challenge; Second, the player being invited to leave must have been in the room for at least 3 hours; Third, the number of successful challenges by the host is 0 or not attempted yet.',
		fmt_in = '2. Harus memenuhi 3 syarat berikut: Pertama, ada setidaknya 3 pemain yang sudah menyelesaikan tantangan di dalam ruangan; Kedua, pemain yang akan dikeluarkan harus berada di dalam ruangan minimal 3 jam; Ketiga, jumlah tantangan sukses pemain tersebut adalah 0 atau belum pernah menantang.',
		fmt_th = '2.ต้องมีเงื่อนไขครบ 3 ข้อดังนี้: หนึ่ง ต้องมีผู้เล่นอย่างน้อย 3 คนที่ทำภารกิจสำเร็จในห้อง สอง ผู้เล่นที่จะถูกเชิญออกต้องอยู่ในห้องอย่างน้อย 3 ชั่วโมง สาม จำนวนครั้งที่ทำภารกิจสำเร็จต้องเป็น 0 หรือยังไม่ได้ทำภารกิจ',
		fmt_ph = '2. Kailangang matugunan ang 3 kondisyon: Una, kailangang may hindi bababa sa 3 manlalaro sa room na nakatapos ng challenge; Pangalawa, ang manlalarong paaalisin ay kailangang nasa room nang hindi bababa sa 3 oras; Pangatlo, ang bilang ng matagumpay na hamon ng manlalaro ay 0 o wala pang nagawang hamon.',
		fmt_vn = '2. Cần đáp ứng đủ 3 điều kiện sau: Một, trong phòng có ít nhất 3 người chơi hoàn thành thử thách; Hai, người chơi bị mời rời phòng phải ở trong phòng ít nhất 3 giờ; Ba, số lần Ta thành công thử thách là 0 hoặc chưa thử thách.'
