	[108006] = {
		id = 108006,
		fmt = '6. After exchanging the prize, the rewards will be gradually sent via email after the mini-game ends. Players who win prizes should check their email.',
		fmt_ma = '6. Selepas penebusan, ganjaran akan dihantar melalui e-mel selepas acara mini game berakhir, sila periksa e-mel anda',
