	[108007] = {
		id = 108007,
		fmt = '7. If a player receives a prize ticket but fails to exchange it before the mini-game ends in this round, the system will automatically scratch and exchange the ticket and send the prize notification to the player’s inbox on time.',
		fmt_ma = '7. Jika pemain menerima tiket menang tetapi tidak sempat menebus sebelum mini game berakhir, sistem akan automatik gores dan tebus hadiah, e-mel pemberitahuan akan dihantar tepat pada masanya',
		fmt_en = '7. If a player receives a prize ticket but fails to exchange it before the mini-game ends in this round, the system will automatically scratch and exchange the ticket and send the prize notification to the player’s inbox on time.',
		fmt_in = '7. Jika pemain mendapatkan kupon hadiah tetapi belum sempat menukarkan sebelum event berakhir, sistem akan otomatis menggosok dan menukarkan hadiah, lalu mengirim pemberitahuan hadiah ke kotak surat tepat waktu.',
		fmt_th = '7.หากได้รับคูปองรางวัลแต่ไม่แลกรางวัลก่อนจบมินิเกม ระบบจะทำการขูดบัตรให้อัตโนมัติและส่งอีเมลแจ้งรางวัล',
		fmt_ph = '7. Kung nakuha ang winning coupon ngunit hindi na-redeem bago matapos ang mini game sa cycle na iyon, awtomatikong i-scratch at i-redeem ng system ang coupon at ipapadala ang notification sa email.',
		fmt_vn = '7. Nếu người chơi nhận được vé trúng thưởng nhưng không kịp đổi thưởng trước khi kết thúc trò chơi nhỏ lì xì rơi từ trời trong phiên này, hệ thống sẽ tự động cào và đổi thưởng, và gửi email thông báo trúng thưởng đến hộp thư đúng giờ.'
	},
	[109001] = {
		id = 109001,
		fmt = '1. The event is a mini-game where you build a snowman. The snowman has levels, and as the level increases, it unlocks decorations and costumes for different parts of the snowman.',
		fmt_ma = '1. Aktiviti ini adalah permainan membuat orang salji, orang salji mempunyai tahap, tahap lebih tinggi membuka perhiasan dan kostum untuk bahagian orang salji',
		fmt_en = '1. The event is a mini-game where you build a snowman. The snowman has levels, and as the level increases, it unlocks decorations and costumes for different parts of the snowman.',
		fmt_in = '1. Event ini adalah mini game membuat manusia salju, manusia salju memiliki level, semakin tinggi level maka akan membuka dekorasi dan kostum untuk bagian tubuh manusia salju.',
		fmt_th = '1.กิจกรรมเป็นมินิเกมสร้างตุ๊กตาหิมะ ตุ๊กตาหิมะมีระดับ เมื่อเลเวลเพิ่มขึ้นจะปลดล็อกของตกแต่งและชุดใหม่',
		fmt_ph = '1. Ang event ay isang mini game ng paggawa ng snowman. May level ang snowman, at sa bawat pagtaas ng level, ma-unlock ang mga palamuti at costume ng snowman.',
		fmt_vn = '1.Hoạt động là một trò chơi nhỏ làm người tuyết, người tuyết có cấp độ, khi cấp độ tăng lên sẽ mở khóa các vật trang trí và trang phục cho các bộ phận của người tuyết.'
	},
	[109002] = {
		id = 109002,
		fmt = '2. Collect limited event snowflake props, which can be used to build Pikachu the snowman. Each time you consume 1 prop to build, you will receive a random reward, and Pikachu will level up.',
		fmt_ma = '2. Kumpul item kepingan salji acara, digunakan untuk membina orang salji Pikachu, setiap penggunaan 1 item akan mendapat ganjaran rawak dan meningkatkan tahap Pikachu',
		fmt_en = '2. Collect limited event snowflake props, which can be used to build Pikachu the snowman. Each time you consume 1 prop to build, you will receive a random reward, and Pikachu will level up.',
		fmt_in = '2. Kumpulkan item snowflake terbatas dari event, dapat digunakan untuk membangun manusia salju Pikachu, setiap kali menghabiskan 1 item untuk membangun, akan mendapatkan 1 hadiah acak, dan Pikachu akan naik level.',
		fmt_th = '2.เก็บสะสมไอเทมเกล็ดหิมะในอีเวนต์ ใช้สร้างตุ๊กตา Pikachu ครั้งละ 1 ชิ้น จะได้รับรางวัลแบบสุ่มและ Pikachu จะเลื่อนระดับ',
		fmt_ph = '2. Mangolekta ng limited event item na snowflake, gamitin ito para bumuo ng Pikachu snowman. Kada gamit ng 1 snowflake ay makakakuha ng random na gantimpala, at tataas ang level ni Pikachu.',
		fmt_vn = '2. Thu thập đạo cụ bông tuyết giới hạn sự kiện, có thể dùng để xây người tuyết Pikachu, mỗi lần tiêu hao 1 đạo cụ để xây dựng, sẽ nhận được 1 phần thưởng ngẫu nhiên, đồng thời Pikachu sẽ tăng cấp.'
	},
	[109003] = {
		id = 109003,
		fmt = '3. As Pikachu\'s level increases, some Christmas decorations on it will be unlocked. The unlocked parts can be customized with your favorite colors, and fixed environmental decorations with a Christmas atmosphere will also be unlocked.',
		fmt_ma = '3. Apabila tahap Pikachu meningkat, beberapa perhiasan Krismas akan dibuka, perhiasan boleh diubah warna mengikut suka, beberapa perhiasan persekitaran Krismas juga akan dibuka',
		fmt_en = '3. As Pikachu\'s level increases, some Christmas decorations on it will be unlocked. The unlocked parts can be customized with your favorite colors, and fixed environmental decorations with a Christmas atmosphere will also be unlocked.',
		fmt_in = '3. Saat level Pikachu naik, beberapa dekorasi Natal di tubuhnya akan terbuka. Bagian yang terbuka bisa diubah warna dekorasinya sesuai keinginan, dan juga membuka dekorasi lingkungan bertema Natal.',
		fmt_th = '3.เมื่อ Pikachu เลื่อนระดับ จะปลดล็อกของตกแต่งคริสต์มาส สามารถเปลี่ยนสีตกแต่งตามต้องการ และปลดล็อกของตกแต่งบรรยากาศ',
		fmt_ph = '3. Sa pagtaas ng level ni Pikachu, ilang Christmas decorations sa kanya ay maa-unlock. Ang mga unlocked na bahagi ay maaaring i-customize ang kulay, at may mga environment decorations na maa-unlock din.',
		fmt_vn = '3. Khi cấp độ của Pikachu tăng lên, một số vật trang trí Giáng sinh trên người nó sẽ được mở khóa. Các bộ phận được mở khóa có thể thay đổi tùy ý màu sắc trang trí yêu thích, đồng thời sẽ mở khóa cố định một số vật trang trí môi trường mang không khí Giáng sinh.'
	},
	[109004] = {
		id = 109004,
		fmt = '4. Pikachu\'s level has a cap. When it reaches the maximum level, all decorations and costumes will be fully unlocked and displayed. However, snowflake props can still be used to level up, and each use will grant a reward.',
		fmt_ma = '4. Tahap Pikachu ada had, apabila capai tahap maksimum, semua perhiasan akan dipaparkan dan dibuka sepenuhnya, masih boleh guna item untuk tingkatkan tahap dan menerima ganjaran',
		fmt_en = '4. Pikachu\'s level has a cap. When it reaches the maximum level, all decorations and costumes will be fully unlocked and displayed. However, snowflake props can still be used to level up, and each use will grant a reward.',
		fmt_in = '4. Level Pikachu memiliki batas, saat mencapai level maksimum, semua dekorasi dan kostum akan ditampilkan dan terbuka sepenuhnya. Namun, Anda tetap bisa menggunakan item snowflake untuk naik level dan tetap mendapatkan hadiah setiap kali digunakan.',
		fmt_th = '4.เลเวล Pikachu มีขีดจำกัด เมื่อถึงระดับสูงสุด จะปลดล็อกของตกแต่งและชุดทั้งหมด แต่ยังสามารถใช้เกล็ดหิมะเพิ่มระดับเพื่อรับรางวัล',
		fmt_ph = '4. May limit ang level ni Pikachu, at sa max level, lahat ng decorations at costume ay buong-buong maa-unlock. Maaari pa ring gumamit ng snowflake item para pataasin ang level at makatanggap ng gantimpala.',
		fmt_vn = '4. Cấp độ của Pikachu có giới hạn, khi đạt đến cấp độ tối đa, tất cả vật phẩm trang trí và trang phục sẽ được hiển thị và mở khóa hoàn toàn. Tuy nhiên, vẫn có thể sử dụng đạo cụ bông tuyết để tăng cấp, mỗi lần sử dụng đều nhận được phần thưởng.'
	},
	[110001] = {
		id = 110001,
		fmt = '1. The game provides 3 heroes with different health, movement speed, and sizes to choose from. Players can freely select the hero they are skilled with before each game.',
		fmt_ma = '1. Permainan menyediakan 3 hero dengan HP, kelajuan pergerakan dan saiz berbeza, pemain boleh pilih hero yang dikuasai sebelum mula bermain',
