	[110005] = {
		id = 110005,
		fmt = '5. The mini-game has a leaderboard, where your highest score in a game will be displayed.',
		fmt_ma = '5. Permainan mini ada papan ranking, skor tertinggi anda akan dipaparkan',
		fmt_en = '5. The mini-game has a leaderboard, where your highest score in a game will be displayed.',
