	[112007] = {
		id = 112007,
		fmt = '1. There are a total of 15 questions in the general Q&A, and if you answer incorrectly or fail to answer, you score 0 points. Correct answers will earn points, and the faster and more accurately you answer, the higher your score will be.',
		fmt_ma = '1. Terdapat 15 soalan dalam kuis, jawapan salah atau tidak menjawab mendapat 0 mata; jawapan betul akan menerima mata, lebih cepat dan tepat menjawab, lebih tinggi mata',
		fmt_en = '1. There are a total of 15 questions in the general Q&A, and if you answer incorrectly or fail to answer, you score 0 points. Correct answers will earn points, and the faster and more accurately you answer, the higher your score will be.',
		fmt_in = '1. Total ada 15 pertanyaan di kuis umum, jawaban salah atau tidak dijawab 0 poin; jawaban benar akan mendapatkan poin sesuai, semakin cepat dan tepat menjawab, semakin tinggi poin yang didapat.',
		fmt_th = '1.มี 15 คำถามในรอบทั่วไป ตอบผิดหรือไม่ตอบ 0 คะแนน ตอบถูกได้คะแนนตามเวลา ยิ่งเร็ว ยิ่งได้คะแนนสูง',
		fmt_ph = '1. Kabuuang 15 tanong sa quiz, maling sagot o walang sagot ay 0 points; tamang sagot ay may puntos depende sa bilis at accuracy — mas mabilis at tama, mas mataas ang puntos.',
		fmt_vn = '1.Tổng cộng có 15 câu hỏi trong phần hỏi đáp tổng quan, trả lời sai hoặc không trả lời được 0 điểm; trả lời đúng sẽ nhận được số điểm tương ứng, thời gian trả lời càng ngắn và chính xác thì số điểm nhận được càng cao.'
	},
