	[113001] = {
		id = 113001,
		fmt = '1. The Cross-Server Trial Tower requires waiting for a match to be created between servers. Once the match is successful, the status "#C0xF76B45#Matchmaking successful, waiting for battle#C0xFFFFFF#" will be displayed on the interface.',
		fmt_ma = '1. Menara Percubaan Cross-server memerlukan masa matching server, selepas berjaya akan tertera status #C0xF76B45#Berjaya matching, tunggu pertempuran#C0xFFFFFF# dalam antaramuka',
		fmt_en = '1. The Cross-Server Trial Tower requires waiting for a match to be created between servers. Once the match is successful, the status "#C0xF76B45#Matchmaking successful, waiting for battle#C0xFFFFFF#" will be displayed on the interface.',
		fmt_in = '1. Menara Uji Lintas Server memerlukan waktu untuk pencocokan antar server, setelah berhasil dicocokkan, akan menampilkan status #C0xF76B45#Pencocokan berhasil, menunggu pertempuran#C0xFFFFFF# di antarmuka',
		fmt_th = '1.หอคอยข้ามเซิร์ฟเวอร์รอจับคู่ เมื่อจับคู่สำเร็จจะแสดงสถานะ #C0xF76B45#จับคู่สำเร็จ รอเปิดศึก#C0xFFFFFF#',
		fmt_ph = '1. Kailangang hintayin ang matchmaking sa Cross-server Trial Tower, kapag matagumpay ang matchmaking, lalabas ang status na #C0xF76B45#Matagumpay ang matchmaking, naghihintay ng labanan#C0xFFFFFF# sa interface.',
		fmt_vn = '1. Tháp Thí Luyện Liên Server cần chờ đợi ghép trận giữa các máy chủ, khi ghép trận thành công, sẽ hiển thị trạng thái #C0xF76B45#Ghép trận thành công, chờ khai chiến#C0xFFFFFF# trên giao diện.'
	},
	[113002] = {
		id = 113002,
		fmt = '2. Seasonal process: #C0xF76B45# Pre-season announcement (1 day) - Season starts (10:00 every other day, lasting 3 days) - Displaying season results (from 22:00 of the end date until before the start of the next season).',
		fmt_ma = '2. Proses musim: #C0xF76B45#Notis pra-musim (1 hari) - Musim bermula (10:00 dua hari sekali, berlangsung 3 hari) - Paparan keputusan musim (dari 22:00 hari akhir sehingga sebelum musim berikut)',
		fmt_en = '2. Seasonal process: #C0xF76B45# Pre-season announcement (1 day) - Season starts (10:00 every other day, lasting 3 days) - Displaying season results (from 22:00 of the end date until before the start of the next season).',
		fmt_in = '2. Proses musim: #C0xF76B45# Pemberitahuan pra-musim (berlangsung 1 hari) - Musim dimulai (10:00 setiap dua hari, berlangsung 3 hari) - Menampilkan hasil musim (dari 22:00 hari terakhir hingga sebelum musim berikutnya dimulai)',
		fmt_th = '2.ฤดูกาล: #C0xF76B45# ประกาศล่วงหน้า (1 วัน) - เริ่มฤดูกาล (10:00 สองวันครั้ง, 3 วัน) - แสดงผล (22:00 วันสุดท้าย ถึงวันเริ่มถัดไป)  ',
		fmt_ph = '2. Season process: #C0xF76B45# Pre-season notice (1 araw) - Season start (10:00 tuwing dalawang araw, 3 araw na duration) - Result display (mula 22:00 sa huling araw hanggang bago magsimula ang susunod na season)',
		fmt_vn = '2. Quy trình mùa giải: #C0xF76B45# Thông báo trước mùa giải (kéo dài 1 ngày) - Mùa giải bắt đầu (10:00 hai ngày một lần, kéo dài 3 ngày) - Hiển thị kết quả mùa giải (từ 22:00 ngày kết thúc đến trước ngày bắt đầu mùa giải tiếp theo)'
	},
	[113003] = {
		id = 113003,
		fmt = '3. At 22:00 each day during the season and at 22:00 on the last day of the season, individual rewards will be given based on rankings. At 22:00 on the last day of the season, server rewards will also be calculated. All rewards will be sent via mail.',
		fmt_ma = '3. Pada 22:00 setiap hari musim dan 22:00 hari akhir musim, hadiah individu diberikan berdasarkan ranking, hadiah server turut dikira pada 22:00 hari akhir, semua hadiah dihantar melalui surat',
		fmt_en = '3. At 22:00 each day during the season and at 22:00 on the last day of the season, individual rewards will be given based on rankings. At 22:00 on the last day of the season, server rewards will also be calculated. All rewards will be sent via mail.',
		fmt_in = '3. Pada pukul 22:00 setiap hari selama musim dan pukul 22:00 di hari terakhir musim, hadiah individu akan dibagikan berdasarkan peringkat, pada pukul 22:00 hari terakhir musim juga akan menghitung hadiah server, semua hadiah dikirim melalui surat',
		fmt_th = '3.เวลา 22:00 ทุกวันและวันสุดท้ายจะมอบรางวัลอันดับ รางวัลเซิร์ฟเวอร์จะคิดตอน 22:00 ของวันจบฤดูกาล ส่งทางจดหมาย',
		fmt_ph = '3. Tuwing 22:00 kada araw sa season at sa 22:00 ng huling araw ng season, ipapamahagi ang personal rewards batay sa ranking, at sa 22:00 ng pagtatapos ng season, bibilangin ang server rewards, lahat ng rewards ay ipapadala sa mail.',
		fmt_vn = '3. Vào lúc 22:00 mỗi ngày trong mùa giải và lúc 22:00 ngày kết thúc mùa giải sẽ phát thưởng cá nhân dựa trên thứ hạng, lúc 22:00 ngày kết thúc mùa giải cũng sẽ tính toán thưởng server, tất cả phần thưởng đều được nhận qua thư.'
	},
	[113004] = {
		id = 113004,
		fmt = '4. During the season, the #C0xF76B45#duel challenge can only be performed from 10:00 to 22:00 daily. The rest of the time is a ceasefire period where fighting actions like dueling or revenge are not allowed.',
		fmt_ma = '4. Dalam musim, cabaran #C0xF76B45# hanya boleh dilakukan dari 10:00 hingga 22:00 setiap hari, masa lain adalah masa damai, tidak boleh cabar atau balas dendam',
		fmt_en = '4. During the season, the #C0xF76B45#duel challenge can only be performed from 10:00 to 22:00 daily. The rest of the time is a ceasefire period where fighting actions like dueling or revenge are not allowed.',
		fmt_in = '4. Selama musim, tindakan tantangan #C0xF76B45# hanya dapat dilakukan dari pukul 10:00 hingga 22:00 setiap hari, waktu lainnya adalah waktu gencatan senjata, tidak dapat melakukan pertempuran seperti tantangan atau balas dendam',
		fmt_th = '4.ในฤดูกาล จะท้าทายได้เวลา 10:00-22:00 นอกเวลานี้สงบศึก ท้าทายไม่ได้',
		fmt_ph = '4. Sa loob ng season, ang mga challenge actions #C0xF76B45# ay maaari lamang gawin mula 10:00 hanggang 22:00 bawat araw, ang natitirang oras ay ceasefire period kung saan hindi maaaring mag-challenge o mag-revenge.',
		fmt_vn = '4. Trong mùa giải, hành vi thách đấu #C0xF76B45# chỉ có thể được thực hiện từ 10:00 đến 22:00 hàng ngày, thời gian còn lại là thời gian ngừng bắn, không thể thực hiện hành vi chiến đấu như thách đấu, trả thù.'
	},
	[113005] = {
		id = 113005,
		fmt = '5. Players have a number of free challenge attempts, opponent refresh attempts, and revenge attempts. If they exceed the limit, diamonds or gold can be used to buy more attempts.',
		fmt_ma = '5. Pemain mempunyai cabaran percuma, refresh lawan dan peluang balas dendam; jika melebihi, boleh beli guna berlian atau emas',
		fmt_en = '5. Players have a number of free challenge attempts, opponent refresh attempts, and revenge attempts. If they exceed the limit, diamonds or gold can be used to buy more attempts.',
		fmt_in = '5. Pemain memiliki jumlah percobaan tantangan gratis, jumlah refresh lawan tantangan, dan jumlah balas dendam; jika melebihi jumlah yang ditentukan, dapat membeli tambahan dengan berlian atau emas',
		fmt_th = '5.มีจำนวนท้าทายฟรี จำนวนรีเฟรชศัตรู และจำนวนล้างแค้น ใช้เพชรหรือทองซื้อเพิ่มได้ถ้าเกิน',
		fmt_ph = '5. May libreng bilang ng mga challenge attempts, refresh opponent attempts, at revenge attempts. Kung lampas dito, maaaring bumili gamit ang diamante o gold.',
		fmt_vn = '5. Người chơi có số lượt khiêu chiến miễn phí, số lượt làm mới đối thủ khiêu chiến và số lượt trả thù. Nếu vượt quá số lượt, có thể dùng kim cương hoặc vàng để mua thêm.'
	},
