	[113020] = {
		id = 113020,
		fmt = '1. Rankings correspond to the speed of producing Trial Coins and reward points. After occupying this rank, #C0xF76B45#Trial Coins will be produced at the current rate, and the reward points for that rank will be received. After changing ranks, the production speed and reward points will be directly replaced, without accumulation.',
		fmt_ma = '1. Ranking menentukan kadar penghasilan Syiling Percubaan dan mata, selepas memegang ranking itu, #C0xF76B45#Syiling Percubaan dihasilkan ikut kadar semasa dan terima mata ranking, ranking baharu terus ganti kadar lama, tidak dikumpul',
		fmt_en = '1. Rankings correspond to the speed of producing Trial Coins and reward points. After occupying this rank, #C0xF76B45#Trial Coins will be produced at the current rate, and the reward points for that rank will be received. After changing ranks, the production speed and reward points will be directly replaced, without accumulation.',
		fmt_in = '1. Peringkat menentukan kecepatan produksi Koin Uji dan poin hadiah, setelah menduduki peringkat tersebut, #C0xF76B45#Koin Uji akan diproduksi sesuai kecepatan saat ini, dan menerima poin hadiah peringkat tersebut; setelah peringkat berubah, kecepatan produksi dan hadiah akan langsung diganti, tidak terakumulasi',
		fmt_th = '1.อันดับสัมพันธ์กับอัตราผลิตเหรียญทดสอบและคะแนน รักษาอันดับจะได้เหรียญและแต้มตามนั้น ถ้าเปลี่ยนอันดับจะเปลี่ยนทันที ไม่สะสม',
		fmt_ph = '1. Ang ranking ay tumutukoy sa production speed ng Trial Coins at ranking points, kapag nakuha ang ranking na ito, #C0xF76B45#ang Trial Coins ay ipo-produce ayon sa kasalukuyang speed at makakakuha ng ranking points. Kapag nabago ang ranking, ang production speed at points ay papalitan, hindi ipag-iipon.',
		fmt_vn = '1. Thứ hạng tương ứng với tốc độ sản xuất Xu Thử Luyện và điểm thưởng, sau khi chiếm giữ thứ hạng này, #C0xF76B45#Xu Thử Luyện sẽ được sản xuất theo tốc độ hiện tại, đồng thời nhận được điểm thưởng của thứ hạng đó. Sau khi đổi thứ hạng, tốc độ sản xuất và điểm thưởng sẽ được thay thế trực tiếp, không cộng dồn.'
	},
	[113021] = {
		id = 113021,
		fmt = '2. Trial Coins are produced continuously throughout the day based on rankings, even during the ceasefire period. Challenging other players can yield a portion of their Trial Coins. #C0xF76B45#These can be used to buy items in the shop and upgrade attributes in the Blessing system.',
		fmt_ma = '2. Syiling Percubaan dihasilkan sepanjang hari mengikut ranking, cabar pemain lain boleh dapat sebahagian syiling mereka, #C0xF76B45#digunakan beli item di kedai dan tingkatkan atribut di berkat',
		fmt_en = '2. Trial Coins are produced continuously throughout the day based on rankings, even during the ceasefire period. Challenging other players can yield a portion of their Trial Coins. #C0xF76B45#These can be used to buy items in the shop and upgrade attributes in the Blessing system.',
		fmt_in = '2. Koin Uji diproduksi sepanjang hari berdasarkan peringkat, bahkan saat gencatan senjata; menantang pemain lain bisa mendapatkan sebagian koin mereka, #C0xF76B45#dapat digunakan untuk membeli item di toko dan meningkatkan atribut di berkat',
		fmt_th = '2.เหรียญทดสอบผลิตต่อเนื่องตลอดวัน แม้ช่วงสงบศึก ท้าทายผู้เล่นอื่นแย่งเหรียญได้ #C0xF76B45#ใช้ซื้อของในร้านและเพิ่มสเตตัสพรได้',
		fmt_ph = '2. Ang Trial Coins ay tuloy-tuloy na nae-earn buong araw batay sa ranking, kahit nasa ceasefire period. Maaaring makakuha ng bahagi ng Trial Coins ng kalaban sa pag-challenge. #C0xF76B45#Maaaring gamitin sa shop o para sa attribute training sa Blessing.',
		fmt_vn = '2. Xu thử luyện được sản xuất liên tục cả ngày dựa trên thứ hạng, kể cả trong thời gian không đình chiến. Khiêu chiến người chơi khác có thể nhận được một phần xu thử luyện của họ. #C0xF76B45#Có thể dùng để mua vật phẩm trong cửa hàng và bồi dưỡng thuộc tính trong chúc phúc.'
	},
	[113022] = {
		id = 113022,
		fmt = '3. Accumulation points are based on rank changes and rewards from fighting and defeating Bosses in time-limited battles. #C0xF76B45#Accumulation points are used to rank the top 100 players by total accumulation points at the end of the season, #C0xFFFFFF# based on the order of points.',
		fmt_ma = '3. Mata terkumpul hasil perubahan ranking dan hadiah dari pertempuran serta mengalahkan BOSS, #C0xF76B45# digunakan untuk ranking 100 pemain tertinggi setiap server di akhir musim #C0xFFFFFF# ikut turutan ranking',
		fmt_en = '3. Accumulation points are based on rank changes and rewards from fighting and defeating Bosses in time-limited battles. #C0xF76B45#Accumulation points are used to rank the top 100 players by total accumulation points at the end of the season, #C0xFFFFFF# based on the order of points.',
		fmt_in = '3. Poin akumulasi berdasarkan perubahan peringkat serta hadiah dari pertempuran dan mengalahkan Boss dalam pertarungan waktu terbatas, #C0xF76B45#poin akumulasi digunakan untuk peringkat total 100 pemain teratas di setiap server pada akhir musim#C0xFFFFFF#, berdasarkan peringkat',
		fmt_th = '3.คะแนนสะสมจะขึ้นอยู่กับการเปลี่ยนแปลงอันดับและรางวัลจากการต่อสู้และการกำจัดบอสในการต่อสู้แบบจำกัดเวลา #C0xF76B45#คะแนนสะสมจะถูกใช้ในการจัดอันดับคะแนนสะสมรวมของผู้เล่น 100 อันดับแรกของแต่ละเซิร์ฟเวอร์เมื่อสิ้นสุดฤดูกาล#C0xFFFFFF#เรียงตามลำดับจากมากไปน้อย',
		fmt_ph = '3. Ang accumulated points ay galing sa pagbabago ng ranking, battle rewards at pagpatay ng Boss sa time-limited battles, #C0xF76B45#ang points ay gagamitin sa top 100 accumulated ranking ng bawat server sa pagtatapos ng season#C0xFFFFFF# ayon sa mataas-pababang order.',
		fmt_vn = '3. Điểm tích lũy dựa trên sự thay đổi thứ hạng và phần thưởng từ việc chiến đấu và tiêu diệt Boss trong các trận chiến giới hạn thời gian, #C0xF76B45# điểm tích lũy được sử dụng để xếp hạng tổng điểm tích lũy của 100 người chơi đứng đầu mỗi máy chủ khi kết thúc mùa giải, #C0xFFFFFF# dựa trên thứ tự cao thấp.'
	},
	[113040] = {
		id = 113040,
		fmt = '1. Before fighting, players can #C0xF76B45# arrange 3 formations, each with a maximum of 4 heroes.',
		fmt_ma = '1. Sebelum pertempuran, pemain boleh #C0xF76B45#susun 3 formasi, setiap formasi maksimum 4 pahlawan',
		fmt_en = '1. Before fighting, players can #C0xF76B45# arrange 3 formations, each with a maximum of 4 heroes.',
		fmt_in = '1. Sebelum bertempur, pemain dapat #C0xF76B45# mengatur 3 formasi, masing-masing formasi maksimal 4 hero',
		fmt_th = '1.ก่อนการต่อสู้ผู้เล่นสามารถ #C0xF76B45#จัดทีมได้ 3 ทีม โดยแต่ละทีมสูงสุด 4 ฮีโร่',
		fmt_ph = '1. Bago ang laban, maaaring #C0xF76B45# mag-set up ng 3 formations, maximum 4 na bayani kada formation.',
		fmt_vn = '1.Trước khi chiến đấu, người chơi có thể #C0xF76B45# sắp xếp 3 đội hình, mỗi đội hình tối đa 4 anh hùng.'
	},
	[113041] = {
		id = 113041,
		fmt = '2. The battle system follows a competitive format between teams, scoring by rounds, #C0xF76B45# winning 2 out of 3 rounds means winning the match, with a maximum of 3 rounds, and the results of previous rounds do not affect the following rounds.',
		fmt_ma = '2. Sistem pertandingan berformat lawan pasukan, kira markah ikut perlawanan, #C0xF76B45#menang 2 dari 3 pusingan dikira menang keseluruhan, maksimum 3 pusingan, keputusan pusingan terdahulu tidak jejaskan pusingan berikut',
		fmt_en = '2. The battle system follows a competitive format between teams, scoring by rounds, #C0xF76B45# winning 2 out of 3 rounds means winning the match, with a maximum of 3 rounds, and the results of previous rounds do not affect the following rounds.',
		fmt_in = '2. Pertarungan dengan sistem duel antar tim, penilaian berdasarkan pertandingan, #C0xF76B45# menang 2 dari 3 pertandingan akan menang total, maksimal 3 ronde, hasil ronde sebelumnya tidak mempengaruhi ronde berikutnya',
		fmt_th = '2.ระบบการแข่งขันจะเป็นแบบทีมต่อทีม คิดคะแนนตามรอบ #C0xF76B45#ชนะ 2 ใน 3 รอบถือว่าชนะทั้งหมด สูงสุด 3 รอบ แต่ละรอบไม่ส่งผลต่อรอบถัดไป',
		fmt_ph = '2. Ang sistema ay best-of-three battle format, #C0xF76B45# 2 panalo sa 3 rounds ang mananalo sa match, hanggang maximum 3 rounds, at ang resulta ng bawat round ay hindi makaapekto sa susunod.',
		fmt_vn = '2. Hệ thống thi đấu theo hình thức đối kháng giữa các đội, tính điểm theo trận đấu, #C0xF76B45# thắng 2 trong 3 trận là thắng chung cuộc, tối đa 3 vòng đấu, kết quả của vòng đấu trước không ảnh hưởng đến vòng đấu sau.'
