	[114004] = {
		id = 114004,
		fmt = '4. Every time a player completes a challenge, they will reduce the BOSS’s health accordingly and receive a random reward. The player who kills the BOSS last will receive an additional kill reward. After the BOSS is defeated, ranking rewards will be given based on the damage dealt.',
		fmt_ma = '4. Setiap cabaran akan mengurangkan HP BOSS dan beri ganjaran rawak, pemain yang mengalahkan BOSS terakhir akan dapat ganjaran tambahan, selepas BOSS ditewaskan, hadiah ranking akan diberi ikut jumlah damage',
		fmt_en = '4. Every time a player completes a challenge, they will reduce the BOSS’s health accordingly and receive a random reward. The player who kills the BOSS last will receive an additional kill reward. After the BOSS is defeated, ranking rewards will be given based on the damage dealt.',
		fmt_in = '4. Setiap kali tantangan selesai, HP BOSS akan berkurang, pemain akan menerima hadiah acak, pemain yang mengalahkan BOSS terakhir akan menerima hadiah tambahan, setelah BOSS dikalahkan, hadiah peringkat akan diberikan berdasarkan jumlah damage yang diberikan',
		fmt_th = '4.เมื่อท้าทายสำเร็จ BOSS จะลดพลังชีวิตตามจำนวนที่กำหนดและได้รับรางวัลแบบสุ่ม ผู้ที่โค่น BOSS คนสุดท้ายจะได้รับรางวัลพิเศษ และจะมีการแจกของรางวัลตามอันดับความเสียหาย',
		fmt_ph = '4. Bawat matagumpay na challenge ay magbabawas ng HP ng BOSS at magbibigay ng random rewards, ang huling nakapatay ng BOSS ay makakakuha ng additional kill reward, at pagkatapos ng pagpatay ng BOSS, iraranggo ang mga rewards batay sa total damage.',
		fmt_vn = '4. Mỗi khi người chơi hoàn thành thử thách sẽ trừ lượng máu tương ứng của BOSS đồng thời nhận được phần thưởng ngẫu nhiên, người hạ gục BOSS cuối cùng sẽ nhận được phần thưởng hạ gục thêm, sau khi BOSS bị tiêu diệt sẽ phát phần thưởng xếp hạng dựa trên lượng sát thương gây ra.'
	},
	[114005] = {
		id = 114005,
		fmt = 'The server of the player who defeats the BOSS will receive an additional buff, one of three effects: attribute enhancement, increased production, and enhanced looting ability.',
