	},
	[117003] = {
		id = 117003,
		fmt = '3. The premium version of the Pass Card is only valid for the current event period, and needs to be purchased again for the next event period. The accumulated activity points will also be reset when the event ends.',
		fmt_ma = '3. Pas Premium yang dibeli hanya sah untuk musim itu sahaja, perlu dibeli semula untuk musim berikutnya; mata terkumpul juga akan direset selepas acara tamat.',
		fmt_en = '3. The premium version of the Pass Card is only valid for the current event period, and needs to be purchased again for the next event period. The accumulated activity points will also be reset when the event ends.',
		fmt_in = '3. Pass Premium hanya berlaku untuk periode acara tersebut, pada periode berikutnya harus dibeli kembali; poin aktivitas juga akan direset setelah acara selesai',
		fmt_th = '3.Battle Pass แบบพรีเมียมจะมีผลเฉพาะในรอบกิจกรรม ต้องซื้อใหม่ทุกครั้งเมื่อเริ่มรอบใหม่ คะแนนสะสมจะถูกรีเซ็ตเมื่อจบกิจกรรม',
