		fmt = '4. When the Pass Card event ends, all unclaimed rewards will be sent via email.',
		fmt_ma = '4. Apabila acara Pas tamat, semua ganjaran yang belum diterima akan dihantar melalui emel.',
		fmt_en = '4. When the Pass Card event ends, all unclaimed rewards will be sent via email.',
