	[118001] = {
		id = 118001,
		fmt = '1. Each day, by surpassing the Space Tower and accumulating the number of floors completed (only counted when the final Boss challenge of each floor is completed), you can unlock attractive rewards from the pass card.',
		fmt_ma = '1. Setiap hari melepasi Menara Angkasa, bilangan tingkat yang berjaya dilepasi (hanya kira selepas cabaran BOSS setiap tingkat selesai), boleh membuka ganjaran menarik dalam Pas.',
		fmt_en = '1. Each day, by surpassing the Space Tower and accumulating the number of floors completed (only counted when the final Boss challenge of each floor is completed), you can unlock attractive rewards from the pass card.',
		fmt_in = '1. Setiap hari menyelesaikan lantai di Menara Dimensi, akumulasi jumlah lantai yang dilewati (hanya dihitung saat menyelesaikan tantangan BOSS di akhir lantai), dapat membuka hadiah menarik dari Kartu Pass',
		fmt_th = '1. เคลียร์หอคอยมิติแต่ละวัน สะสมจำนวนชั้นที่ผ่าน (นับเฉพาะเมื่อเคลียร์ BOSS ของแต่ละชั้นสำเร็จ) จะสามารถปลดล็อครางวัลพาสสุดคุ้มได้',
		fmt_ph = '1. Araw-araw na pag-akyat sa Space Tower, iipunin ang bilang ng mga nalampasang palapag (binibilang lang kapag natapos ang BOSS challenge sa bawat palapag), upang ma-unlock ang mga kahanga-hangang gantimpala ng battle pass.  ',
		fmt_vn = '1. Mỗi ngày vượt Tháp Không Gian, tích lũy số tầng đã qua (chỉ tính khi hoàn thành thử thách BOSS cuối mỗi tầng), có thể mở khóa phần thưởng hấp dẫn của vé thông hành.'
	},
