	[119001] = {
		id = 119001,
		fmt = '#C0xFFFFFFFF#1. Success in challenging faction dungeons each week will accumulate the number of challenges (#C0xF76B45#Players challenging their own faction will not count#C0xFFFFFFFF#); The more accumulated challenges, the richer the rewards unlocked by the pass card.',
		fmt_ma = '#C0xFFFFFFFF#1. Berjaya mencabar penjara kuasa mingguan akan mengumpulkan bilangan cabaran (#C0xF76B45#Pemain cabar kuasa tidak dikira#C0xFFFFFFFF#); semakin banyak cabaran terkumpul, semakin banyak ganjaran pas yang boleh dibuka.',
		fmt_en = '#C0xFFFFFFFF#1. Success in challenging faction dungeons each week will accumulate the number of challenges (#C0xF76B45#Players challenging their own faction will not count#C0xFFFFFFFF#); The more accumulated challenges, the richer the rewards unlocked by the pass card.',
		fmt_in = '#C0xFFFFFFFF#1. Berhasil menyelesaikan tantangan Dungeon Kekuatan setiap minggu akan menambah jumlah tantangan (#C0xF76B45#Tantangan Kekuatan oleh pemain tidak dihitung#C0xFFFFFFFF#); semakin banyak jumlah tantangan yang terakumulasi, semakin banyak hadiah Kartu Pass yang terbuka',
		fmt_th = '#C0xFFFFFFFF#1. สำเร็จในการท้าทายดันเจี้ยนกองกำลังประจำสัปดาห์ จะสะสมจำนวนครั้งที่ท้าทาย (#C0xF76B45#ผู้เล่นที่ท้าทายกองกำลังจะไม่ถูกนับ#C0xFFFFFFFF#) ยิ่งสะสมมาก รางวัลที่ปลดล็อคจากพาสก็ยิ่งหลากหลาย',
		fmt_ph = '#C0xFFFFFFFF#1. Tagumpay sa lingguhang faction dungeon challenge ay magdaragdag sa bilang ng mga challenge attempts (#C0xF76B45#Hindi kasama ang mga faction challenges ng manlalaro#C0xFFFFFFFF#); mas maraming challenge attempts, mas maraming gantimpala ang ma-unlock sa battle pass.  ',
		fmt_vn = '#C0xFFFFFFFF#1. Thành công khi thách đấu phụ bản thế lực mỗi tuần sẽ cộng dồn số lần thách đấu (#C0xF76B45#Người chơi thách đấu thế lực không được tính#C0xFFFFFFFF#); Số lần thách đấu cộng dồn càng nhiều, phần thưởng thẻ thông hành mở khóa càng phong phú.'
	},
