	[120001] = {
		id = 120001,
		fmt = '1. Roll the dice to move, on the map there are treasure chests, #C0xF76B45# which have rich rewards and will randomly reappear on the map once obtained. Make hunting treasure chests your goal!',
		fmt_ma = '1. Lempar dadu untuk bergerak, di atas peta terdapat peti harta karun, #C0xF76B45# yang mengandungi ganjaran menarik dan selepas diperoleh akan muncul semula secara rawak di peta. Jadikan memburu peti harta sebagai matlamat anda!',
		fmt_en = '1. Roll the dice to move, on the map there are treasure chests, #C0xF76B45# which have rich rewards and will randomly reappear on the map once obtained. Make hunting treasure chests your goal!',
		fmt_in = '1. Lempar dadu untuk bergerak, di peta terdapat peti harta, #C0xF76B45#yang memiliki hadiah melimpah dan setelah diambil akan muncul kembali secara acak di peta. Jadikan berburu peti harta sebagai tujuanmu!',
		fmt_th = '1. ทอยลูกเต๋าเพื่อเดินบนแผนที่ บนแผนที่จะมีหีบสมบัติ #C0xF76B45#ซึ่งมีของรางวัลมากมายและจะสุ่มเกิดใหม่หลังได้รับ ใช้การล่าหีบเป็นเป้าหมายของคุณ!',
		fmt_ph = '1. Mag-roll ng dice para lumipat, sa mapa ay may mga treasure chest, #C0xF76B45# mayaman ang mga gantimpala at pagkatapos makuha ay magpapakita muli nang random sa mapa. Gawin ang paghahanap ng mga treasure chest bilang iyong layunin!  ',
		fmt_vn = '1. Tung xúc xắc để di chuyển, trên bản đồ có các rương báu, #C0xF76B45#chúng có phần thưởng phong phú và sau khi nhận được sẽ ngẫu nhiên xuất hiện lại trên bản đồ. Hãy lấy việc săn đuổi các rương báu làm mục tiêu của bạn!'
	},
	[120002] = {
		id = 120002,
		fmt = '2. When moving on the map, you will also encounter other event spaces. Click on an event space on the map #C0xF76B45# to see detailed information.',
		fmt_ma = '2. Semasa bergerak di peta, anda juga akan menemui petak acara lain. Klik pada petak acara di peta #C0xF76B45# untuk melihat maklumat lanjut.',
		fmt_en = '2. When moving on the map, you will also encounter other event spaces. Click on an event space on the map #C0xF76B45# to see detailed information.',
		fmt_in = '2. Saat bergerak di peta, kamu juga akan menemui kotak event lainnya. Klik pada kotak event di antarmuka peta #C0xF76B45# untuk melihat detail informasinya',
		fmt_th = '2. ระหว่างเดินบนแผนที่ จะเจอกับช่องอีเวนต์ต่าง ๆ คลิกช่องอีเวนต์บนแผนที่ #C0xF76B45#เพื่อดูรายละเอียด',
		fmt_ph = '2. Sa paggalaw sa mapa, makakatagpo ka rin ng iba pang mga event tiles. I-click ang event tile sa mapa #C0xF76B45# para makita ang mga detalye.  ',
		fmt_vn = '2. Khi di chuyển trên bản đồ, bạn cũng sẽ gặp các ô sự kiện khác. Nhấp vào ô sự kiện trên giao diện bản đồ #C0xF76B45# để xem thông tin chi tiết.'
	},
	[120003] = {
		id = 120003,
		fmt = '3. In event spaces, the small shop and treasure chests will trigger the event as long as you pass through. Once the event ends, if Satoshi can still move, they will continue to move forward; other event spaces require stopping to trigger them.',
		fmt_ma = '3. Dalam petak acara, kedai kecil dan peti harta akan diaktifkan hanya dengan melaluinya, acara selesai, jika Satoshi masih boleh bergerak, akan terus maju ke depan; petak acara lain perlu berhenti di situ untuk diaktifkan.',
		fmt_en = '3. In event spaces, the small shop and treasure chests will trigger the event as long as you pass through. Once the event ends, if Satoshi can still move, they will continue to move forward; other event spaces require stopping to trigger them.',
		fmt_in = '3. Dalam kotak event, toko kecil dan peti harta akan mengaktifkan event hanya dengan melewati, setelah event selesai, jika Satoshi masih bisa bergerak, maka akan terus bergerak ke depan; kotak event lainnya memerlukan berhenti untuk mengaktifkannya',
		fmt_th = '3. ในช่องอีเวนต์ ร้านค้าขนาดเล็กและหีบสมบัติจะทำงานทันทีเมื่อเดินผ่าน อีเวนต์อื่น ๆ ต้องหยุดเพื่อเปิดใช้งาน ถ้ายังเดินได้ จะเดินต่อไป',
		fmt_ph = '3. Sa event tile, ang mga small shop at treasure chest ay nagti-trigger ng event kapag tinawid lang, matatapos ang event, at kung ang Satoshi ay maaari pang gumalaw, magpapatuloy siya; ang ibang event tiles ay kailangang huminto muna bago ma-trigger.  ',
		fmt_vn = '3. Trong ô sự kiện, cửa hàng nhỏ và rương báu sẽ kích hoạt sự kiện chỉ cần đi qua, sự kiện kết thúc, nếu Satoshi vẫn có thể di chuyển, thì sẽ tiếp tục di chuyển về phía trước; các ô sự kiện khác cần phải dừng lại mới kích hoạt được.'
	},
	[120004] = {
		id = 120004,
		fmt = '4. In the Grand Adventure, you can obtain Explorer Medals #C0xF76B45#, #C0xFFFFFF# which allow you to purchase items at the #C0xF76B45# shop along the way. Note, they can only be used to buy items that can be used in the Grand Adventure.',
		fmt_ma = '4. Dalam Pengembaraan Hebat, anda boleh memperoleh Pingat Pengembaraan #C0xF76B45#, #C0xFFFFFF# yang boleh digunakan untuk membeli item di #C0xF76B45# kedai di sepanjang jalan. Perhatian, hanya boleh digunakan untuk membeli item yang boleh digunakan dalam Pengembaraan Hebat.',
		fmt_en = '4. In the Grand Adventure, you can obtain Explorer Medals #C0xF76B45#, #C0xFFFFFF# which allow you to purchase items at the #C0xF76B45# shop along the way. Note, they can only be used to buy items that can be used in the Grand Adventure.',
		fmt_in = '4. Dalam Petualangan Besar, kamu bisa mendapatkan Medali Penjelajah #C0xF76B45#, #C0xFFFFFF#yang memungkinkan kamu membeli item di #C0xF76B45# toko sepanjang perjalanan. Perhatikan, hanya bisa digunakan untuk membeli item yang dapat digunakan dalam Petualangan Besar',
		fmt_th = '4. ในการผจญภัย จะได้รับเหรียญตราสำรวจ #C0xF76B45#ใช้ซื้อของใน #C0xF76B45#ร้านค้าระหว่างทาง ของเหล่านี้ใช้ได้เฉพาะในกิจกรรมการผจญภัยนี้เท่านั้น',
		fmt_ph = '4. Sa Grand Adventure, maaari kang makatanggap ng Exploration Medals #C0xF76B45#, #C0xFFFFFF# na nagpapahintulot sa iyo na bumili ng mga item sa #C0xF76B45# tindahan sa daan. Tandaan, maaari lamang itong gamitin para bumili ng mga item na magagamit sa Grand Adventure.  ',
		fmt_vn = '4. Trong Đại phiêu lưu, bạn có thể nhận được huy chương Thám hiểm #C0xF76B45#, #C0xFFFFFF#nó cho phép bạn mua vật phẩm tại #C0xF76B45# cửa hàng trên đường đi. Lưu ý, nó chỉ có thể được sử dụng để mua vật phẩm có thể sử dụng trong Đại phiêu lưu.'
	},
	[120005] = {
		id = 120005,
		fmt = '5. During the adventure, you will receive certain item cards and unique dice. If you don’t know how to use them, #C0xF76B45# please check the item description below.',
		fmt_ma = '5. Dalam pengembaraan, anda akan memperoleh beberapa kad item dan dadu khas. Jika tidak tahu cara menggunakannya, #C0xF76B45# sila lihat penerangan item di bawah.',
		fmt_en = '5. During the adventure, you will receive certain item cards and unique dice. If you don’t know how to use them, #C0xF76B45# please check the item description below.',
		fmt_in = '5. Dalam petualangan, kamu akan mendapatkan beberapa kartu item dan dadu khusus. Jika tidak tahu cara menggunakannya, #C0xF76B45# silakan lihat deskripsi item di bawah',
		fmt_th = '5. ระหว่างการผจญภัย จะได้รับการ์ดไอเทมและลูกเต๋าพิเศษ หากไม่แน่ใจวิธีใช้ #C0xF76B45#โปรดดูคำอธิบายไอเทมด้านล่าง',
		fmt_ph = '5. Sa paglalakbay, makakakuha ka ng ilang natatanging item cards at dice. Kung hindi mo alam paano gamitin, #C0xF76B45# tingnan ang paglalarawan ng item sa ibaba.  ',
		fmt_vn = '5. Trong cuộc phiêu lưu, bạn sẽ nhận được một số thẻ vật phẩm và xúc xắc độc đáo. Nếu không biết cách sử dụng chúng, #C0xF76B45# hãy xem phần mô tả vật phẩm bên dưới.'
	},
	[121001] = {
		id = 121001,
		fmt = '#L10##C0xF76B45#"It has always been the place where hands were held together that year, and this year\'s flowers are more beautiful than last year."#C0xFFFFFFFF# — Commanders from all over the world, along with their heroes, begin the annual Hero Tournament season.',
		fmt_ma = '#L10##C0xF76B45#"Masih di tempat bergandingan tangan tahun itu, bunga tahun ini lebih indah dari tahun lalu."#C0xFFFFFFFF# —— Pemimpin dari seluruh dunia bersama hero mereka memulakan Musim Kejuaraan Hero tahunan.',
		fmt_en = '#L10##C0xF76B45#"It has always been the place where hands were held together that year, and this year\'s flowers are more beautiful than last year."#C0xFFFFFFFF# — Commanders from all over the world, along with their heroes, begin the annual Hero Tournament season.',
		fmt_in = '#L10##C0xF76B45#"Selalu bersama seperti dulu, bunga tahun ini lebih indah dari tahun lalu."#C0xFFFFFFFF#——Para komandan dari seluruh dunia bersama para pahlawan mereka, memulai Musim Kompetisi Heroik tahunan',
		fmt_th = '#L10##C0xF76B45#"ยังคงเป็นสถานที่ที่จับมือกันเมื่อครั้งก่อน ดอกไม้ปีนี้งดงามยิ่งกว่าปีก่อน"#C0xFFFFFFFF#——เหล่าผู้นำจากทั่วโลกและเหล่าฮีโร่ เข้าสู่ฤดูกาลแข่งขันฮีโร่ประจำปี  ',
		fmt_ph = '#L10##C0xF76B45#"Palaging magkahawak-kamay noon, mas maganda ang mga bulaklak ngayon kaysa noon."#C0xFFFFFFFF#——Ang mga komandante mula sa buong mundo kasama ang kanilang mga bayani, sinimulan ang taunang Hero Battle season.  ',
		fmt_vn = '#L10##C0xF76B45#"Luôn là nơi tay trong tay năm ấy, hoa năm nay đẹp hơn năm ngoái."#C0xFFFFFFFF#——Các chỉ huy từ khắp nơi trên thế giới cùng với các anh hùng của họ, bắt đầu mùa giải Anh Hùng Tranh Bá hàng năm.'
	},
	[121002] = {
		id = 121002,
		fmt = 'The entire hero race season includes four phases: prize prediction, pre-competition preparation, during competition, and result announcement.',
		fmt_ma = 'Seluruh musim perlumbaan hero terdiri daripada empat fasa: Ramalan Berhadiah, Persiapan Sebelum Pertandingan, Semasa Pertandingan dan Pengumuman Keputusan.',
		fmt_en = 'The entire hero race season includes four phases: prize prediction, pre-competition preparation, during competition, and result announcement.',
		fmt_in = 'Seluruh musim kompetisi heroik terdiri dari empat tahap: Tebak Berhadiah, Persiapan sebelum pertandingan, Saat pertandingan berlangsung, dan Pengumuman hasil',
		fmt_th = 'ฤดูกาลแข่งขันฮีโร่มีทั้งหมด 4 ช่วง: ทายผลรับรางวัล เตรียมการแข่งขัน ขณะแข่งขัน และประกาศผล',
		fmt_ph = 'Ang buong hero racing season ay binubuo ng apat na yugto: prediction with prize, preparation bago ang laban, habang laban, at pag-aanunsyo ng resulta.  ',
		fmt_vn = 'Toàn bộ mùa giải đua anh hùng bao gồm bốn giai đoạn: dự đoán trúng thưởng, chuẩn bị trước khi thi đấu, trong khi thi đấu và công bố kết quả.'
	},
