	[121004] = {
		id = 121004,
		fmt = '1. During the event period, the Hero Tournament will have two rounds daily (12:00 and 20:00), and in each round, 4 heroes will be randomly selected to compete.',
		fmt_ma = '1. Sepanjang tempoh acara, akan ada dua pusingan pertandingan hero setiap hari (12:00 dan 20:00), setiap pusingan akan memilih secara rawak 4 hero untuk bertanding.',
		fmt_en = '1. During the event period, the Hero Tournament will have two rounds daily (12:00 and 20:00), and in each round, 4 heroes will be randomly selected to compete.',
		fmt_in = '1. Selama event berlangsung, kompetisi heroik akan diadakan dua kali sehari (12:00 dan 20:00), setiap putaran akan secara acak memilih 4 hero untuk bertanding',
		fmt_th = '1. ระหว่างกิจกรรม จะมีแข่งฮีโร่วันละ 2 รอบ (12:00 และ 20:00) โดยจะสุ่มเลือกฮีโร่ 4 ตัวมาแข่ง',
		fmt_ph = '1. Sa panahon ng event, ang hero racing season ay magkakaroon ng dalawang round bawat araw (12:00 at 20:00), sa bawat round ay pipili ng random na 4 bayani na lalaban.  ',
		fmt_vn = '1.Trong thời gian sự kiện diễn ra, mùa giải đua anh hùng sẽ có hai vòng thi mỗi ngày (12:00 và 20:00), mỗi vòng thi sẽ chọn ngẫu nhiên 4 anh hùng để thi đấu.'
	},
	[121005] = {
		id = 121005,
		fmt = '2. Although commanders cannot train with their heroes, they can participate in the prize prediction before the match starts; the result of the prediction will be announced after the match ends.',
		fmt_ma = '2. Walaupun pemimpin tidak dapat melatih bersama hero, mereka boleh menyertai ramalan berhadiah sebelum pertandingan bermula; keputusan ramalan akan diumumkan selepas pertandingan selesai.',
		fmt_en = '2. Although commanders cannot train with their heroes, they can participate in the prize prediction before the match starts; the result of the prediction will be announced after the match ends.',
		fmt_in = '2. Meskipun komandan tidak dapat melatih bersama hero, namun mereka dapat berpartisipasi dalam tebak berhadiah sebelum pertandingan dimulai; hasil tebakan akan diumumkan setelah pertandingan selesai',
		fmt_th = '2. แม้ผู้เล่นจะไม่ได้เข้าร่วมฝึกฮีโร่ แต่สามารถร่วมทายผลก่อนแข่งได้ ผลจะประกาศหลังแข่งจบ',
		fmt_ph = '2. Kahit na ang mga komandante ay hindi pwedeng magsanay kasama ang mga bayani, maaari silang sumali sa prediction with prize bago magsimula ang laban; ang resulta ng prediction ay iaanunsyo pagkatapos ng laban.  ',
		fmt_vn = '2. Tuy các chỉ huy không thể tham gia huấn luyện cùng với các anh hùng, nhưng họ có thể tham gia dự đoán có thưởng trước khi trận đấu bắt đầu; kết quả dự đoán sẽ được công bố khi trận đấu kết thúc.'
	},
	[121006] = {
		id = 121006,
		fmt = '3. The participation time for the fun quiz is: 05:00~11:57 and 13:00~19:57 daily; outside of these hours, you cannot participate in the quiz.',
		fmt_ma = '3. Masa untuk menyertai ramalan berhadiah adalah: 05:00~11:57 dan 13:00~19:57 setiap hari; di luar waktu ini, anda tidak boleh menyertai.',
		fmt_en = '3. The participation time for the fun quiz is: 05:00~11:57 and 13:00~19:57 daily; outside of these hours, you cannot participate in the quiz.',
		fmt_in = '3. Waktu untuk berpartisipasi dalam tebak berhadiah adalah: 05:00~11:57 dan 13:00~19:57 setiap hari; di luar jam ini tidak dapat ikut serta',
		fmt_th = '3. เวลาร่วมทายผล: 05:00~11:57 และ 13:00~19:57 นอกช่วงนี้จะไม่สามารถทายได้',
		fmt_ph = '3. Ang oras ng pagsali sa prediction quiz ay: 05:00~11:57 at 13:00~19:57 araw-araw; sa labas ng oras na ito, hindi pwedeng sumali.  ',
		fmt_vn = '3. Thời gian tham gia đố vui có thưởng là: 05:00~11:57 và 13:00~19:57 hàng ngày; ngoài khung giờ này, bạn không thể tham gia đố vui.'
	},
