	[121015] = {
		id = 121015,
		fmt = 'b. Physical strength: During the competition, heroes will continuously consume physical strength. When the physical strength is insufficient, the hero will enter a weakened state (in this state, the speed will be affected and reduced); when physical strength is fully restored, the weakened state will disappear.',
		fmt_ma = 'b. Stamina: Semasa pertandingan, hero akan terus menggunakan stamina. Bila stamina habis, hero akan berada dalam keadaan lemah (kelajuan berkurang); apabila stamina dipulihkan, keadaan lemah hilang.',
		fmt_en = 'b. Physical strength: During the competition, heroes will continuously consume physical strength. When the physical strength is insufficient, the hero will enter a weakened state (in this state, the speed will be affected and reduced); when physical strength is fully restored, the weakened state will disappear.',
		fmt_in = 'b. Stamina: Selama pertandingan, stamina hero akan terus berkurang. Jika stamina habis, hero akan memasuki status lemah (dalam status lemah, kecepatan akan berkurang); saat stamina pulih penuh, status lemah akan hilang',
		fmt_th = 'b. พลังงาน - ระหว่างแข่งพลังงานจะลดลง เมื่อพลังไม่พอจะเข้าสถานะอ่อนแรง (ความเร็วลด) ฟื้นเต็มจะกลับสู่ปกติ',
		fmt_ph = 'b. Pisikal na lakas: Sa loob ng laban, patuloy na nababawasan ang pisikal na lakas ng bayani. Kapag ubos ang pisikal na lakas, ang bayani ay papasok sa mahina na estado (kung saan maaapektuhan at bababa ang bilis); kapag bumalik sa normal ang pisikal na lakas, mawawala ang mahina na estado.  ',
		fmt_vn = 'b. Sức mạnh thể chất: Trong quá trình thi đấu, anh hùng sẽ liên tục tiêu hao sức mạnh thể chất. Khi sức mạnh thể chất không đủ, anh hùng sẽ rơi vào trạng thái suy yếu (trong trạng thái suy yếu, tốc độ sẽ bị ảnh hưởng và giảm xuống); khi sức mạnh thể chất hồi phục đầy đủ, trạng thái suy yếu sẽ biến mất.'
	},
	[121016] = {
		id = 121016,
		fmt = 'c. Acceleration probability: Throughout the match, heroes will have a certain probability of speeding up for a certain period, and their actual speed will increase by the corresponding multiplier.',
		fmt_ma = 'c. Kebarangkalian Pecut: Sepanjang pertandingan, hero berpeluang pecut untuk satu tempoh tertentu, kelajuan sebenar meningkat berkali ganda.',
		fmt_en = 'c. Acceleration probability: Throughout the match, heroes will have a certain probability of speeding up for a certain period, and their actual speed will increase by the corresponding multiplier.',
		fmt_in = 'c. Probabilitas percepatan: Selama pertandingan, hero memiliki peluang tertentu untuk mempercepat dalam jangka waktu tertentu, kecepatan aktual akan meningkat sesuai',
		fmt_th = 'c. โอกาสเร่ง - ระหว่างแข่งมีโอกาสเร่งความเร็วชั่วคราว',
		fmt_ph = 'c. Tsansa ng pagbilis: Sa buong laban, may tiyak na tsansa ang bayani na bumilis sa loob ng takdang oras, at tataas ang aktwal na bilis ng isang katumbas na multiplier.  ',
		fmt_vn = 'c. Xác suất tăng tốc: Trong suốt trận đấu, anh hùng sẽ có một xác suất nhất định để tăng tốc trong một khoảng thời gian nhất định, tốc độ thực tế sẽ tăng lên một bội số tương ứng.'
	},
