	},
	[124005] = {
		id = 124005,
		fmt = '4. After a hero undergoes Z Awakening training, you can level up the awakening power and receive additional stats for the entire team.',
		fmt_ma = '4. Selepas wira dinaik taraf kebangkitan, kuasa kebangkitan boleh dinaikkan dan lebih banyak atribut tambahan boleh diperoleh untuk seluruh pasukan.',
