	[124011] = {
		id = 124011,
		fmt = '1. The reset will refund 100% of the training resources. Z Awakening fragments obtained from refunded resources will still be Z Awakening fragments and will not be transformed into heroes or hero fragments.',
		fmt_ma = '1 Penetapan semula akan memulangkan 100% sumber pembangunan. Serpihan Z Kebangkitan yang ditukar daripada sumber yang dikembalikan masih merupakan serpihan Z Kebangkitan, tidak akan menjadi wira atau serpihan wira.',
		fmt_en = '1. The reset will refund 100% of the training resources. Z Awakening fragments obtained from refunded resources will still be Z Awakening fragments and will not be transformed into heroes or hero fragments.',
