	[124201] = {
		id = 124201,
		fmt = '1. During the event, complete the assigned tasks to control heroes and complete missions to receive generous rewards!',
		fmt_ma = '1. Sepanjang tempoh acara, laksanakan misi yang diberikan untuk mengawal wira, lengkapkan misi untuk menerima ganjaran lumayan!  ',
		fmt_en = '1. During the event, complete the assigned tasks to control heroes and complete missions to receive generous rewards!',
		fmt_in = '1. Selama event, lakukan misi yang diberikan untuk mengendalikan hero, selesaikan misi untuk mendapatkan hadiah besar!',
		fmt_th = '1. ในช่วงเวลากิจกรรม โปรดทำภารกิจที่ได้รับมอบหมายเพื่อควบคุมฮีโร่ เมื่อทำภารกิจสำเร็จจะได้รับรางวัลมากมาย',
		fmt_ph = '1. Sa panahon ng event, kumpletuhin ang mga itinalagang misyon para kontrolin ang mga hero at makatanggap ng magagandang gantimpala!  ',
		fmt_vn = '1.Trong thời gian sự kiện, hãy thực hiện nhiệm vụ được giao phó để điều khiển anh hùng, hoàn thành nhiệm vụ sẽ nhận được phần thưởng hậu hĩnh!'
	},
	[124202] = {
		id = 124202,
		fmt = '2. Performing tasks requires assigning heroes according to the mission requirements, deducting action points and taking some time. If the mission’s point requirements are met #C0xF76B45#, there will be additional surprise rewards!',
		fmt_ma = '2. Melaksanakan penugasan memerlukan penggunaan wira yang sesuai dengan keperluan penugasan, menolak mata tindakan dan memerlukan masa tertentu; jika memenuhi keperluan mata tambahan penugasan #C0xF76B45#, ganjaran mengejut tambahan akan diperoleh!  ',
		fmt_en = '2. Performing tasks requires assigning heroes according to the mission requirements, deducting action points and taking some time. If the mission’s point requirements are met #C0xF76B45#, there will be additional surprise rewards!',
		fmt_in = '2. Menjalankan misi memerlukan hero yang sesuai dengan syarat misi, mengurangi poin aksi dan memakan waktu tertentu. Jika memenuhi syarat poin tambahan #C0xF76B45#, akan ada hadiah kejutan tambahan!',
		fmt_th = '2. การทำภารกิจจำเป็นต้องใช้ฮีโร่ที่เหมาะสมตามเงื่อนไขของภารกิจ ใช้แต้มพลังงานและใช้เวลาตามที่กำหนด หากตรงตามเงื่อนไข #C0xF76B45# จะได้รับรางวัลพิเศษเพิ่ม',
		fmt_ph = '2. Ang pag-assign ng mga hero ay kailangang umayon sa mga requirement ng misyon, magbabawas ng action points at magtatagal ng ilang oras. Kung makakatugon sa bonus requirement ng misyon #C0xF76B45#, may dagdag pang sorpresa na gantimpala!  ',
		fmt_vn = '2. Thực hiện ủy thác cần điều động anh hùng phù hợp với yêu cầu của ủy thác, trừ điểm hành động và tốn một khoảng thời gian nhất định, nếu đáp ứng yêu cầu cộng điểm của ủy thác #C0xF76B45#, sẽ có thêm phần thưởng bất ngờ!'
	},
	[124203] = {
		id = 124203,
		fmt = '3. Tasks are divided into main and side missions, and are arranged in order on the map. You need to #C0xF76B45# complete the previous mission before proceeding to the next mission.',
		fmt_ma = '3. Misi dibahagikan kepada misi utama dan sampingan, disusun mengikut urutan di peta. Perlu #C0xF76B45# selesaikan misi sebelumnya sebelum memulakan misi seterusnya.  ',
		fmt_en = '3. Tasks are divided into main and side missions, and are arranged in order on the map. You need to #C0xF76B45# complete the previous mission before proceeding to the next mission.',
		fmt_in = '3. Misi dibagi menjadi misi utama dan misi sampingan, diatur berurutan di peta. Harus #C0xF76B45# menyelesaikan misi sebelumnya untuk melanjutkan misi berikutnya',
		fmt_th = '3. ภารกิจแบ่งเป็นภารกิจหลักและภารกิจรอง เรียงตามลำดับบนแผนที่ ต้อง #C0xF76B45# เคลียร์ภารกิจก่อนหน้าให้สำเร็จก่อนจึงจะดำเนินการต่อได้',
		fmt_ph = '3. Ang mga misyon ay nahahati sa pangunahing at side missions, inayos ayon sa pagkakasunod sa mapa. Kailangang #C0xF76B45# kumpletuhin ang naunang misyon bago magsimula sa susunod  ',
		fmt_vn = '3. Nhiệm vụ được chia thành nhiệm vụ chính và nhiệm vụ phụ, được sắp xếp theo thứ tự trên bản đồ. Cần #C0xF76B45# hoàn thành nhiệm vụ trước đó trước khi tiến hành nhiệm vụ tiếp theo.'
	},
	[124204] = {
		id = 124204,
		fmt = '4. Side missions along the path can be completed multiple times, and they may reward chests. Completing side missions can give generous rewards, and treasure chests provide immediate rewards. Don’t miss them!',
		fmt_ma = '4. Misi sampingan di laluan boleh dilakukan berulang kali dan menawarkan ganjaran peti harta; misi sampingan memberikan ganjaran lumayan, manakala peti harta akan terus memberikan ganjaran — jangan terlepas!  ',
		fmt_en = '4. Side missions along the path can be completed multiple times, and they may reward chests. Completing side missions can give generous rewards, and treasure chests provide immediate rewards. Don’t miss them!',
		fmt_in = '4. Misi sampingan di jalur dapat diulang, ada hadiah peti, misi sampingan memberi hadiah besar, peti harta karun memberi hadiah langsung, jangan lewatkan!',
		fmt_th = '4. ภารกิจรองสามารถทำซ้ำได้ และมีรางวัลเป็นหีบสมบัติ ภารกิจรองจะมีรางวัลมาก หีบสมบัติจะเปิดรับรางวัลทันที อย่าพลาด',
		fmt_ph = '4. Ang mga side mission ay maaaring ulitin at may mga gantimpalang chest, maaaring makakuha ng magagandang gantimpala sa side mission at agarang reward mula sa treasure chest, huwag palampasin!  ',
		fmt_vn = '4. Nhiệm vụ phụ trên tuyến có thể thực hiện nhiều lần, cũng có phần thưởng là rương, nhiệm vụ phụ có thể nhận được phần thưởng hậu hĩnh, còn rương kho báu thì nhận thưởng ngay lập tức, đừng bỏ lỡ chúng!'
	},
	[124205] = {
		id = 124205,
		fmt = '5. All tasks (including treasure chests) are displayed on the map. If you haven’t completed them, you can view them by clicking.',
		fmt_ma = '5. Semua misi (termasuk peti harta) dipaparkan di peta; jika belum diselesaikan, boleh dilihat dengan klik.  ',
		fmt_en = '5. All tasks (including treasure chests) are displayed on the map. If you haven’t completed them, you can view them by clicking.',
		fmt_in = '5. Semua misi (termasuk peti harta karun) ditampilkan di peta, yang belum selesai bisa dilihat dengan klik',
		fmt_th = '5. ทุกภารกิจ (รวมถึงหีบสมบัติ) จะแสดงบนแผนที่ หากยังไม่สำเร็จสามารถคลิกดูได้',
		fmt_ph = '5. Lahat ng misyon (kasama ang treasure chests) ay ipinapakita sa mapa at maaaring makita kapag hindi pa natatapos sa pamamagitan ng pag-click',
		fmt_vn = '5. Tất cả các nhiệm vụ (bao gồm cả rương kho báu) được hiển thị trên bản đồ, nếu chưa hoàn thành, đều có thể được xem bằng cách nhấp chuột.'
	},
	[124206] = {
		id = 124206,
		fmt = '6. Missions require you to manually assign heroes. After completing the mission, remember to #C0xF76B45# claim your reward. #C0xFFFFFF# You can also undertake (including unfinished missions that haven’t claimed rewards) 3 #C0xFFFFFF# tasks at once. Plan your tasks wisely.',
		fmt_ma = '4. Misi memerlukan pemain sendiri mengatur wira; setelah misi selesai ingat #C0xF76B45# tuntut ganjaran secara manual. #C0xFFFFFF# Pada masa yang sama #C0xF76B45# boleh melaksanakan (termasuk misi yang telah selesai tetapi belum tuntut ganjaran) 3 #C0xFFFFFF# misi serentak, sila atur dengan baik.  ',
		fmt_en = '6. Missions require you to manually assign heroes. After completing the mission, remember to #C0xF76B45# claim your reward. #C0xFFFFFF# You can also undertake (including unfinished missions that haven’t claimed rewards) 3 #C0xFFFFFF# tasks at once. Plan your tasks wisely.',
		fmt_in = '6. Misi perlu mengatur hero secara manual, setelah selesai ingat #C0xF76B45# klaim hadiah sendiri. #C0xFFFFFF# Selain itu, #C0xF76B45# bisa menjalankan (termasuk misi selesai yang belum diklaim) 3 #C0xFFFFFF# misi sekaligus, atur dengan bijak',
		fmt_th = '4. ภารกิจต้องเลือกฮีโร่ด้วยตัวเอง เมื่อทำสำเร็จ #C0xF76B45# ต้องกดรับรางวัลด้วยตัวเอง #C0xFFFFFF# พร้อมกันนี้ #C0xF76B45# สามารถทำ (รวมถึงภารกิจที่เสร็จแล้วแต่ยังไม่ได้รับรางวัล) ได้ 3 #C0xFFFFFF# ภารกิจ ควรวางแผนให้ดี',
		fmt_ph = '4. Kailangan i-assign ng player ang mga hero para sa misyon, at huwag kalimutang #C0xF76B45# kunin ang gantimpala pagkatapos matapos ang misyon. #C0xFFFFFF# Kasabay nito, maaaring magpatupad ng hanggang 3 #C0xFFFFFF# misyon (kasama ang mga natapos pero hindi pa kinukuha ang gantimpala), planuhin nang maayos  ',
		fmt_vn = '4. Nhiệm vụ cần tự tay phân phái anh hùng, nhiệm vụ hoàn thành nhớ #C0xF76B45# tự mình nhận thưởng. #C0xFFFFFF# Đồng thời #C0xF76B45#có thể thực hiện (bao gồm cả nhiệm vụ đã hoàn thành chưa nhận thưởng) 3 #C0xFFFFFF# nhiệm vụ, hãy sắp xếp hợp lý.'
	},
	[124207] = {
		id = 124207,
		fmt = '7. During the task execution, players are allowed to abandon the task midway. After abandoning, the task execution time will be reset, action points will be refunded, and players will not receive mission rewards.',
		fmt_ma = '5. Semasa menjalankan misi, pemain boleh memilih untuk membatalkan misi pada bila-bila masa. Setelah dibatalkan, masa pelaksanaan akan diset semula ke 0, mata tindakan dikembalikan, dan pemain tidak akan menerima ganjaran misi.  ',
		fmt_en = '7. During the task execution, players are allowed to abandon the task midway. After abandoning, the task execution time will be reset, action points will be refunded, and players will not receive mission rewards.',
		fmt_in = '7. Selama menjalankan misi, pemain boleh membatalkan misi. Setelah dibatalkan, waktu pengerjaan kembali ke 0, poin aksi dikembalikan, dan tidak mendapatkan hadiah misi',
		fmt_th = '5. ระหว่างทำภารกิจ ผู้เล่นสามารถยกเลิกภารกิจก่อนจบได้ หากยกเลิก เวลาที่ใช้จะถูกรีเซ็ตเป็น 0 แต้มพลังงานจะคืน และจะไม่ได้รับรางวัล',
		fmt_ph = '5. Sa proseso ng pagsasagawa ng misyon, maaaring isuko ng player ang misyon. Kapag inabandona, ire-reset ang oras, maibabalik ang action points, at hindi matatanggap ang gantimpala  ',
		fmt_vn = '5. Trong quá trình thực hiện nhiệm vụ, người chơi được phép từ bỏ nhiệm vụ giữa chừng. Sau khi từ bỏ, thời gian thực hiện nhiệm vụ sẽ được đặt về 0, điểm hành động được hoàn trả và người chơi sẽ không nhận được phần thưởng nhiệm vụ.'
	},
	[124301] = {
		id = 124301,
		fmt = '1. Welcome to the Hero\'s Journey, it’s said that the best way to conquer a journey is to make yourself the prey.',
