		fmt_th = '1. ยินดีต้อนรับสู่เส้นทางฮีโร่ ว่ากันว่า วิธีที่ดีที่สุดในการพิชิตการเดินทางคือต้องกลายเป็นเหยื่อเสียก่อน',
		fmt_ph = '1. Maligayang pagdating sa Hero\'s Journey, sabi nila ang pinakamabisang paraan para malampasan ang paglalakbay ay maging biktima ng sarili  ',
		fmt_vn = '1.Chào mừng đến với Hành Trình Anh Hùng, người ta nói rằng cách tốt nhất để chinh phục hành trình là biến mình thành con mồi.'
	},
