	[124402] = {
		id = 124402,
		fmt = '#F36#1. Each technique can only refine 2 attributes at most.',
		fmt_ma = '#F36#1. Setiap Kitab Rahsia hanya boleh memilih maksimum 2 atribut untuk penalaan.',
		fmt_en = '#F36#1. Each technique can only refine 2 attributes at most.',
