		fmt_th = '#F36#1. เคล็ดวิชาหนึ่งสามารถเลือกรีเฟรชได้สูงสุด 2 สถานะ',
		fmt_ph = '#F36#1. Ang bawat skill book ay maaaring pumili lamang ng hanggang 2 attributes para sa refinement',
