	[124403] = {
		id = 124403,
		fmt = '#F36#2. After selecting the attributes to refine, the selected attributes will be locked and cannot be undone or changed. This action cannot be reversed, so please select the attributes carefully before refining.',
		fmt_ma = '#F36#2. Selepas memilih atribut yang ingin ditapis, atribut yang dipilih akan dikunci dan tidak boleh dibatalkan atau diubah. Tindakan ini tidak boleh dipulihkan, sila pilih atribut dengan berhati-hati sebelum menapis.  ',
		fmt_en = '#F36#2. After selecting the attributes to refine, the selected attributes will be locked and cannot be undone or changed. This action cannot be reversed, so please select the attributes carefully before refining.',
		fmt_in = '#F36#2. Setelah memilih atribut yang ingin dimurnikan, atribut akan terkunci dan tidak bisa dibatalkan atau diubah. Tindakan ini tidak bisa di-undo, harap pilih dengan hati-hati sebelum memurnikan',
		fmt_th = '#F36#2. เมื่อเลือกสถานะที่จะรีเฟรชแล้ว สถานะนั้นจะล็อก ไม่สามารถยกเลิกหรือเปลี่ยนเป้าหมายได้ การกระทำนี้ย้อนกลับไม่ได้ กรุณาเลือกอย่างระมัดระวัง',
		fmt_ph = '#F36#2. Kapag napili na ang attribute na gustong i-refine, ito ay naka-lock at hindi na maaaring kanselahin o baguhin ang target ng refinement. Ang aksyon na ito ay hindi na mababawi, mangyaring piliin nang maingat bago i-refine.',
		fmt_vn = '#F36#2. Sau khi chọn thuộc tính muốn tinh luyện, thuộc tính đã chọn sẽ bị khóa và không thể hủy bỏ hoặc thay đổi mục tiêu tinh luyện. Thao tác này không thể hoàn tác, vui lòng chọn kỹ thuộc tính trước khi tinh luyện.'
	},
	[124404] = {
		id = 124404,
		fmt = '#F36#3. When refining, the type of attribute will be randomly selected, and the number of enhancements for all random attributes will be reset simultaneously.',
		fmt_ma = '#F36#3. Semasa penalaan, jenis atribut yang dipilih akan dijana secara rawak, dan bilangan pengukuhan semua atribut akan diset semula serentak.  ',
		fmt_en = '#F36#3. When refining, the type of attribute will be randomly selected, and the number of enhancements for all random attributes will be reset simultaneously.',
		fmt_in = '#F36#3. Saat memurnikan, jenis atribut dipilih secara acak, dan jumlah penguatan semua atribut juga di-reset bersamaan',
		fmt_th = '#F36#3. ขณะรีเฟรช สถานะที่เลือกจะสุ่มใหม่ และการเสริมพลังสถานะทั้งหมดจะรีเซ็ตพร้อมกัน',
		fmt_ph = '#F36#3. Kapag ni-refine, ang uri ng attribute ay pipiliin nang random at ang bilang ng enhancement ng lahat ng random na attributes ay ire-reset nang sabay-sabay.',
