		fmt_in = '#C0xF76B45#Legenda mengatakan bahwa di kuil bawah danau, hidup Pokémon tercantik di dunia...#C0xFFFFFF#',
		fmt_th = '#C0xF76B45#ตำนานเล่าว่า ในวิหารใต้น้ำมี Pokémon ที่สวยที่สุดในโลกอาศัยอยู่...#C0xFFFFFF#',
		fmt_ph = '#C0xF76B45#Sinasabing sa templo sa ilalim ng lawa ay naninirahan ang pinakamagandang Pokémon sa buong mundo...#C0xFFFFFF#',
		fmt_vn = '#C0xF76B45#Truyền thuyết kể rằng trong đền thờ dưới hồ, có một Pokémon đẹp nhất thế giới sinh sống...#C0xFFFFFF#'
	},
