	},
	[125004] = {
		id = 125004,
		fmt = '1. A fixed number of maps are unlocked every day, and players can retry incomplete maps.  ',
		fmt_ma = '1. Setiap hari membuka beberapa peta tetap, boleh mencabar semula peta yang belum diselesaikan.  ',
		fmt_en = '1. A fixed number of maps are unlocked every day, and players can retry incomplete maps.  ',
		fmt_in = '1. Setiap hari akan membuka sejumlah peta tetap, bisa mencoba ulang peta yang belum selesai',
		fmt_th = '1. เปิดแผนที่จำนวนหนึ่งต่อวัน สามารถเข้าเล่นแผนที่ที่ยังไม่ผ่านได้อีก',
		fmt_ph = '1. Magbubukas ng takdang bilang ng mga mapa araw-araw, pwedeng subukang ulitin ang mga di pa natapos na mapa.',
		fmt_vn = '1. Mở một số lượng bản đồ cố định mỗi ngày, có thể thử thách lại bản đồ chưa hoàn thành.'
	},
	[125005] = {
		id = 125005,
		fmt = '2. Each dungeon can only be experienced once after completing it for the first time, and the next stage will only open after completing the previous one.  ',
		fmt_ma = '2. Setiap peta hanya boleh dimainkan sekali selepas selesai buat kali pertama, perlu selesai peta sebelumnya untuk membuka peta seterusnya.  ',
		fmt_en = '2. Each dungeon can only be experienced once after completing it for the first time, and the next stage will only open after completing the previous one.  ',
		fmt_in = '2. Dungeon hanya bisa dimainkan sekali setelah selesai pertama kali, dan harus menyelesaikan stage sebelumnya untuk membuka stage berikutnya',
		fmt_th = '2. ด่านที่เคยผ่านครั้งแรกแล้วจะเล่นได้แค่ครั้งเดียว ต้องผ่านด่านก่อนจึงจะเปิดด่านถัดไปได้',
		fmt_ph = '2. Ang kopya ay pwedeng maranasan isang beses lamang pagkatapos ng unang pagtatapos, at dapat tapusin ang naunang stage bago mabuksan ang susunod.',
		fmt_vn = '2. Bản sao chỉ được trải nghiệm một lần duy nhất sau khi hoàn thành lần đầu tiên, và phải hoàn thành cửa ải trước đó mới mở được cửa ải tiếp theo.'
	},
	[125006] = {
		id = 125006,
		fmt = '3. The dialogues within the dungeon contain tips for clearing the stage; after clearing the stage, you can review the storyline in the information interface.  ',
		fmt_ma = '3. Dialog dalam peta mengandungi petunjuk untuk menamatkan cabaran, selepas selesai boleh melihat semula jalan cerita di antara muka maklumat.  ',
		fmt_en = '3. The dialogues within the dungeon contain tips for clearing the stage; after clearing the stage, you can review the storyline in the information interface.  ',
		fmt_in = '3. Dialog dalam dungeon berisi petunjuk melewati stage, setelah selesai bisa melihat kembali cerita di menu informasi',
		fmt_th = '3. บทสนทนาในด่านมีเคล็ดลับในการผ่าน หลังผ่านด่านสามารถดูเนื้อเรื่องอีกครั้งได้ในหน้าเมนู',
		fmt_ph = '3. Ang mga diyalogo sa kopya ay naglalaman ng sikreto ng pagdaig, pwedeng balikan ang kwento sa info interface pagkatapos ng pagtatapos.',
		fmt_vn = '3. Cuộc đối thoại trong bản sao ẩn chứa bí quyết vượt ải, sau khi vượt ải có thể xem lại cốt truyện ở giao diện thông tin.'
	},
