		fmt = '#C0xF76B45#Tips for clearing the stage:#C0xFFFFFF#Pay attention to the storyline dialogues.',
		fmt_ma = '#C0xF76B45#Petua cabaran:#C0xFFFFFF#Perhatikan kandungan dialog jalan cerita',
