		fmt_th = '#C0xF76B45#เทคนิคผ่านด่าน:#C0xFFFFFF#ใส่ใจบทสนทนาเนื้อเรื่อง',
		fmt_ph = '#C0xF76B45#Tips sa pagdaig:#C0xFFFFFF#Pansinin ang kwento sa mga diyalogo',
		fmt_vn = '#C0xF76B45#Mẹo vượt ải:#C0xFFFFFF#Chú ý nội dung hội thoại cốt truyện'
