	[125301] = {
		id = 125301,
		fmt = '1. During the event, complete tasks to proceed with prayers in the event interface.',
		fmt_ma = '1. Semasa acara berlangsung, lengkapkan misi untuk melakukan doa di antara muka acara.  ',
		fmt_en = '1. During the event, complete tasks to proceed with prayers in the event interface.',
		fmt_in = '1. Selama event berlangsung, selesaikan misi untuk melakukan doa di antarmuka event',
		fmt_th = '1.ในช่วงเวลากิจกรรม ให้ทำภารกิจเพื่อทำการอธิษฐานในหน้าอีเวนต์',
		fmt_ph = '1. Sa panahon ng event, kumpletuhin ang mga misyon upang magsagawa ng panalangin sa interface ng event.  ',
		fmt_vn = '1.Trong thời gian sự kiện, hoàn thành nhiệm vụ để tiến hành cầu nguyện trong giao diện sự kiện.'
	},
	[125302] = {
		id = 125302,
		fmt = '2. When praying, you can receive random blessings, and you may also receive a lucky blessing.',
		fmt_ma = '2. Apabila berdoa, anda boleh menerima berkat secara rawak, juga berpeluang menerima berkat bertuah.  ',
		fmt_en = '2. When praying, you can receive random blessings, and you may also receive a lucky blessing.',
		fmt_in = '2. Saat berdoa, Anda bisa mendapatkan berkah secara acak, juga bisa mendapatkan berkah keberuntungan',
		fmt_th = '2.เมื่ออธิษฐาน คุณจะได้รับพรแบบสุ่ม หรืออาจได้รับพรแห่งโชคลาภ',
		fmt_ph = '2. Kapag nananalangin, maaari kang makatanggap ng random na biyaya, o swerte na biyaya.  ',
		fmt_vn = '2.Khi cầu nguyện, bạn có thể nhận được lời chúc phúc ngẫu nhiên, cũng có thể nhận được lời chúc phúc may mắn.'
	},
	[125303] = {
		id = 125303,
		fmt = '3. Each time you pray, if you do not receive a lucky blessing, you can light up a lucky charm. The more lucky charms you light up, the higher the chance of receiving a lucky blessing. Once all lucky charms in the interface are lit, the next prayer will definitely grant a lucky blessing.',
		fmt_ma = '3. Setiap kali berdoa, jika tidak menerima berkat bertuah, anda boleh menyalakan satu jimat bertuah. Semakin banyak jimat bertuah yang dinyalakan, semakin tinggi peluang mendapat berkat bertuah. Apabila semua jimat bertuah di antara muka dinyalakan, doa seterusnya pasti akan mendapat berkat bertuah.  ',
		fmt_en = '3. Each time you pray, if you do not receive a lucky blessing, you can light up a lucky charm. The more lucky charms you light up, the higher the chance of receiving a lucky blessing. Once all lucky charms in the interface are lit, the next prayer will definitely grant a lucky blessing.',
		fmt_in = '3. Setiap kali berdoa, jika tidak mendapatkan berkah keberuntungan, Anda bisa menyalakan satu jimat keberuntungan. Semakin banyak jimat yang dinyalakan, semakin besar kemungkinan mendapatkan berkah keberuntungan. Jika semua jimat sudah dinyalakan, doa berikutnya pasti akan mendapatkan berkah keberuntungan',
		fmt_th = '3.ทุกครั้งที่อธิษฐาน หากยังไม่ได้รับพรแห่งโชคลาภ จะสามารถจุดยันต์โชคลาภได้ 1 ใบ จำนวนยันต์โชคลาภที่จุดมากขึ้น โอกาสได้รับพรแห่งโชคลาภก็จะสูงขึ้น เมื่อจุดยันต์ครบทั้งหมด การอธิษฐานครั้งถัดไปจะได้รับพรแห่งโชคลาภอย่างแน่นอน',
		fmt_ph = '3. Sa bawat panalangin, kung hindi nakatanggap ng swerte na biyaya, maaari mong sindihan ang isang swerte na anting-anting. Mas maraming na sindi na anting-anting, mas mataas ang tsansa na makatanggap ng swerte na biyaya. Kapag nasindi na lahat ng anting-anting sa interface, ang susunod na panalangin ay tiyak na makakatanggap ng swerte na biyaya.  ',
		fmt_vn = '3.Mỗi lần cầu nguyện, nếu không nhận được lời chúc phúc may mắn, bạn có thể thắp sáng một lá bùa may mắn. Số lượng lá bùa may mắn thắp sáng càng nhiều, xác suất nhận được lời chúc phúc may mắn càng lớn. Khi thắp sáng tất cả các lá bùa may mắn trong giao diện, lần cầu nguyện tiếp theo chắc chắn sẽ nhận được lời chúc phúc may mắn.'
	},
	[125304] = {
		id = 125304,
		fmt = '4. Tasks will reset daily, so please ensure to complete and claim rewards in time. The number of prayers you have received will not reset and will remain the same until the event ends.',
		fmt_ma = '4. Misi akan diset semula mengikut masa harian, sila lengkapkan dan tuntut ganjaran tepat pada masanya. Bilangan doa yang telah dilakukan tidak akan diset semula dan akan dikekalkan sehingga acara berakhir.  ',
		fmt_en = '4. Tasks will reset daily, so please ensure to complete and claim rewards in time. The number of prayers you have received will not reset and will remain the same until the event ends.',
		fmt_in = '4. Misi akan di-reset setiap hari, harap selesaikan dan klaim hadiah tepat waktu. Jumlah doa yang sudah dilakukan tidak akan di-reset dan tetap berlaku hingga event berakhir',
		fmt_th = '4.ภารกิจจะรีเซ็ตเวลาในแต่ละวัน โปรดทำและรับรางวัลให้ทัน สะสมจำนวนครั้งอธิษฐานจะไม่รีเซ็ตและจะคงอยู่จนจบกิจกรรม',
		fmt_ph = '4. Ang mga misyon ay mare-reset araw-araw, pakitiyak na makumpleto at makuha ang gantimpala sa tamang oras. Ang bilang ng mga panalangin na natanggap ay hindi mare-reset at mananatili hanggang matapos ang event.  ',
		fmt_vn = '4.Nhiệm vụ sẽ được đặt lại theo thời gian hàng ngày, vui lòng chú ý hoàn thành và nhận thưởng kịp thời. Số lần cầu nguyện đã nhận không bị đặt lại và sẽ giữ nguyên cho đến khi sự kiện kết thúc.'
	},
	[125305] = {
		id = 125305,
		fmt = '5. In the prayer task interface, you can view the rewards you have received during this event.',
		fmt_ma = '5. Di antara muka misi doa, anda boleh melihat ganjaran yang telah diterima dalam acara ini.  ',
		fmt_en = '5. In the prayer task interface, you can view the rewards you have received during this event.',
		fmt_in = '5. Di antarmuka misi doa, Anda bisa melihat hadiah yang sudah diterima selama event ini',
		fmt_th = '5.ในหน้าเควสอธิษฐาน สามารถดูรางวัลที่ได้รับจากกิจกรรมนี้ได้',
		fmt_ph = '5. Sa interface ng panalangin na misyon, maaari mong makita ang mga gantimpalang natanggap sa event na ito.  ',
