	[125503] = {
		id = 125503,
		fmt = '1. The chamber battle process will occur across multiple servers, with a total of #C0xF76B45#16#C0xFFFFFF# guilds selected to compete.',
		fmt_ma = '1. Proses pemilihan bahagian akan dijalankan di beberapa server, secara keseluruhan akan memilih #C0xF76B45#16#C0xFFFFFF# persatuan terkuat untuk bersaing.  ',
		fmt_en = '1. The chamber battle process will occur across multiple servers, with a total of #C0xF76B45#16#C0xFFFFFF# guilds selected to compete.',
		fmt_in = '1. Proses konstruksi dilakukan di banyak server, total akan dipilih #C0xF76B45#16#C0xFFFFFF# guild terkuat untuk bertanding',
		fmt_th = '1.การจัดศึกห้องนิรภัยจะมีหลายเซิร์ฟเวอร์ โดยจะคัดเลือก #C0xF76B45#16#C0xFFFFFF# กิลด์ที่แข็งแกร่งที่สุดเข้าร่วมแข่งขัน',
		fmt_ph = '1. Ang proseso ng Guild War ay isasagawa sa maraming server, pipiliin ang #C0xF76B45#16#C0xFFFFFF# pinakamalalakas na guild para makipagkompetensya.  ',
		fmt_vn = '1. Quá trình phòng ốc cần diễn ra ở nhiều server, tổng cộng sẽ chọn ra #C0xF76B45#16#C0xFFFFFF# bang hội mạnh nhất để cạnh tranh.'
	},
	[125504] = {
		id = 125504,
		fmt = '2. The selection will be based on the total accumulated points of the guilds over three weeks (which can be checked in the Grand Chamber Battle interface), and the #C0xF76B45#top-ranked guilds#C0xFFFFFF# will be directly selected.',
		fmt_ma = '2. Pemilihan akan berdasarkan jumlah mata terkumpul persatuan dalam tiga minggu (boleh dilihat dalam antara muka Pertempuran Bahagian), #C0xF76B45#persatuan tempat pertama dan kedua#C0xFFFFFF# akan dipilih secara langsung.  ',
		fmt_en = '2. The selection will be based on the total accumulated points of the guilds over three weeks (which can be checked in the Grand Chamber Battle interface), and the #C0xF76B45#top-ranked guilds#C0xFFFFFF# will be directly selected.',
		fmt_in = '2. Pemilihan berdasarkan total poin akumulasi Guild War selama tiga minggu (bisa dilihat di antarmuka Guild War), #C0xF76B45#guild peringkat 1 dan 2#C0xFFFFFF# akan langsung terpilih',
		fmt_th = '2.การคัดเลือกจะอิงจากคะแนนรวมสะสมในสงครามกิลด์ช่วง 3 สัปดาห์ (สามารถดูในหน้า ศึกห้องนิรภัย) โดย #C0xF76B45#กิลด์อันดับ 1 และ 2 #C0xFFFFFF#จะได้รับเลือกโดยตรง',
		fmt_ph = '2. Pipiliin ang mga guild base sa kabuuang puntos na nakuha sa loob ng tatlong linggo (makikita sa Guild War interface), ang #C0xF76B45#unang at pangalawang ranggo#C0xFFFFFF# ay diretso mapipili.  ',
		fmt_vn = '2. Công trình sẽ chọn lọc dựa trên tổng điểm tích lũy của chiến bang trong ba tuần (có thể xem trong giao diện Đại Chiến Phòng), #C0xF76B45#bang xếp hạng nhất và nhì #C0xFFFFFF#sẽ được chọn trực tiếp.'
	},
	[125505] = {
		id = 125505,
		fmt = '3. If there aren\'t enough guilds in the cross-server cluster to conduct the battle, guilds ranked 3rd to 5th in the server cluster will be selected (priority will be given to guilds with higher total battle power).',
		fmt_ma = '3. Jika dalam kumpulan cross-server yang digabungkan tidak cukup bilangan persatuan yang diperlukan, maka persatuan ranking 3~5 dalam kumpulan yang sama (diutamakan yang mempunyai kuasa tempur keseluruhan lebih tinggi) akan dipilih.  ',
		fmt_en = '3. If there aren\'t enough guilds in the cross-server cluster to conduct the battle, guilds ranked 3rd to 5th in the server cluster will be selected (priority will be given to guilds with higher total battle power).',
		fmt_in = '3. Jika di cluster antar server jumlah guild tidak cukup, maka akan dipilih dari guild peringkat 3~5 berdasarkan poin Guild War (prioritas untuk guild dengan total power lebih tinggi)',
		fmt_th = '3.หากจำนวนกิลด์ในกลุ่มเซิร์ฟเวอร์ไม่เพียงพอ ระบบจะเลือกเพิ่มจากกิลด์อันดับ 3-5 ตามคะแนนกิลด์ในเซิร์ฟเวอร์กลุ่มเดียวกัน (จะเลือกกิลด์ที่มีพลังรบสูงก่อน)',
		fmt_ph = '3. Kung kulang ang bilang ng guild sa cross-server cluster, pipiliin mula sa ika-3 hanggang ika-5 na ranggo base sa puntos sa guild war sa parehong cluster (pinaprioritize ang guild na may mas mataas na lakas).  ',
		fmt_vn = '3. Nếu trong cụm liên server được ghép trận, không đủ số lượng công hội cần thiết để thực hiện công trình, thì sẽ chọn từ các công hội xếp hạng 3~5 theo điểm công hội chiến trong cùng cụm liên server (ưu tiên chọn công hội có tổng chiến lực cao hơn).'
	},
	[125506] = {
		id = 125506,
		fmt = '4. After the three-week guild battle, the guild and its members who participated in the battle will be locked. Any new members joining the guild afterward will not be able to participate in the current Chamber Battle.',
		fmt_ma = '4. Selepas tiga minggu Pertempuran Persatuan berakhir, persatuan dan ahli yang bertempur akan dikunci. Ahli baru yang menyertai selepas itu tidak boleh mengambil bahagian dalam Pertempuran Bahagian kali ini.  ',
		fmt_en = '4. After the three-week guild battle, the guild and its members who participated in the battle will be locked. Any new members joining the guild afterward will not be able to participate in the current Chamber Battle.',
		fmt_in = '4. Setelah 3 minggu Guild War berakhir, guild dan anggota yang ikut bertarung akan terkunci. Anggota yang masuk setelah pemilihan tidak bisa ikut di musim ini',
		fmt_th = '4.หลังจบ 3 สัปดาห์ของสงครามกิลด์ กิลด์และสมาชิกที่เข้าร่วมจะถูกล็อก สมาชิกใหม่ที่เข้า guild จะไม่สามารถเข้าร่วมศึกห้องนิรภัยรอบนี้ได้',
		fmt_ph = '4. Pagkatapos ng tatlong linggo ng Guild War, ang guild at mga miyembro nito ay naka-lock. Ang mga bagong miyembrong sumali sa guild ay hindi na makakasali sa kasalukuyang Guild War season.  ',
		fmt_vn = '4. Sau khi kết thúc 3 tuần Công Hội Chiến, công hội và các thành viên tham gia chiến đấu trong công hội sẽ bị khóa. Các thành viên gia nhập công hội được chọn sau đó sẽ không thể tham gia Phòng Ốc Đại Tác Chiến kỳ này.'
	},
