	[125509] = {
		id = 125509,
		fmt = '2. The Battle of the Chamber consists of two phases: the qualifiers and the finals. The qualifiers take place on #C0xF76B45#Friday#C0xFFFFFF# of the open week, and the finals take place on #C0xF76B45#Sunday#C0xFFFFFF# of the open week.',
