	[125703] = {
		id = 125703,
		fmt = '2. During the event, upgrade the designated theme heroes to a specified star level to receive free rewards! You can also unlock the option to purchase discounted paid gift packs, helping you level up your stars faster!',
		fmt_ma = '2. Sepanjang acara, tingkatkan bintang hero tema ke tahap yang ditetapkan untuk menerima ganjaran percuma! Pada masa sama, buka peluang membeli pakej berbayar bernilai tinggi, membantu anda meningkatkan bintang dengan lebih pantas!  ',
		fmt_en = '2. During the event, upgrade the designated theme heroes to a specified star level to receive free rewards! You can also unlock the option to purchase discounted paid gift packs, helping you level up your stars faster!',
		fmt_in = '2. Selama event, upgrade bintang hero tema untuk mendapatkan hadiah gratis! Juga membuka kesempatan membeli paket berbayar dengan diskon besar untuk mempercepat upgrade',
		fmt_th = '2.ในช่วงกิจกรรม อัปเกรดฮีโร่หัวข้อถึงระดับดาวที่กำหนด จะได้รับรางวัลฟรี! พร้อมปลดล็อกสิทธิ์ซื้อแพ็กเกจสุดคุ้มช่วยให้อัปดาวได้เร็วขึ้น',
		fmt_ph = '2.Sa panahon ng event, kapag na-upgrade ang featured hero sa tinukoy na star level, makakakuha ng libreng gantimpala! Kasama rin ang pagbubukas ng opsyon para bumili ng super value na gift packs para mas mapabilis ang pag-upgrade  ',
		fmt_vn = '2. Trong thời gian sự kiện, nâng cấp tướng chủ đề lên cấp sao chỉ định để nhận thưởng miễn phí! Đồng thời mở khóa quyền mua các gói quà trả phí với giá trị siêu hời tương ứng, giúp bạn tăng sao nhanh chóng hơn một bước!'
	},
	[125704] = {
		id = 125704,
		fmt = '3. Theme heroes typically have high potential and superior strength, making them highly valuable for development, so it is recommended to prioritize resources to improve them.',
		fmt_ma = '3. Hero tema biasanya mempunyai potensi tinggi dan kekuatan luar biasa, sangat berbaloi untuk dibangunkan, utamakan penggunaan sumber daya.  ',
		fmt_en = '3. Theme heroes typically have high potential and superior strength, making them highly valuable for development, so it is recommended to prioritize resources to improve them.',
		fmt_in = '3. Hero tema biasanya punya potensi dan kekuatan besar, sangat layak untuk difokuskan',
		fmt_th = '3.ฮีโร่หัวข้อส่วนใหญ่มักมีศักยภาพสูง ควรโฟกัสพัฒนา',
		fmt_ph = '3.Ang mga featured hero ay kadalasang may mataas na potensyal, inirerekomenda na bigyang prioridad ang pagpapalakas  ',
		fmt_vn = '3. Các tướng chủ đề thường có tiềm năng cao và sức mạnh vượt trội, giá trị bồi dưỡng rất lớn, nên ưu tiên dồn tài nguyên để phát triển.'
	},
