	[125804] = {
		id = 125804,
		fmt = '3. Click on the avatar above to select heroes, preview the corresponding rewards and gift packs. You can freely change your selection before locking it, but after the event starts, no changes can be made.',
		fmt_ma = '3. Klik avatar di atas untuk memilih hero, pratonton ganjaran dan pakej yang berkaitan, anda boleh tukar pilihan secara bebas sebelum kunci, selepas acara bermula, tidak boleh diubah lagi.  ',
