	[125922] = {
		id = 125922,
		fmt = '1. World Martial Arts Tournament season rewards include server-wide ranking rewards at the end of the season and tier rank rewards. You can click the "Rewards" button to view details. Rewards will be sent via mail after the season ends.',
		fmt_ma = '1. Ganjaran musim Kejohanan Dunia termasuk ganjaran ranking seluruh server di akhir musim, ganjaran peringkat, boleh klik butang "Ganjaran" untuk lihat butiran. Ganjaran akan dihantar melalui mel selepas musim tamat.  ',
		fmt_en = '1. World Martial Arts Tournament season rewards include server-wide ranking rewards at the end of the season and tier rank rewards. You can click the "Rewards" button to view details. Rewards will be sent via mail after the season ends.',
		fmt_in = '1. Hadiah musim Turnamen Seni Bela Diri Dunia Terkuat mencakup hadiah peringkat seluruh server saat musim berakhir, hadiah peringkat rank saat musim berakhir, bisa klik tombol "Hadiah" untuk melihat detail. Hadiah akan diterima melalui surat setelah musim berakhir.  ',
		fmt_th = '1. รางวัลประจำฤดูกาลของศึกศิลปะการต่อสู้อันดับหนึ่งใต้หล้า จะรวมถึงรางวัลจัดอันดับเซิร์ฟเวอร์ทั้งหมดเมื่อจบฤดูกาล รางวัลระดับขั้นเมื่อจบฤดูกาล สามารถกดปุ่ม "รางวัล" เพื่อดูรายละเอียด รางวัลจะถูกส่งทางจดหมายหลังจบฤดูกาล  ',
		fmt_ph = '1.Ang season reward ng World Martial Arts Tournament ay may kasamang server-wide ranking reward at rank tier reward na matatanggap pagkatapos ng season. Pindutin ang "Reward" button para makita ang detalye. Ang reward ay ipapadala sa mail pagkatapos ng season  ',
		fmt_vn = '1. Phần thưởng mùa giải Thiên Hạ Đệ Nhất Võ Đạo Hội bao gồm phần thưởng xếp hạng toàn server khi kết thúc mùa giải, phần thưởng bậc rank khi kết thúc mùa giải, có thể nhấn vào nút "Phần thưởng" để xem chi tiết. Phần thưởng sẽ được nhận qua thư sau khi kết thúc mùa giải.'
	},
	[125923] = {
		id = 125923,
		fmt = '2. The World Martial Arts Tournament will grant corresponding titles based on individual rankings. All titles will be announced in the server channel when players log in. Notably, the top player, Supreme King, will be broadcasted server-wide upon login.',
		fmt_ma = '2. Kejohanan Dunia akan memberikan gelaran berdasarkan ranking individu, semua gelaran akan diumumkan di saluran server semasa pemain log masuk. Khasnya, pemain tempat pertama, Raja Tertinggi, akan diumumkan seluruh server semasa log masuk.  ',
		fmt_en = '2. The World Martial Arts Tournament will grant corresponding titles based on individual rankings. All titles will be announced in the server channel when players log in. Notably, the top player, Supreme King, will be broadcasted server-wide upon login.',
		fmt_in = '2. Turnamen Seni Bela Diri Dunia Terkuat akan memberikan gelar sesuai dengan peringkat individu, semua gelar akan diumumkan di saluran server saat pemain login. Khusus untuk pemain peringkat pertama, Raja Tertinggi, akan diumumkan ke seluruh server saat login.  ',
		fmt_th = '2. ศึกศิลปะการต่อสู้อันดับหนึ่งใต้หล้า จะมอบฉายาตามอันดับส่วนตัว โดยฉายาทั้งหมดจะประกาศในช่องเซิร์ฟเวอร์เมื่อผู้เล่นล็อกอิน โดยเฉพาะผู้ที่ได้อันดับ 1 จักรพรรดิสูงสุด จะมีการประกาศเซิร์ฟเวอร์ทั้งหมดเมื่อเข้าสู่เกม',
		fmt_ph = '2.Ang tournament ay magbibigay din ng titulo batay sa individual ranking, lahat ng titulo ay ipapahayag sa server chat kapag ang manlalaro ay nag-log in. Lalo na ang unang ranked player, Supreme King, ay ipapahayag sa buong server  ',
		fmt_vn = '2. Giải đấu Võ Thuật Đệ Nhất Thiên Hạ sẽ trao thưởng danh hiệu tương ứng dựa trên xếp hạng cá nhân, tất cả danh hiệu đều sẽ được thông báo trên kênh server khi người chơi đăng nhập. Đặc biệt, người chơi đạt hạng nhất, Chí Tôn Vương Giả, sẽ được phát sóng toàn server khi đăng nhập.'
	},
