	[129206] = {
		id = 129206,
		fmt = '4. Temporary star exchanges consume items; item costs vary depending on hero rarity and star level differences, please check details during the exchange.',
		fmt_ma = '4. Pertukaran sementara memerlukan bahan, bahan digunakan berbeza mengikut rare dan bintang hero, sila semak butiran semasa pertukaran.  ',
		fmt_en = '4. Temporary star exchanges consume items; item costs vary depending on hero rarity and star level differences, please check details during the exchange.',
		fmt_in = '4. Pertukaran sementara memerlukan konsumsi item, jumlah item yang dikonsumsi bisa berbeda tergantung kelangkaan dan jumlah bintang hero, silakan periksa detailnya saat pertukaran.  ',
		fmt_th = '4. การแลกเปลี่ยนชั่วคราวต้องใช้ไอเทม ไอเทมที่ใช้จะเปลี่ยนตามความหายากและจำนวนดาวของฮีโร่ กรุณาตรวจสอบรายละเอียดในระหว่างแลกเปลี่ยน',
		fmt_ph = '4.Ang temporary swap ay nangangailangan ng items; ang required items ay nag-iiba depende sa rarity at star level, pakisuri ang detalye habang nag-swap  ',
		fmt_vn = '4.Trao đổi tạm thời cần tiêu hao vật phẩm, vật phẩm tiêu hao khi trao đổi giữa các độ hiếm và số sao khác nhau có thể thay đổi, hãy kiểm tra chi tiết trong quá trình trao đổi.'
	},
	[129207] = {
		id = 129207,
		fmt = '5. During the exchange event, hero upgrades that consume items (skill upgrades, Z-Awakening, etc.) after star upgrades will not have items refunded or reset after the event ends; materials will remain locked until the required star level is reached again.',
		fmt_ma = '5. Semasa acara pertukaran berlangsung, aktiviti menaik taraf hero yang menggunakan bahan (naik tahap skill, Z-Awakening, dll) selepas naik bintang tidak akan dipulangkan atau diset semula selepas acara berakhir, bahan akan dikunci hingga mencapai tahap bintang semula.  ',
		fmt_en = '5. During the exchange event, hero upgrades that consume items (skill upgrades, Z-Awakening, etc.) after star upgrades will not have items refunded or reset after the event ends; materials will remain locked until the required star level is reached again.',
		fmt_in = '5. Selama event pertukaran berlangsung, semua aktivitas pengembangan yang mengonsumsi item (upgrade skill, Z-Awakening, dll.) setelah meningkatkan bintang hero tidak akan mengembalikan item atau direset setelah event berakhir, melainkan akan terkunci hingga memenuhi jumlah bintang yang dibutuhkan.  ',
		fmt_th = '5. ในช่วงอีเวนต์แลกเปลี่ยน กิจกรรมพัฒนาฮีโร่ที่ใช้ไอเทม (อัปเกรดสกิล, Z-Awakening ฯลฯ) หลังจากเพิ่มดาว จะไม่สามารถขอคืนไอเทมหรือรีเซ็ตได้หลังอีเวนต์สิ้นสุด ไอเทมจะถูกล็อกไว้จนกว่าจะถึงระดับดาวที่กำหนด  ',
		fmt_ph = '5.Habang active ang swap event, items consumed sa upgrading (skills, Z-Awakening, etc.) ay hindi ire-refund o i-reset pagkatapos ng event; ang mga ito ay naka-lock hanggang maabot muli ang kinakailangang star  ',
		fmt_vn = '5. Trong thời gian diễn ra sự kiện trao đổi, các hoạt động bồi dưỡng tiêu hao vật phẩm (nâng cấp kỹ năng, Z-Awakening, v.v.) sau khi tăng sao cho tướng sẽ không được hoàn trả vật phẩm hoặc thiết lập lại sau khi sự kiện kết thúc, mà sẽ bị khóa lại cho đến khi đạt lại số sao yêu cầu.'
	},
	[129208] = {
		id = 129208,
		fmt = '6. During the exchange period, heroes cannot be further starred up, used as materials for other upgrades (such as soul awakening), dismantled, or counted towards related quest conditions (such as achievements or medal quests requiring specific star levels).',
		fmt_ma = '6. Semasa tempoh pertukaran, hero tidak boleh naik bintang, tidak boleh digunakan sebagai bahan untuk aktiviti lain (contoh awakening jiwa) atau dibubarkan, juga tidak dikira sebagai syarat untuk misi berkaitan (contoh pencapaian atau medal memerlukan hero bintang tertentu).  ',
		fmt_en = '6. During the exchange period, heroes cannot be further starred up, used as materials for other upgrades (such as soul awakening), dismantled, or counted towards related quest conditions (such as achievements or medal quests requiring specific star levels).',
		fmt_in = '6. Selama pertukaran, hero tidak dapat dinaikkan bintang, tidak dapat digunakan sebagai bahan untuk aktivitas pengembangan lain (misalnya awakening soul), tidak dapat diurai, dan tidak dihitung untuk menyelesaikan misi terkait (misalnya prestasi atau misi medal yang membutuhkan jumlah bintang tertentu).  ',
		fmt_th = '6. ระหว่างการแลกเปลี่ยน ฮีโร่จะไม่สามารถเพิ่มดาว, ใช้เป็นวัตถุดิบในการพัฒนาอื่น ๆ (เช่น ปลุกพลังจิตวิญญาณ), ย่อยสลาย หรือใช้ในการทำภารกิจที่เกี่ยวข้องกับดาวได้ (เช่น ความสำเร็จหรือภารกิจเหรียญที่ต้องการฮีโร่ดาวระดับหนึ่ง)  ',
		fmt_ph = '6.Habang naka-swap, ang hero ay hindi maaaring i-upgrade ng star, gamitin bilang material sa iba pang activities (hal. awakening) o i-dismantle, at hindi mabibilang para sa quest requirements  ',
		fmt_vn = '6. Trong thời gian trao đổi, tướng không thể tăng sao, không thể dùng làm nguyên liệu cho các hoạt động bồi dưỡng khác (ví dụ như thức tỉnh linh hồn) và phân giải, cũng không được tính là điều kiện để hoàn thành các nhiệm vụ liên quan (ví dụ như thành tựu hoặc nhiệm vụ huy chương yêu cầu tướng đạt một số sao nhất định).'
	},
	[129209] = {
		id = 129209,
		fmt = '#C0xF76B45#The Temporary Star Exchange feature only applies to certain hero rarities. Heroes that have undergone soul awakening cannot use this feature. Before finalizing the exchange, there will be a preview of the star effects. Please review carefully.',
		fmt_ma = '#C0xF76B45#Fungsi Pertukaran Sementara bintang ini hanya terpakai untuk sesetengah rare tertentu, hero yang telah awakening jiwa tidak boleh guna fungsi ini. Sebelum tukar rasmi, akan ada pratonton kesan bintang, sila semak dengan teliti.  ',
		fmt_en = '#C0xF76B45#The Temporary Star Exchange feature only applies to certain hero rarities. Heroes that have undergone soul awakening cannot use this feature. Before finalizing the exchange, there will be a preview of the star effects. Please review carefully.',
		fmt_in = '#C0xF76B45#Fitur Pertukaran Bintang Sementara saat ini hanya berlaku untuk beberapa tingkat kelangkaan tertentu dari hero, dan hero yang sudah awakening soul tidak dapat menggunakan fitur ini. Sebelum melakukan pertukaran resmi, akan ada masa pratinjau efek bintang, harap perhatikan dengan cermat.  ',
		fmt_th = '#C0xF76B45#ฟังก์ชันแลกเปลี่ยนดาวชั่วคราวจะใช้ได้กับฮีโร่ระดับความหายากบางระดับเท่านั้น และฮีโร่ที่ปลุกพลังจิตวิญญาณแล้วจะไม่สามารถใช้ฟังก์ชันนี้ได้ ก่อนแลกจริงจะมีช่วงเวลาให้ดูตัวอย่างเอฟเฟกต์ดาว กรุณาตรวจสอบอย่างละเอียด',
		fmt_ph = '#C0xF76B45#Ang Temporary Star Swap ay para lamang sa ilang rare na hero, at mga hero na awakened ay hindi pwedeng gamitin sa feature na ito. Bago opisyal na i-swap, may preview time para suriin  ',
		fmt_vn = '#C0xF76B45#Tính năng Đổi Sao Tạm Thời hiện chỉ áp dụng cho một số bậc hiếm nhất định của tướng, ngoài ra các tướng đã thức tỉnh linh hồn sẽ không thể sử dụng tính năng này. Trước khi tiến hành đổi chính thức, sẽ có một khoảng thời gian để xem trước hiệu ứng sao, vui lòng xem xét kỹ.'
	},
	[129231] = {
		id = 129231,
